"""
AI generation endpoint — uses the project title + corpus mix to generate
premise, themes, arcs, chapter skeleton, character list, etc.
Reads API key from ~/.noveltea-engine/config.json.
"""
import contextlib
import contextvars
import json
import re
import random
import subprocess
import sys
from pathlib import Path
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel
from typing import Optional
from config import CORPUS_PATH, NOVELS_PATH, CHARACTER_DNA_PATH


# ── Error log ─────────────────────────────────────────────────────────────
# The packaged exe runs with no visible console, so CLI/agent failures were
# previously only surfaced as a truncated message in the API response and
# then lost. This gives every future "it failed, why?" a real answer.
_ERROR_LOG = Path.home() / ".noveltea-engine" / "errors.log"


def _log_error(context: str, detail: str):
    try:
        _ERROR_LOG.parent.mkdir(parents=True, exist_ok=True)
        import time as _t
        with open(_ERROR_LOG, "a", encoding="utf-8") as f:
            f.write(f"[{_t.strftime('%Y-%m-%d %H:%M:%S')}] {context}\n{detail}\n{'-'*70}\n")
    except Exception:
        pass  # logging must never itself break the request

router = APIRouter()

CONFIG_FILE = Path.home() / ".noveltea-engine" / "config.json"


def _read_config() -> dict:
    """Tolerant config read — never raises. A concurrent settings save must not
    500 a generation request (config.json is replaced atomically, but stay safe)."""
    if not CONFIG_FILE.exists():
        return {}
    try:
        with open(CONFIG_FILE, encoding="utf-8-sig") as f:
            return json.load(f)
    except Exception:
        return {}


def _get_key(provider: str) -> str:
    return _read_config().get("api_keys", {}).get(provider, "")


def _get_generation_cfg() -> dict:
    return _read_config().get("generation", {})


def _get_models_cfg() -> dict:
    return _read_config().get("models", {})


# (The Gemini account/key pool itself -- which one is active, rotation -- lives in llm_client;
# see _gemini_lc() below. One pool for the app and the pipeline.)
def _is_gemini_quota_error(msg: str) -> bool:
    m = (msg or "").lower()
    return any(s in m for s in ("rate limit", "quota", "resource_exhausted", "429", "too many requests"))


def _qoder_token_pool() -> list:
    return _read_config().get("qoder_token_pool", []) or []


def _qoder_active_token_index() -> int:
    pool = _qoder_token_pool()
    if not pool:
        return -1
    return _read_config().get("qoder_token_pool_index", 0) % len(pool)


def _qoder_active_token() -> str:
    pool = _qoder_token_pool()
    idx = _qoder_active_token_index()
    if idx < 0:
        return ""
    return pool[idx].get("token", "")


def _qoder_rotate_token():
    """Advance the pool index — used on a billing/quota failure so the NEXT
    call tries a different pooled token, same pattern as the Gemini key pool."""
    cfg = _read_config()
    pool = cfg.get("qoder_token_pool", []) or []
    if len(pool) < 2:
        return
    cfg["qoder_token_pool_index"] = (cfg.get("qoder_token_pool_index", 0) + 1) % len(pool)
    import os as _os2
    tmp = CONFIG_FILE.with_suffix(".json.tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(cfg, f, indent=2)
    _os2.replace(tmp, CONFIG_FILE)


def _is_qoder_billing_error(msg: str) -> bool:
    m = (msg or "").lower()
    return any(s in m for s in ("forbidden", "code\":\"112\"", "pricing", "quota", "429",
                                 "too many requests", "insufficient", "no active plan"))


def _kimi_model() -> str:
    """Model alias for -m — confirmed real aliases (kimi-code/docs/en/kimi-code/
    models.html): k3 (flagship, 1M context), kimi-for-coding (K2.7 Code, 256k),
    kimi-for-coding-highspeed (6x speed / 3x quota). Default to the standard
    coding model, not the priciest flagship."""
    m = (_get_models_cfg() or {}).get("kimi", "")
    return m or "kimi-for-coding"


KIMI_NVIDIA_DEFAULT_MODEL = "moonshotai/kimi-k3"


def _kimi_nvidia_model() -> str:
    """The NVIDIA model the Kimi engine runs (Settings → Kimi K3 Model). models.kimi can still
    hold an old Kimi Code CLI alias (k3, kimi-for-coding…) — those aren't NVIDIA ids."""
    m = (_get_models_cfg() or {}).get("kimi", "") or ""
    return m if m.startswith("moonshotai/") else KIMI_NVIDIA_DEFAULT_MODEL


def _kimi_via_nvidia() -> bool:
    """Kimi K3 runs on NVIDIA's API with the same nvapi- key pool as Nemotron. The Kimi Code
    CLI (Moonshot's own account) is only the fallback when no NVIDIA key is pooled."""
    return bool(_nemotron_active_api_key())


