_FIELD_DECISION_INSTRUCTIONS = (
    "\n\nOutput ONLY a decision block in EXACTLY this format (valid JSON between the markers, nothing else at all):\n"
    "<<<DECISION>>>\n"
    '{"question": "one clear sentence", '
    '"options": [{"label": "short choice A", "description": "what this means for the story", "evidence": "which corpus novel/pattern from the CORPUS REFERENCE block above suggested this — name it"}, '
    '{"label": "short choice B", "description": "what this means for the story", "evidence": "..."}], '
    '"recommended": 0, "progress": "{PROGRESS_HINT}"}\n'
    "<<<END>>>\n"
    "recommended = 0-based index of the option YOU judge strongest. 2-3 genuinely different options. Keep each "
    "label under 10 words and each description to 1-2 complete sentences (under 250 characters) — they display "
    "in a small popup. evidence is REQUIRED and must name a REAL novel/pattern from the CORPUS REFERENCE block "
    "above — if an option isn't actually grounded in anything there, write \"author's own instinct\" instead of "
    "inventing a source."
)


class FieldInteractiveRequest(BaseModel):
    project_id: str
    field: str                          # "arcs" | "chapter_skeleton"
    session_id: Optional[str] = None
    choice: Optional[str] = None
    back: Optional[bool] = False         # rewind to the PREVIOUS question instead of advancing — no LLM call
    back_to: Optional[int] = None        # jump straight to this question index (0-based) instead of one step — no LLM call
    chapter_summaries: Optional[list] = None
    chapter_number: Optional[int] = None  # required for field == "dialogue_shaping"/"blueprint_enrichment"/"critique" — which chapter to interview about
    critique_text: Optional[str] = None   # required for field == "critique" — the author's free-text critique
    provider: Optional[str] = None
    force_pattern: Optional[bool] = False  # field == "chapter_skeleton" only — see _forced_pattern_for_chapter's
                                           # docstring: finds the best-matching corpus narrative pattern not yet
                                           # used in THIS project and guarantees it appears as one of the SCENE
                                           # STRUCTURE question's options, never silently written into the chapter
                                           # without the author choosing it.


@router.post("/field-interactive")
def field_interactive(req: FieldInteractiveRequest):
    """Interactive planning for arcs / chapter_skeleton: a short survey of
    pivotal A/B/other questions (one per arc, or 3 for a skeleton batch),
    then a single final generation honoring every answer."""
    key = (req.project_id, req.field)
    with _ACTIVE_GENERATIONS_LOCK:
        _ACTIVE_GENERATIONS.add(key)
    try:
        return _field_interactive_impl(req)
    except HTTPException:
        raise
    except Exception as e:
        import traceback
        _log_error("field_interactive", f"project={req.project_id} field={req.field}\n{traceback.format_exc()}")
        raise HTTPException(502, f"Interactive planning failed: {str(e)[:200]}")
    finally:
        with _ACTIVE_GENERATIONS_LOCK:
            _ACTIVE_GENERATIONS.discard(key)


class FieldInteractiveAbandonRequest(BaseModel):
    project_id: str
    field: str
    session_id: Optional[str] = None   # if known; otherwise abandons whatever session is live for (project_id, field)


@router.post("/field-interactive-abandon")
def field_interactive_abandon(req: FieldInteractiveAbandonRequest):
    """Real "Abandon" for an interactive survey/interview popup — before this
    existed, the ONLY way to actually clear a stuck or unwanted session was
    to restart the whole app (confirmed live: /api/generate/abandon only
    clears an ACTIVELY RUNNING generation's process/dedup-lock, it has no
    concept of a session sitting idle with an unanswered pending question —
    deleting the on-disk mirror alone doesn't help either, since a running
    process still holds the session in its in-memory _INTERACTIVE_SESSIONS
    dict and will just re-persist it on the next request). This endpoint
    does all three things /abandon-plus-delete-file didn't: kills any
    genuinely in-flight LLM call for this (project_id, field), clears the
    dedup lock, AND removes the session from _INTERACTIVE_SESSIONS itself
    (not just its disk mirror) — so the very next Interactive click starts
    genuinely fresh instead of resuming the abandoned question."""
    key = (req.project_id, req.field)
    killed = _abort_active_proc(key)
    with _ACTIVE_GENERATIONS_LOCK:
        _ACTIVE_GENERATIONS.discard(key)
    removed_sid = None
    with _INTERACTIVE_LOCK:
        if req.session_id and req.session_id in _INTERACTIVE_SESSIONS:
            del _INTERACTIVE_SESSIONS[req.session_id]
            removed_sid = req.session_id
        else:
            # No session_id given (or it's already gone) — fall back to
            # matching by (project_id, field), same lookup _field_interactive_impl
            # itself uses to find "the" live session for this button.
            for sid, s in list(_INTERACTIVE_SESSIONS.items()):
                if s.get("kind") == "field" and s.get("project_id") == req.project_id and s.get("field") == req.field:
                    del _INTERACTIVE_SESSIONS[sid]
                    removed_sid = sid
                    break
    if removed_sid:
        _delete_interactive_session_file(removed_sid)
    if removed_sid or killed:
        _progress_log(req.project_id, f"INTERACTIVE {req.field}: abandoned by user"
                                      + (" — subprocess killed" if killed else ""), "warn")
    return {"ok": True, "removed": bool(removed_sid), "process_killed": killed}


class ChapterInteractiveAbandonRequest(BaseModel):
    project_id: str
    chapter_number: int
    session_id: Optional[str] = None   # if known; otherwise abandons whatever session is live for (project_id, chapter_number)


@router.post("/chapter-interactive-abandon")
def chapter_interactive_abandon(req: ChapterInteractiveAbandonRequest):
    """Same real "Abandon" as /field-interactive-abandon, for the scene-by-scene
    chapter-WRITING interactive session (_chapter_interactive_impl) — that flow
    had no equivalent at all. Confirmed live 2026-09-30: a session started before
    a prompt-content fix was deployed keeps resuming with its own stale, already-
    persisted base_prompt forever — there was no way to discard it and start
    genuinely fresh short of restarting the whole app. Chapter sessions have no
    "kind" key (only field-interview sessions set "kind": "field" — see the
    resume-scan's own `es.get("kind") != "field"` filter above), and are matched
    by (project_id, chapter_number) instead of (project_id, field); the dedup/
    abort key is the same (project_id, "interactive") every chapter-interactive
    call site already uses."""
    key = (req.project_id, "interactive")
    killed = _abort_active_proc(key)
    with _ACTIVE_GENERATIONS_LOCK:
        _ACTIVE_GENERATIONS.discard(key)
    removed_sid = None
    with _INTERACTIVE_LOCK:
        if req.session_id and req.session_id in _INTERACTIVE_SESSIONS:
            del _INTERACTIVE_SESSIONS[req.session_id]
            removed_sid = req.session_id
        else:
            for sid, s in list(_INTERACTIVE_SESSIONS.items()):
                if (s.get("kind") != "field" and s.get("project_id") == req.project_id
                        and s.get("chapter_number") == req.chapter_number):
                    del _INTERACTIVE_SESSIONS[sid]
                    removed_sid = sid
                    break
    if removed_sid:
        _delete_interactive_session_file(removed_sid)
    if removed_sid or killed:
        _progress_log(req.project_id, f"INTERACTIVE Ch.{req.chapter_number}: abandoned by user"
                                      + (" — subprocess killed" if killed else ""), "warn")
    return {"ok": True, "removed": bool(removed_sid), "process_killed": killed}


def _field_interactive_impl(req: FieldInteractiveRequest):
    _prune_interactive_sessions()
    cfg = _FIELD_INTERACTIVE_CONFIG.get(req.field)
    if cfg is None and _is_system_field(req.field):
        # Generic Systems-tab fallback (see "_systems_generic" in
        # _FIELD_INTERACTIVE_CONFIG) — no per-engine entry exists for these
        # (there are 10 built-in ones plus any number of author-defined
        # custom_* engines, too many to hand-write individually), so every
        # one of them shares one config with {SYSTEM_LABEL} substituted for
        # a human-readable name derived from the field key. A character power
        # system's field looks like "character_power_system::Lu Jian" — label
        # it with the character's name rather than the raw key.
        generic = _FIELD_INTERACTIVE_CONFIG["_systems_generic"]
        if req.field.startswith("character_power_system::"):
            system_label = f"{req.field.split('::', 1)[1]}'s Power System"
        else:
            system_label = req.field.removeprefix("custom_").replace("_", " ").strip().title() or req.field
        cfg = {**generic, "intro": generic["intro"].replace("{SYSTEM_LABEL}", system_label)}
    if cfg is None:
        raise HTTPException(400, f"Field '{req.field}' does not support interactive planning "
                                  f"({', '.join(k for k in _FIELD_INTERACTIVE_CONFIG.keys() if not k.startswith('_'))}, "
                                  f"or any Systems engine).")
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)

    gen_cfg = _get_generation_cfg()
    provider = req.provider or gen_cfg.get("default_provider", "anthropic")
    api_key = _get_key(provider)
    model = _get_models_cfg().get(provider, "")
    decision_instr = _FIELD_DECISION_INSTRUCTIONS.replace("{PROGRESS_HINT}", cfg["progress_hint"])
    using_cli = not api_key
    effective_provider = f"{_get_agent_engine()}-cli (subscription)" if using_cli else provider
    _progress_log(req.project_id, f"INTERACTIVE {req.field}: 🤖 using {_model_label(effective_provider, provider, model, using_cli)}")

    # ── start (or RESUME an interrupted survey) ──
    if not req.session_id:
        with _INTERACTIVE_LOCK:
            for esid, es in list(_INTERACTIVE_SESSIONS.items()):
                # Same chapter too, when the request names one — chapter-scoped
                # interviews (dialogue_shaping, blueprint_enrichment, critique)
                # used to match on project+field alone, so starting one for
                # chapter 5 resumed chapter 3's pending question, or — when chapter
                # 3's session had no pending question — fell through to the
                # delete below and destroyed it. chapter_skeleton requests carry no
                # chapter (the server picks it), so they still match as before.
                if (es.get("kind") == "field" and es.get("project_id") == req.project_id
                        and es.get("field") == req.field
                        and (req.chapter_number is None or es.get("chapter_number") == req.chapter_number)):
                    # For "critique" specifically: a leftover session's
                    # base_prompt was built from THIS PROJECT'S CHAPTER TEXT
                    # AT THE TIME IT STARTED — if the author has since typed
                    # a genuinely different critique (or the chapter itself
                    # changed since, e.g. from an earlier fix), blindly
                    # resuming silently serves a stale question grounded in
                    # old content and DISCARDS the new critique text entirely
                    # (confirmed live: clicking Critique with fresh text
                    # returned an old, unrelated pending question from a
                    # prior attempt with zero acknowledgment of the new
                    # input). Only resume when the critique text actually
                    # matches what this session was already working on;
                    # otherwise fall through to the delete-and-restart path
                    # below so a new session builds fresh from the CURRENT
                    # chapter file and the CURRENT critique text.
                    if (req.field == "critique" and es.get("pending")
                            and (req.critique_text or "").strip() != (es.get("critique_text") or "").strip()):
                        _progress_log(req.project_id,
                                      f"CRITIQUE: new critique text differs from the pending session — starting fresh instead of resuming")
                    elif es.get("pending"):
                        es["touched"] = _time.time()
                        _progress_log(req.project_id,
                                      f"INTERACTIVE {req.field}: resumed in-progress survey "
                                      f"({es['pending'].get('answered', 0)} answers already recorded)")
                        return {**es["pending"], "session_id": esid, "resumed": True}
                    if es.get("in_flight"):
                        # A request for THIS session (next question, or the
                        # final generation — which alone can take several
                        # minutes) is still being processed right now. There is
                        # no pending question yet because the answer/round in
                        # progress hasn't come back — that is NOT the same as
                        # abandoned. Previously this fell through to the delete
                        # below and silently discarded every answer recorded so
                        # far (confirmed: cost a real 10-question arc interview
                        # its answers when the author re-clicked Interactive
                        # while the final arc generation was still running).
                        age = _time.time() - es.get("touched", 0)
                        if age < 900:   # generous vs. the 600s max LLM call timeout
                            return {"ok": True, "done": False, "in_flight": True, "session_id": esid,
                                    "answered": len(es.get("qa") or []),
                                    "message": "Still working on your last answer — this can take a few minutes "
                                               "for the final step. Try again shortly; your answers are safe."}
                        # Stale beyond any plausible in-flight call — the
                        # process handling it is gone (crashed/restarted).
                        # Roll back THIS round only (undo the answer that
                        # triggered it, restore the question it answered) so
                        # nothing beyond that one in-flight round is lost —
                        # never silently drop the whole interview.
                        rollback = es.get("_rollback")
                        if rollback:
                            es["qa"] = es["qa"][:rollback["qa_len_before"]]
                            es["pending"] = rollback["pending"]
                            es["in_flight"] = False
                            es.pop("_rollback", None)
                            if es["pending"]:
                                _persist_interactive_session(esid, es)
                                es["touched"] = _time.time()
                                _progress_log(req.project_id,
                                              f"INTERACTIVE {req.field}: recovered after an interrupted round "
                                              f"({len(es['qa'])} answers safe)")
                                return {**es["pending"], "session_id": esid, "resumed": True}
                    del _INTERACTIVE_SESSIONS[esid]
                    _delete_interactive_session_file(esid)
                    break
        arc_ctx = None
        sk_ctx = None
        forced_pattern = None
        # Cleared BEFORE prompt-building (not after) — _single_arc_context and
        # _dialogue_shaping_interview_prompt both log their own SEMANTIC SEARCH
        # entries while building base_prompt; clearing afterward silently wiped
        # them before the author ever saw them (confirmed live: the log showed
        # only the "interviewing you" line, no trace the search had run).
        _progress_clear(req.project_id)
        if req.field == "arcs":
            # Scoped to ONE arc (the next one, same default as /arc) — not the
            # whole-story _build_prompt used by every other interactive field.
            arc_ctx = _single_arc_context(project, project_id=req.project_id)
            base_prompt = arc_ctx["base_prompt"]
            intro = cfg["intro"].replace("{ARC_LABEL}", f"Arc {arc_ctx['idx'] + 1}")
        elif req.field == "chapter_skeleton":
            # Scoped to ONE chapter (the next unplanned one, same default as
            # /skeleton) — was previously falling through to the generic
            # branch below and using the whole-story batch _build_prompt
            # (the OLD 20-at-once schema), which is why its intro talked
            # about "this batch of chapters" instead of one. Shares the
            # exact same rich context (arc contract, reveals owed, tension
            # curve position, chapter role, semantic search) as the direct
            # Generate button via _single_chapter_skeleton_context, so the
            # interview and the one-shot button never silently drift apart.
            sk_ctx = _single_chapter_skeleton_context(project, chapter=req.chapter_number, project_id=req.project_id,
                                                      regenerate=True)   # regenerate=True: an interview session
                                                      # replans this chapter deliberately; the "already planned"
                                                      # guard is for the one-shot button's accidental-overwrite
                                                      # protection, not relevant once the author has chosen to
                                                      # interview about this specific chapter.
            base_prompt = sk_ctx["base_prompt"]
            intro = cfg["intro"]
            forced_pattern = None
            if req.force_pattern:
                _fp_arc = sk_ctx.get("arc") or {}
                _fp_query = f"{_fp_arc.get('label','')} {_fp_arc.get('description','')} {' '.join(sk_ctx.get('owed') or [])}".strip()
                forced_pattern = _forced_pattern_for_chapter(_fp_query, project, project_id=req.project_id)
                if forced_pattern:
                    _fp_marker = f"[Pattern: {forced_pattern['pattern_id']}]"
                    intro += (
                        f"\n\nFORCED PATTERN (author enabled 'Force Pattern' for this interview): the SCENE "
                        f"STRUCTURE question's options MUST include one option that builds this chapter's scenes "
                        f"around this specific corpus pattern — do not merely mention it, actually shape the "
                        f"scene structure to enact it:\n"
                        f"  [{forced_pattern['novel_title']}]: {forced_pattern['text'][:300]}\n"
                        + (f"  Generation guidance: {forced_pattern['gen_guidance']}\n" if forced_pattern.get('gen_guidance') else "")
                        + f"That option's label MUST end with the exact literal text \"{_fp_marker}\" (verbatim, so "
                          f"the app can detect if the author picks it) — e.g. \"Escalate through overlapping crowd "
                          f"reactions {_fp_marker}\". Every OTHER option's label must NOT contain that marker text."
                    )
        elif req.field == "dialogue_shaping":
            if not req.chapter_number:
                raise HTTPException(400, "Dialogue Shaping requires chapter_number.")
            gen_path = CORPUS_PATH / "generated" / req.project_id / f"ch{req.chapter_number:03d}_generated.txt"
            if not gen_path.exists():
                raise HTTPException(404, f"Chapter {req.chapter_number} has not been written yet.")
            base_prompt = _dialogue_shaping_interview_prompt(project, gen_path.read_text(encoding="utf-8"), req.chapter_number, project_id=req.project_id)
            intro = cfg["intro"]
        elif req.field == "blueprint_enrichment":
            if not req.chapter_number:
                raise HTTPException(400, "Blueprint Enrichment requires chapter_number.")
            gen_path = CORPUS_PATH / "generated" / req.project_id / f"ch{req.chapter_number:03d}_generated.txt"
            if not gen_path.exists():
                raise HTTPException(404, f"Chapter {req.chapter_number} has not been written yet.")
            chapter_text = gen_path.read_text(encoding="utf-8")
            _progress_log(req.project_id, f"BLUEPRINT ENRICHMENT: ch{req.chapter_number} — reading chapter, deciding what to check…")
            findings = _blueprint_enrichment_find_queries(req.project_id, chapter_text, req.chapter_number)
            _progress_log(req.project_id, f"BLUEPRINT ENRICHMENT: {len(findings)} candidate finding(s) — searching…")
            search_results = _blueprint_enrichment_search_findings(req.project_id, findings)
            _progress_log(req.project_id, f"BLUEPRINT ENRICHMENT: {len(search_results)} finding(s) with a genuine match", "success" if search_results else "info")
            base_prompt = _blueprint_enrichment_interview_prompt(req.project_id, chapter_text, req.chapter_number, search_results)
            intro = cfg["intro"]
        elif req.field == "critique":
            if not req.chapter_number:
                raise HTTPException(400, "Critique requires chapter_number.")
            if not (req.critique_text or "").strip():
                raise HTTPException(400, "Critique requires critique_text — write what you want changed first.")
            gen_path = CORPUS_PATH / "generated" / req.project_id / f"ch{req.chapter_number:03d}_generated.txt"
            if not gen_path.exists():
                raise HTTPException(404, f"Chapter {req.chapter_number} has not been written yet.")
            chapter_text = gen_path.read_text(encoding="utf-8")
            _progress_log(req.project_id, f"CRITIQUE: ch{req.chapter_number} — reading your critique, searching corpus + Blueprint, proposing fixes…")
            base_prompt = _critique_find_options(chapter_text, req.chapter_number, req.critique_text, project_id=req.project_id)
            intro = cfg["intro"]
        else:
            # Was hardcoded to None unconditionally — every interactive field
            # routed through this branch (chapter_skeleton, characters, world,
            # every system field, ...) NEVER saw the latest written chapter,
            # even though _build_prompt's own "characters" branch explicitly
            # prioritizes it and the ONE-SHOT (non-interactive) Generate/Update
            # button for the same fields already loads it correctly (see
            # _generate_field_impl's matching lookup). Confirmed live: a
            # project with real written chapters and no chapter_summaries.json
            # (chapters written before/without using the planning tools) got
            # zero written-chapter grounding on every interactive field.
            latest_chapter = None
            written_nums = _list_written_chapters(req.project_id)
            if written_nums:
                latest_num = written_nums[-1]
                try:
                    latest_text = (CORPUS_PATH / "generated" / req.project_id
                                  / f"ch{latest_num:03d}_generated.txt").read_text(encoding="utf-8")
                    latest_chapter = {"number": latest_num, "text": latest_text}
                except Exception:
                    latest_chapter = None
            base_prompt = _build_prompt(req.field, project, [], req.chapter_summaries, latest_chapter)
            # Characters/Chapter Skeleton (and any other field here) have no
            # natural "chapter range" the way an arc does — full text of the
            # most recent few written chapters, auto-summaries for the rest.
            # Same _written_chapters_block used by the arc interview; here it
            # ALSO covers chapters chapter_summaries.json might be missing.
            if req.field in ("chapter_skeleton", "characters"):
                written_block = _written_chapters_block(req.project_id, label=req.field)
                if written_block:
                    base_prompt += ("\n\n" + written_block
                                    + "\n\nREVERSE-ENGINEER, DON'T INVENT: the WRITTEN CHAPTERS block above shows "
                                      "what's actually been written — ground your questions and every option in what "
                                      "those chapters actually show, not a fresh invention that contradicts them. "
                                      "Where planning and prose disagree, the prose wins.")
            # No per-request grep_mode on FieldInteractiveRequest — falls back
            # to the Settings default, same as every other interactive field.
            # top_k=12 when that default is agentic, matching every other
            # agentic call site now.
            _interactive_grep_mode = _resolve_grep_mode(None)
            semantic_block = _semantic_corpus_block(_semantic_query_for_field(req.field, project),
                                                    top_k=12 if _interactive_grep_mode == "agentic" else 6,
                                                    label=req.field, project_id=req.project_id,
                                                    category=_FIELD_SEMANTIC_CATEGORY.get(req.field), also_unfiltered=True)
            if semantic_block:
                base_prompt += "\n\n" + semantic_block
            # Same Blueprint-search wiring as the regular Generate/Update path
            # (_generate_field_impl) — "world" is a system field (its own
            # dedicated interactive wizard, see _FIELD_INTERACTIVE_CONFIG) so
            # without this it would silently miss saved Blueprint grounding
            # that every other system field's interactive button now gets.
            # _SYSTEM_FIELDS_PLUS_WORLD (not the plain _is_system_field check
            # used elsewhere) since world belongs here specifically — its own
            # non-interactive handling in _generate_field_impl deliberately
            # excludes it from that path's is_system_field test instead.
            if (req.field in _SYSTEM_FIELDS_PLUS_WORLD or req.field.startswith("custom_")
                    or req.field.startswith("character_power_system::")):
                blueprint_block = _semantic_blueprint_block(_semantic_query_for_field(req.field, project),
                                                            top_k=12 if _interactive_grep_mode == "agentic" else 6,
                                                            label=req.field, project_id=req.project_id)
                if blueprint_block:
                    base_prompt += "\n\n" + blueprint_block
            intro = cfg["intro"]
            # "characters" specifically: base_prompt (via _build_prompt) already
            # includes the EXISTING CAST block listing every saved character —
            # tell the interviewer explicitly not to re-interview any of them.
            # Without this, a click on Interactive re-asked about characters
            # already fully specified (core_belief/speech_style/etc. already
            # set) instead of spending its question budget on what's actually
            # missing — new characters the written chapters introduced, or
            # gaps in the existing cast's fields.
            if req.field == "characters" and (project.get("character_list") or []):
                intro += (
                    "\n\nDO NOT RE-INTERVIEW EXISTING CHARACTERS: the EXISTING CAST block above lists characters "
                    "already fully specified — do not ask questions whose only purpose is to re-derive a trait "
                    "one of them already has. Spend your questions on: (1) any NEW named character the written "
                    "chapters introduced that isn't in the existing cast yet, (2) a field an existing character "
                    "is genuinely missing or left thin (e.g. no banter_style, a one-word core_belief), or (3) a "
                    "real contradiction between an existing character's saved traits and how they actually "
                    "appear in the written chapters. If the existing cast is already complete and consistent "
                    "with the chapters, say so and finish early rather than inventing filler questions."
                )
        # Applies to EVERY interactive field uniformly (arcs, dialogue_shaping,
        # blueprint_enrichment, world, every system field, etc.) — one
        # insertion point instead of hand-editing each field's own intro. See
        # _pacing_discipline_block's docstring for the author complaint this
        # fixes: interview questions/recommendations kept resolving mysteries,
        # revealing full backstory, or closing threads far too early relative
        # to how much story is actually left (chapter_number for the
        # chapter-scoped fields, chapters_written otherwise).
        base_prompt += "\n\n" + _pacing_discipline_block(project, req.chapter_number)
        # Author Intent (recurring_themes/strategy_notes, part of
        # _author_profile_block) was already wired into direct chapter
        # generation and the "arcs" interview (via _single_arc_context) but
        # NOT into dialogue_shaping/blueprint_enrichment or any of the
        # generic system-field interviews (world, power_levels, techniques,
        # relationships, encounters, etc.) — confirmed live: _build_prompt,
        # which the generic `else` branch above uses, never calls
        # _author_profile_block at all. An interviewer with no idea what the
        # author's own strategy notes/recurring themes ARE is more likely to
        # recommend something off the author's actual intent, including
        # over-revealing early — closing that gap here, skipping "arcs"
        # which already has it to avoid duplicating the block in the prompt.
        if req.field != "arcs":
            author_block = _author_profile_block(project)
            if author_block:
                base_prompt += "\n\n" + author_block
        import uuid as _uuid
        sid = _uuid.uuid4().hex
        session = {"kind": "field", "project_id": req.project_id, "field": req.field,
                   "base_prompt": base_prompt, "intro": intro, "arc_ctx": arc_ctx, "qa": [], "last_question": None,
                   "chapter_number": req.chapter_number,
                   # target_t (this chapter's position on its arc's tension
                   # curve) — only set for field == "chapter_skeleton", carried
                   # through to the finish path so it can run the same
                   # _skeleton_plan_check_warnings the one-shot button uses,
                   # instead of the interview silently skipping that check.
                   "sk_target_t": (sk_ctx or {}).get("target_t"),
                   # The actual chapter number _single_chapter_skeleton_context picked
                   # (the next unplanned one, unless req.chapter_number overrode it) —
                   # req.chapter_number itself is never sent by the chapter_skeleton
                   # interview's own UI (only dialogue_shaping/blueprint_enrichment/
                   # critique require it), so without this the finish step has no
                   # chapter number to build this chapter's _skeleton_record_schema
                   # from, or to fall back on if the model's response omits one.
                   "sk_chapter": (sk_ctx or {}).get("chapter"),
                   # The pattern _forced_pattern_for_chapter picked for this
                   # session (None if force_pattern wasn't set, search failed,
                   # or every candidate was already used) — carried through so
                   # the finish path can check whether the author's actual
                   # chosen option was the forced one (see the
                   # "FORCED PATTERN: <id>" evidence marker) and, if so,
                   # record it into project["used_corpus_patterns"].
                   "forced_pattern": forced_pattern,
                   # Only meaningful for field == "critique" — the author's
                   # original free-text critique, carried through the whole
                   # session so _critique_interactive_finish can distill it
                   # into a standing rule once the interview concludes.
                   "critique_text": req.critique_text,
                   # history[i] = the pending payload shown when qa had length i —
                   # lets "Back" rewind to a prior question for free (no LLM call).
                   "history": [],
                   "chapter_summaries": req.chapter_summaries, "touched": _time.time()}
        with _INTERACTIVE_LOCK:
            _INTERACTIVE_SESSIONS[sid] = session
        _progress_log(req.project_id, f"INTERACTIVE {req.field}: interviewing you before generating…")
        raw = _call_llm(base_prompt + "\n\n" + intro + decision_instr, provider, model, api_key, timeout=300,
                        abort_key=(req.project_id, req.field))
        return _field_interactive_handle(sid, session, raw, cfg, provider, model, api_key,
                                         project, project_file, decision_instr)

    # ── continue ──
    with _INTERACTIVE_LOCK:
        session = _INTERACTIVE_SESSIONS.get(req.session_id)
    if session is None or session.get("kind") != "field":
        raise HTTPException(404, "Interactive planning session not found or expired — start a new one.")

    # ── back: rewind to the previous question, or jump straight to any
    # earlier one via back_to (a breadcrumb click) — either way, no LLM call,
    # just truncating qa and re-serving that question from history. ──
    if req.back or req.back_to is not None:
        history = session.get("history") or []
        qa = session.get("qa") or []
        if not qa:
            raise HTTPException(400, "Already at the first question — nothing earlier to go back to.")
        target = req.back_to if req.back_to is not None else len(qa) - 1
        if target < 0 or target >= len(qa):
            raise HTTPException(400, f"Can't jump to question {target + 1} — only {len(qa)} question(s) answered so far.")
        del qa[target:]
        idx = len(qa)
        if idx >= len(history):
            raise HTTPException(500, "Lost the earlier question's history — cannot go back further.")
        payload = history[idx]
        session["pending"] = payload
        session["last_question"] = payload.get("question", "")
        session["touched"] = _time.time()
        _persist_interactive_session(req.session_id, session)
        _progress_log(req.project_id, f"INTERACTIVE {req.field}: went back to question {idx + 1} — pick a different answer")
        return {**payload, "session_id": req.session_id, "went_back": True}

    if not (req.choice or "").strip():
        raise HTTPException(400, "A choice is required to continue.")
    session["touched"] = _time.time()
    session["qa"].append({"q": session.get("last_question") or "?", "a": req.choice.strip()})
    _prev_pending = session.pop("pending", None)   # answered — no longer pending (restored on failure below)
    # Marks the window between "answered" and "next question/final result
    # ready" — the resume-scan above treats this differently from a truly
    # abandoned session (see the in_flight branch there). _rollback carries
    # enough to undo THIS round (the answer just appended + the question it
    # answered) if the backend itself dies mid-call — persisted to disk so
    # the rollback survives a crash, not just an in-process failure.
    session["in_flight"] = True
    session["_rollback"] = {"qa_len_before": len(session["qa"]) - 1, "pending": _prev_pending}
    _persist_interactive_session(req.session_id, session)

    answers_block = "\n".join(f"Q{i+1}: {qa['q']}\nAUTHOR'S ANSWER: {qa['a']}" for i, qa in enumerate(session["qa"]))
    n_answered = len(session["qa"])
    interview_done = n_answered >= cfg["max_questions"]

    # If the LLM call below fails (timeout, spending cap, …), UN-record the
    # answer so the user can retry the same choice without it double-counting
    # toward max_questions / duplicating in the answers block.
    try:
        if interview_done:
            _progress_log(req.project_id, f"INTERACTIVE {req.field}: interview complete ({n_answered} answers) — generating…")
            if req.field == "dialogue_shaping":
                # No JSON-field generation here — the interview's Q&A drives an
                # agentic chapter-file edit directly, applying exactly what the
                # author approved (see _dialogue_shaping_apply).
                return _dialogue_shaping_interactive_finish(req.session_id, session, project, project_file)
            if req.field == "blueprint_enrichment":
                # Same reasoning as dialogue_shaping above — the interview's
                # Q&A drives a chapter-file rewrite, not a JSON field save.
                return _blueprint_enrichment_interactive_finish(req.session_id, session, project, project_file)
            if req.field == "critique":
                # Same reasoning again — plus a second, separate step (see
                # _critique_interactive_finish) that tags and saves the
                # critique as a standing rule for future chapters.
                return _critique_interactive_finish(req.session_id, session, project, project_file)
            final_prompt = (
                session["base_prompt"]
                + f"\n\nAUTHOR INTERVIEW — these decisions are FINAL and must be honored exactly:\n{answers_block}\n\n"
                + "The interview is complete. Now produce the full output the original task asked for, honoring every "
                  "answer above. Output ONLY the JSON."
            )
            if req.field == "arcs":
                # session["base_prompt"] (built by _single_arc_context, shared with
                # the one-shot /arc endpoint) never includes the output schema —
                # the one-shot endpoint appends it separately after calling that
                # function. Without it here, the model free-styles its own key
                # names (e.g. "arc_title" instead of "label", a nested
                # chapter_range object instead of a flat chapters array),
                # producing a well-formed but unusable object every time —
                # deterministic, not a transient parse failure a retry can fix.
                final_prompt += f"\n\nOutput ONE JSON object matching EXACTLY this schema, no markdown fences:\n{_arc_record_schema()}"
            elif req.field == "chapter_skeleton":
                # Same reasoning as "arcs" above: session["base_prompt"] (built by
                # _single_chapter_skeleton_context, shared with the one-shot /skeleton
                # endpoint) never includes the output schema either — the one-shot
                # endpoint appends _skeleton_record_schema(ch) separately after calling
                # that function. Without it here the model free-styles its own key
                # names — confirmed live 2026-09-30: a real interview saved
                # "ending_hook"/"tension_curve"/"reveals_delivered_this_chapter" instead
                # of "hook"/"target_psychology.tension_curve"/"reveals", producing a
                # well-formed but thinner object the rest of the pipeline (scene
                # drafting, hard_constraints self-check, dialogue-density verification,
                # the edit UI) can't read at all — deterministic drift, not a transient
                # parse failure a retry would fix.
                final_prompt += f"\n\nOutput ONE JSON object matching EXACTLY this schema, no markdown fences:\n{_skeleton_record_schema(session.get('sk_chapter') or session.get('chapter_number') or 1)}"
            raw = _call_llm(final_prompt, provider, model, api_key, timeout=600,
                            abort_key=(req.project_id, req.field))
            if req.field == "chapter_skeleton":
                _skch = session.get("sk_chapter") or session.get("chapter_number") or 1
                raw, _ow = _skeleton_overlap_gate(raw, final_prompt, project, _skch, provider, model, api_key,
                                                  req.project_id, (req.project_id, req.field))
                session["_sk_gate_warnings"] = _ow
                raw = _skeleton_content_gate(raw, final_prompt, project, _skch,
                                             provider, model, api_key, req.project_id, (req.project_id, req.field))
                raw, _syw = _skeleton_systems_gate(raw, final_prompt, project, _skch, provider, model, api_key,
                                                   req.project_id, (req.project_id, req.field))
                session["_sk_gate_warnings"] = list(session.get("_sk_gate_warnings") or []) + _syw
            try:
                return _field_interactive_finish(req.session_id, session, raw, project, project_file)
            except Exception as first_err:
                # The final generation is the single biggest/most detailed
                # output any interactive session produces (a full arc honoring
                # 10 answers' worth of context, or a full character/world
                # array) — occasionally the model returns something that
                # doesn't parse (HTTPException from the arcs branch's own
                # validation, or a raw JSONDecodeError from _parse_json_from_text
                # for every other field). One silent retry before surfacing
                # the failure to the author covers most of these transient
                # misfires without them ever seeing it.
                detail = first_err.detail if isinstance(first_err, HTTPException) else str(first_err)
                _progress_log(req.project_id, f"INTERACTIVE {req.field}: retrying final generation once "
                                              f"({str(detail)[:100]})…", "warn")
                raw = _call_llm(final_prompt, provider, model, api_key, timeout=600,
                                abort_key=(req.project_id, req.field))
                return _field_interactive_finish(req.session_id, session, raw, project, project_file)

        _progress_log(req.project_id, f"INTERACTIVE {req.field}: answer {n_answered} recorded — next question…")
        # Re-search grounded in the answer JUST GIVEN — every corpus/pattern/
        # blueprint block in session["base_prompt"] was searched ONCE at
        # session start, from the chapter's static purpose/key_event/arc; it
        # never reflected what the author actually steers toward mid-
        # interview. For chapter_skeleton specifically (the field this was
        # built for — see the author's own request), the LAST answer is now
        # ALSO run through a fresh pattern search (category="pattern") and
        # Blueprint search (category="blueprint"), and both are attached to
        # the NEXT question's prompt — so a choice partway through the
        # interview can actually pull in genuinely relevant reference
        # material for what comes after, not just the chapter's starting
        # context. Best-effort: a search failure here never blocks the
        # interview from continuing (same silent-degrade discipline as every
        # other semantic block in this file).
        per_answer_block = ""
        if req.field == "chapter_skeleton" and session["qa"]:
            last_answer = _expand_choice_for_search(session["qa"][-1]["a"], _prev_pending)
            _pa_pattern = _semantic_pattern_block(last_answer, top_k=3, label="your last answer", project_id=req.project_id)
            _pa_blueprint = _semantic_blueprint_block(last_answer, top_k=3, label="your last answer", project_id=req.project_id)
            if _pa_pattern or _pa_blueprint:
                per_answer_block = (
                    "\n\nGROUNDED IN THE AUTHOR'S LAST ANSWER (fresh search on what they just chose — use this to "
                    "inform the NEXT question and its options where genuinely relevant; ignore it if it doesn't fit):\n"
                    + (f"\n{_pa_pattern}\n" if _pa_pattern else "")
                    + (f"\n{_pa_blueprint}\n" if _pa_blueprint else "")
                )
        next_prompt = (
            session["base_prompt"]
            + "\n\n" + session["intro"]
            + f"\n\nANSWERS SO FAR — honor these as fixed decisions:\n{answers_block}\n\n"
            + per_answer_block
            + "Ask the NEXT question in the interview. If every planned question has genuinely been covered by the "
              "answers above, instead produce the full final output JSON now (no decision block)."
            + decision_instr
        )
        raw = _call_llm(next_prompt, provider, model, api_key, timeout=300,
                        abort_key=(req.project_id, req.field))
    except Exception:
        if session["qa"] and session["qa"][-1]["a"] == req.choice.strip():
            session["qa"].pop()
        session["pending"] = _prev_pending   # restore so resume re-serves the question
        session["in_flight"] = False
        session.pop("_rollback", None)
        _persist_interactive_session(req.session_id, session)
        raise
    return _field_interactive_handle(req.session_id, session, raw, cfg, provider, model, api_key,
                                     project, project_file, decision_instr)


def _field_interactive_handle(sid: str, session: dict, raw: str, cfg: dict, provider: str, model: str,
                              api_key: str, project: dict, project_file, decision_instr: str):
    """Parse a survey-round response: either the next decision block (return
    the question) or — if the model skipped straight to output — finish."""
    # Falls back to the unclosed-marker regex when the model emits the
    # decision JSON but drops the closing <<<END>>> — same gap already fixed
    # for chapter interactive's _interactive_handle_segment, confirmed live
    # here too: an Arc Interactive click failed with "Model did not return a
    # usable arc object" because the model's real question got misrouted to
    # the arc-JSON finisher instead of being recognized as a decision block.
    m = _DECISION_RE.search(raw) or _DECISION_RE_UNCLOSED.search(raw)
    if m:
        try:
            decision = json.loads(m.group(1))
        except Exception:
            # Deterministic, non-LLM repair — a single question's decision block
            # can get cut off by the same token/time limit as a final-round
            # answer; see _close_truncated's docstring. Only apply when it
            # produces a dict, never partial/garbage.
            fixed = _close_truncated(m.group(1))
            decision = fixed if isinstance(fixed, dict) else None
        if decision and isinstance(decision.get("options"), list) and decision["options"]:
            session["last_question"] = decision.get("question", "")
            payload = {
                "ok": True, "done": False, "session_id": sid,
                "question": decision.get("question", "Which direction?"),
                "options": [{"label": _trim_option_text(o.get("label", ""), 160), "description": _trim_option_text(o.get("description", ""), 600),
                            "evidence": _trim_option_text(o.get("evidence", ""), 200)}
                            for o in decision["options"][:3]],
                "recommended": decision.get("recommended", 0) if isinstance(decision.get("recommended"), int) else 0,
                "progress": str(decision.get("progress", ""))[:60],
                "answered": len(session["qa"]),
            }
            session["pending"] = payload   # resumable if the client disconnects OR the backend restarts
            session["in_flight"] = False
            session.pop("_rollback", None)
            # Recorded at index len(qa) — this IS the payload shown when qa has
            # its current length, matching how "back" looks it up.
            session.setdefault("history", []).append(payload)
            _persist_interactive_session(sid, session)
            return payload
    # No usable decision block → the model decided the interview is done early.
    # dialogue_shaping has NO JSON-patch finish path — its finisher applies the
    # RECORDED qa answers as an agentic chapter edit (_dialogue_shaping_apply),
    # not a parsed JSON object — so it must route separately from every other
    # field. Confirmed live: without this branch, an early-finished dialogue
    # shaping session fell through to _field_interactive_finish, which called
    # _apply_field_patch("dialogue_shaping", ...) — not a real field schema —
    # and silently returned {"result": None} without ever touching the
    # chapter file, discarding the author's answer with no error at all.
    if session.get("field") == "dialogue_shaping":
        return _dialogue_shaping_interactive_finish(sid, session, project, project_file)
    if session.get("field") == "blueprint_enrichment":
        # Same early-finish gap dialogue_shaping already guards against above
        # — an enrichment interview that ends early must still route to its
        # own chapter-rewrite finisher, not the generic JSON-field patcher.
        return _blueprint_enrichment_interactive_finish(sid, session, project, project_file)
    if session.get("field") == "critique":
        return _critique_interactive_finish(sid, session, project, project_file)
    return _field_interactive_finish(sid, session, raw, project, project_file)


def _field_interactive_finish(sid: str, session: dict, raw: str, project: dict, project_file):
    """Apply the final generated JSON through the SAME parse/patch/snapshot
    logic as one-shot generate_field (_apply_field_patch), so Undo and
    registry sync behave identically. "arcs" is the exception — it saves
    through _save_single_arc (same helper /arc uses) since a session only
    ever plans ONE arc, not the whole array, and returns early before the
    generic patch/snapshot flow below."""
    field, pid = session["field"], session["project_id"]
    if field == "arcs":
        arc = _parse_json_from_text(raw)
        if isinstance(arc, list) and arc:
            arc = arc[0]
        if not isinstance(arc, dict) or not arc.get("label"):
            _progress_log(pid, "INTERACTIVE arcs: unparseable response", "error")
            raise HTTPException(502, "Model did not return a usable arc object.")
        result = _save_single_arc(pid, project, project_file, session["arc_ctx"], arc)
        _progress_log(pid, f"INTERACTIVE arcs: complete — shaped by {len(session['qa'])} of your answers", "success")
        _log_project_memory(pid, "Interactive arcs",
                            "Author-steered planning; answers: "
                            + " | ".join(f"{qa['q']} -> {qa['a']}" for qa in session["qa"])[:400])
        with _INTERACTIVE_LOCK:
            _INTERACTIVE_SESSIONS.pop(sid, None)
        _delete_interactive_session_file(sid)
        return {"ok": True, "done": True, "session_id": sid, "field": field,
                "provider": f"{len(session['qa'])}-question interview",
                "result": result["arc"], "warnings": result["warnings"],
                "decisions": [qa["a"] for qa in session["qa"]], "can_undo": True}

    # Same unguarded-parse gap as the one-shot /field endpoint (see its
    # matching comment) — a malformed final-round response here raised past
    # every progress_log straight to a bare 500, with the interview's last
    # visible line staying whatever "answer recorded" text preceded it,
    # never distinguishing "saved" from "silently failed to save."
    _sk_ref_warnings = []
    if field == "chapter_skeleton":
        raw, _sk_ref_warnings = _skeleton_reference_finalize(
            raw, {**project, "id": pid}, session.get("sk_chapter") or session.get("chapter_number") or 1)
        _sk_ref_warnings = list(session.pop("_sk_gate_warnings", None) or []) + _sk_ref_warnings
        raw = _attach_gate_warnings(raw, _sk_ref_warnings)
    try:
        patch, result_data = _apply_field_patch(field, raw, project,
                                                chapter_number=session.get("chapter_number") or session.get("sk_chapter"))
    except Exception as e:
        _progress_log(pid, f"INTERACTIVE {field}: generated a response but it couldn't be saved "
                           f"(malformed output — {str(e)[:150]}). Nothing was written; try again.", "error")
        raise HTTPException(502, f"Generated response for '{field}' could not be parsed/saved: {str(e)[:200]}")
    if not patch:
        _progress_log(pid, f"INTERACTIVE {field}: generated a response but produced nothing to save. "
                           f"Nothing was written.", "error")
        raise HTTPException(502, f"Generated response for '{field}' produced nothing to save.")
    # If a forced pattern was offered (see FieldInteractiveRequest.force_pattern
    # / _forced_pattern_for_chapter) and the author's actual answer contains
    # its marker text, record it as used — this is the ONLY point a corpus
    # pattern gets marked used, and it only fires if the author genuinely
    # picked that option (never on offering it, never on a different choice).
    _forced = session.get("forced_pattern")
    if _forced and field == "chapter_skeleton":
        _marker = f"[Pattern: {_forced['pattern_id']}]"
        if any(_marker in (qa.get("a") or "") for qa in session["qa"]):
            used = project.setdefault("used_corpus_patterns", [])
            used.append({"pattern_id": _forced["pattern_id"], "novel_title": _forced.get("novel_title"),
                        "chapter": session.get("chapter_number"), "at": _time.time()})
            _progress_log(pid, f"FORCE PATTERN: '{_forced['pattern_id']}' chosen — recorded as used, won't be offered again", "success")

    _snapshot_field(project, field)
    project.update(patch)
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)
    registry_file = CORPUS_PATH / "projects" / "registry.json"
    if registry_file.exists():
        try:
            with open(registry_file, encoding="utf-8-sig") as f:
                reg = json.load(f)
            for p in (reg if isinstance(reg, list) else reg.get("projects", [])):
                if p["id"] == pid and "planning_progress" in patch:
                    p["planning_progress"] = patch["planning_progress"]
            with open(registry_file, "w", encoding="utf-8") as f:
                json.dump(reg, f, indent=2, ensure_ascii=False)
        except Exception:
            pass

    _progress_log(pid, f"INTERACTIVE {field}: complete — shaped by {len(session['qa'])} of your answers", "success")
    _log_project_memory(pid, f"Interactive {field}",
                        "Author-steered planning; answers: "
                        + " | ".join(f"{qa['q']} -> {qa['a']}" for qa in session["qa"])[:400])
    with _INTERACTIVE_LOCK:
        _INTERACTIVE_SESSIONS.pop(sid, None)
    _delete_interactive_session_file(sid)

    # Same drift check the one-shot skeleton button ran — the interview is
    # now the ONLY way to plan a chapter skeleton (the direct button was
    # removed), so this parity is what author actually sees these warnings.
    warnings = []
    if field == "chapter_skeleton" and result_data:
        sk = result_data[-1] if isinstance(result_data, list) else result_data
        if isinstance(sk, dict):
            warnings = _skeleton_plan_check_warnings(sk, session.get("sk_target_t")) + _sk_ref_warnings
            try:    # notes (never a gate) when the plan was made with the reference novel on
                from routers.pre_generation.reference_mechanics import shape_warnings as _shape_w
                warnings += _shape_w(project, sk)
            except Exception:
                pass
            for w in warnings:
                _progress_log(pid, w, "warn")

    return {"ok": True, "done": True, "session_id": sid, "field": field,
            "provider": f"{len(session['qa'])}-question interview",
            "result": result_data, "warnings": warnings,
            "decisions": [qa["a"] for qa in session["qa"]],
            "can_undo": True}


_STYLE_DNA_TOLERANCE = 0.15   # same 15-point tolerance Round-Trip Validation's "Sentence mix" check uses


def _style_dna_measure(text: str) -> dict:
    sys.path.insert(0, str(CORPUS_PATH))
    from extract_v3 import analyze_style_dna  # noqa: PLC0415
    return analyze_style_dna(text) or {}


_VOICE_FIXES = {   # (signal, direction) -> the punctuation-only fix the polish pass is told to make
    ("exclamations", "low"): "Where a character shouts, is shocked, or a crowd reacts, end that existing line with "
                             "'!' (or '?!' for disbelief). Change punctuation only — don't add lines.",
    ("exclamations", "high"): "Change the weakest '!' to a period until it's in range.",
    ("questions", "low"): "Turn existing lines of doubt or disbelief into questions — in dialogue or in narration "
                          "(\"How could this be?\"). Rephrase only those lines.",
    ("questions", "high"): "Turn some questions back into statements.",
    ("ellipses", "low"): "Use '...' where speech trails off or a character hesitates. Punctuation only.",
    ("ellipses", "high"): "Replace some '...' with a period.",
    ("em_dashes", "high"): "Replace each '—' with a comma, a period, or '...' as fits.",
    ("triplets", "high"): "Rewrite each one — two items, or a separate short sentence (\"Relief, plain and "
                          "undisguised\" -> \"Plain relief.\").",
}


def _voice_check(project: Optional[dict], text: str, measured: Optional[dict] = None) -> list:
    """Each corpus voice signal for this text: its raw count, the count range the
    corpus's interquartile range implies for this many sentences, and whether it's
    in range. Sentences are split exactly as analyze_style_dna splits them, so the
    counts line up with the corpus rates they're compared against."""
    import math as _math
    t = _voice_targets(project)
    if not t:
        return []
    n = max(len([s for s in re.split(r'[.!?]+\s+', text) if len(s.strip()) > 10]), 1)
    triplets = re.findall(r"\b\w+,\s+\w+,?\s+and\s+\w+\b", text)
    counts = {"exclamations": text.count("!"), "questions": text.count("?"),
              "ellipses": text.count("…") + len(re.findall(r"\.\s?\.\s?\.", text)),
              "em_dashes": text.count("—"), "triplets": len(triplets)}
    rows = []
    for key in ("exclamations", "questions", "ellipses", "em_dashes", "triplets"):
        if key not in t:
            continue
        lo, hi = t[key]["low"], t[key]["high"]
        lo_c, hi_c = _math.floor(lo * n), _math.ceil(hi * n)
        cnt = counts[key]
        rows.append({"key": key, "label": _VOICE_SIGNALS[key], "count": cnt, "sentences": n,
                     "low": lo, "high": hi, "lo_c": lo_c, "hi_c": hi_c,
                     "status": "low" if cnt < lo_c else "high" if cnt > hi_c else "ok",
                     "examples": triplets[:4] if key == "triplets" else []})
    if "dialogue_share" in t:
        if measured is None:
            measured = _style_dna_measure(text)
        share = (measured.get("content_ratios") or {}).get("dialogue_percentage")
        if isinstance(share, (int, float)):
            lo, hi = t["dialogue_share"]["low"], t["dialogue_share"]["high"]
            # Report-only: raising it means turning narration into dialogue — a content
            # change for Dialogue Shaping, not a punctuation-level polish fix.
            rows.append({"key": "dialogue_share", "label": _VOICE_SIGNALS["dialogue_share"], "share": share,
                         "low": lo, "high": hi, "report_only": True,
                         "status": "low" if share < lo else "high" if share > hi else "ok"})
    return rows


def _style_dna_drift_notes(project: Optional[dict], text: str) -> list:
    """Polish-pass instructions for every Author Profile style DNA target the
    chapter is off — the profile is seeded by averaging the corpus's own
    per-chapter style DNA, so this is "read like the corpus". Sentence mix was
    the only signal enforced anywhere; paragraph mix and transitions were stated
    in the prompt and never checked. Measured on generated chapters, paragraph
    rhythm was the biggest gap: the corpus runs ~75% single-sentence paragraphs
    (median), last night's interactive chapter ran 23%. Best-effort: no profile,
    or a measurement error, means no notes — never a blocked polish."""
    if not ((project or {}).get("author_profile") or {}):
        return []
    sd = (project["author_profile"].get("style_dna") or {})
    try:
        actual = _style_dna_measure(text)
    except Exception:
        return []
    notes = []

    def drift(dist_key):
        want_d, got_d = sd.get(dist_key) or {}, actual.get(dist_key) or {}
        return [(k, w, got_d.get(k)) for k, w in want_d.items()
                if isinstance(w, (int, float)) and isinstance(got_d.get(k), (int, float))
                and abs(got_d[k] - w) > _STYLE_DNA_TOLERANCE]

    sent = drift("sentence_length_distribution")
    if sent:
        notes.append("SENTENCE-LENGTH MIX IS OFF THE STYLE DNA TARGET (rebalance by rewriting individual sentences — "
                     "combine/split where it reads naturally — NOT by adding or cutting content):\n"
                     + "\n".join(f"  - {k.replace('_', ' ')}: target {w:.0%}, now {g:.0%}" for k, w, g in sent))
    para = drift("paragraph_length_distribution")
    if para:
        notes.append("PARAGRAPH MIX IS OFF THE STYLE DNA TARGET — this corpus's paragraphs are mostly a single "
                     "sentence:\n"
                     + "\n".join(f"  - {k.replace('_', ' ')} paragraphs: target {w:.0%}, now {g:.0%}" for k, w, g in para)
                     + "\n  Fix by INSERTING PARAGRAPH BREAKS ONLY — split multi-sentence paragraphs at natural beats "
                       "(after a line of dialogue, after an action beat, before a reaction). Keep every word. Only "
                       "merge single-sentence paragraphs if single-sentence paragraphs are ABOVE target.")
    favs = [t for t in (sd.get("favorite_transitions") or []) if isinstance(t, str) and t.strip()]
    if favs and not any(re.search(rf"\b{re.escape(t)}\b", text, re.I) for t in favs):
        uniq = list(dict.fromkeys(t.lower() for t in favs))
        notes.append("TRANSITIONS: this corpus moves between beats with phrases like "
                     + ", ".join(f"\"{t}\"" for t in uniq) + " — the chapter uses none of them. Where a scene shifts "
                     "or one beat cuts into another, use one or two of these. Only where they fit naturally; never "
                     "force one in.")

    # Corpus voice — exact counts against the range the corpus implies for THIS
    # chapter's sentence count, each with the punctuation-only fix to make.
    voice_lines = []
    try:
        rows = _voice_check(project, text, actual)
    except Exception:
        rows = []
    for r in rows:
        fix = _VOICE_FIXES.get((r["key"], r["status"]))
        if r["status"] == "ok" or r.get("report_only") or not fix:
            continue
        habit = ("your corpus essentially never uses them" if r["high"] == 0 else
                 f"your corpus runs {r['low'] * 100:.0f}-{r['high'] * 100:.0f} per 100 sentences "
                 f"(about {r['lo_c']}-{r['hi_c']} here)")
        line = f"  - {r['label']}: {r['count']} in {r['sentences']} sentences — {habit}. {fix}"
        if r["examples"]:
            line += "\n    " + "\n    ".join(f"\"{e}\"" for e in r["examples"])
        voice_lines.append(line)
    if voice_lines:
        notes.append("CORPUS VOICE — punctuation habits outside the source novels' measured range:\n"
                     + "\n".join(voice_lines))
    return notes


def _style_dna_report(project: Optional[dict], before: str, after: str) -> str:
    """Before -> after for each Author Profile distribution the polish pass was
    asked to move, so the console shows whether style DNA actually changed
    (no LLM call — the same measurement as the check)."""
    sd = ((project or {}).get("author_profile") or {}).get("style_dna") or {}
    if not sd:
        return ""
    try:
        b, a = _style_dna_measure(before), _style_dna_measure(after)
    except Exception:
        return ""
    parts = []
    for dist_key, noun in (("sentence_length_distribution", "sentences"), ("paragraph_length_distribution", "paragraphs")):
        for k, want in (sd.get(dist_key) or {}).items():
            bv, av = (b.get(dist_key) or {}).get(k), (a.get(dist_key) or {}).get(k)
            if isinstance(want, (int, float)) and isinstance(bv, (int, float)) and isinstance(av, (int, float)) \
                    and abs(bv - want) > _STYLE_DNA_TOLERANCE:
                parts.append(f"{k.replace('_', ' ')} {noun} {bv:.0%} → {av:.0%} (target {want:.0%})")
    try:
        after_rows = {r["key"]: r for r in _voice_check(project, after, a)}
        for r in _voice_check(project, before, b):
            if r["status"] == "ok" or r.get("report_only") or r["key"] not in after_rows:
                continue
            target = "~0" if r["high"] == 0 else f"{r['lo_c']}-{r['hi_c']}"
            parts.append(f"{r['label'].lower()} {r['count']} → {after_rows[r['key']]['count']} (corpus {target})")
    except Exception:
        pass
    return "; ".join(parts)


def _voice_match(project: Optional[dict], text: str) -> dict:
    """Corpus voice-match score: every style DNA signal the Author Profile targets
    (sentence mix, paragraph mix, transitions, and the corpus voice signals), each
    with this text's value, the target, and whether it's in range. Score = how many
    are in range. Same measurements and tolerances as the polish pass's checks."""
    profile = (project or {}).get("author_profile") or {}
    if not profile or not (text or "").strip():
        return {"score": 0, "total": 0, "signals": []}
    sd = profile.get("style_dna") or {}
    actual = _style_dna_measure(text)
    signals = []
    for dist_key, noun in (("sentence_length_distribution", "sentences"), ("paragraph_length_distribution", "paragraphs")):
        for k, want in (sd.get(dist_key) or {}).items():
            got = (actual.get(dist_key) or {}).get(k)
            if isinstance(want, (int, float)) and isinstance(got, (int, float)):
                signals.append({"group": "rhythm", "label": f"{k.replace('_', ' ')} {noun}", "value": f"{got:.0%}",
                                "target": f"{want:.0%} ± 15", "ok": abs(got - want) <= _STYLE_DNA_TOLERANCE})
    favs = list(dict.fromkeys(t.lower() for t in (sd.get("favorite_transitions") or []) if isinstance(t, str) and t.strip()))
    if favs:
        used = [t for t in favs if re.search(rf"\b{re.escape(t)}\b", text, re.I)]
        signals.append({"group": "rhythm", "label": "corpus transitions", "value": ", ".join(used) or "none",
                        "target": "at least one", "ok": bool(used)})
    for r in _voice_check(project, text, actual):
        if r.get("report_only"):
            signals.append({"group": "voice", "label": r["label"], "value": f"{r['share']:.0%}",
                            "target": f"{r['low']:.0%}-{r['high']:.0%}", "ok": r["status"] == "ok",
                            "note": "raise it with Dialogue Shaping" if r["status"] == "low" else ""})
        else:
            signals.append({"group": "voice", "label": r["label"],
                            "value": f"{r['count']} ({r['count'] / r['sentences'] * 100:.0f}/100)",
                            "target": "~0" if r["high"] == 0 else f"{r['low'] * 100:.0f}-{r['high'] * 100:.0f}/100",
                            "ok": r["status"] == "ok"})
    return {"score": sum(1 for s in signals if s["ok"]), "total": len(signals), "signals": signals}


# ── Humor DNA check (end of chapter) ─────────────────────────────────────────
# The corpus extractor's humor taxonomy (corpus/extract_v3.py, humor_instances),
# so a chapter's count is comparable with the Humor DNA averages seeded from it.
_HUMOR_TYPES = {
    "deadpan_reaction": "a flat or understated response to something outrageous",
    "situational_irony": "the outcome is the opposite of what someone expected or intended",
    "character_dynamic": "humor from how two or more characters play off each other",
    "running_gag": "a joke that recurs, or a callback to an earlier one",
    "subverted_trope": "a genre expectation set up, then undercut",
    "escalation_gag": "a situation that keeps getting more absurd",
    "fish_out_of_water": "a character comically out of place or out of their depth",
}


def _quote_words(s: str) -> str:
    """Lowercased words only, single-spaced and padded, so a quoted snippet
    matches the chapter whatever its punctuation, quote marks or line breaks."""
    s = (s or "").replace("\u2019", "'").replace("\u2018", "'")
    return " " + " ".join(re.findall(r"[a-z0-9']+", s.lower())) + " "


def _quote_probes(quote: str) -> list:
    """The word runs a model-quoted snippet is looked up by: the whole quote, plus
    its first and last five words when it's longer — models drop or retouch a word
    or two when they copy a line. Padded like _quote_words; [] for a snippet under
    three words, too short to place reliably."""
    q = _quote_words(quote).split()
    if len(q) < 3:
        return []
    return [" " + " ".join(w) + " " for w in ([q] + ([q[:5], q[-5:]] if len(q) > 5 else []))]


def _quote_pos(quote: str, text_words: str) -> int:
    """Where a model-quoted snippet sits in the chapter (text_words from
    _quote_words), or -1."""
    for probe in _quote_probes(quote):
        i = text_words.find(probe)
        if i != -1:
            return i
    return -1


def _humor_beats(text: str, provider: str, model: str, api_key: str, gags: Optional[list] = None,
                 slaps: Optional[list] = None) -> dict:
    """Count a chapter's humor beats by type: one LLM call, the end-of-chapter
    Humor DNA check. Every beat must come back with a short exact quote, and one
    whose quote isn't in the chapter is dropped, so an invented beat can't pad the
    count. The same call keeps the running-gag ledger current: given the book's
    known gags ([{id, name}]), a beat can name the gag it calls back to ("gag") or
    a new joke the book is set up to repeat ("new_gag").
    {"count", "beats": [{type, quote, gag?, new_gag?}], "by_type", "dropped"}, or
    {"error"} when the call or its JSON fails."""
    types = "\n".join(f"- {k}: {v}" for k, v in _HUMOR_TYPES.items())
    known = "\n".join(f"{g['id']}: {g['name']}" for g in (gags or []))
    gag_list = f"\n\nRUNNING GAGS ALREADY IN THIS BOOK:\n{known}" if known else ""
    gag_field = ', "gag": "<a running-gag id from the list above>"' if known else ""
    gag_rule = ('Give "gag" only when a beat clearly calls back to one of the running gags listed above. '
                if known else "")
    leave_out = "both fields" if known else "it"
    known_slaps = "\n".join(f"{s['id']}: {s['name']} ({s.get('target') or 'someone'})" for s in (slaps or []))
    slap_list = f"\n\nFACE SLAPS ALREADY TRACKED IN THIS BOOK:\n{known_slaps}" if known_slaps else ""
    slap_field = ', "slap": "<a tracked face-slap id from the list above, if it continues one>"' if known_slaps else ""
    prompt = f"""Count the HUMOR BEATS in this web-novel chapter. A humor beat is a moment written to make the reader smile or laugh. Banter that isn't meant to amuse doesn't count, and one comic moment that runs over several lines is ONE beat.

Types (use exactly these names):
{types}{gag_list}{slap_list}

Separately, list the chapter's FACE SLAPS (they are not humor beats and don't count as beats): a moment someone looks down on, mocks or humiliates the protagonist or his side (role "setup"), or the protagonist turning it back on them, so the doubter is proven wrong in front of others (role "payoff"). "target" is the person who looked down on him.

THE CHAPTER:
{text}

Respond with JSON only, nothing before or after it:
{{"beats": [{{"type": "<one of the type names above>", "quote": "<5-15 words copied exactly from the chapter, where the beat lands>"{gag_field}, "new_gag": "<short name>"}}], "face_slaps": [{{"role": "setup|payoff", "target": "<who looked down on him>", "name": "<short name, e.g. the deacon's fee mockery>", "quote": "<5-15 words copied exactly from the chapter>"{slap_field}}}]}}
{gag_rule}Give "new_gag" only when a beat sets up a joke the book is built to repeat: a character's comic habit, a catchphrase, a situation the story will keep coming back to. Most beats are one-offs; leave {leave_out} out for those.
If the chapter has no humor beats, use "beats": []; with no face slaps, "face_slaps": []."""
    try:
        raw = _call_llm(prompt, provider, model, api_key, timeout=300) or ""
    except Exception as e:
        _log_error("humor_check", f"error={e}")
        return {"error": f"the model call failed ({str(e)[:120]})"}
    try:
        data = _parse_json_from_text(raw)
    except Exception:
        return {"error": "the reply wasn't valid JSON"}
    items = data.get("beats") if isinstance(data, dict) else data
    if not isinstance(items, list):
        return {"error": "the reply had no list of beats"}
    text_words = _quote_words(text)
    known_ids = {g["id"] for g in (gags or [])}
    beats, seen, dropped = [], set(), 0
    for b in items:
        if not isinstance(b, dict):
            continue
        quote = str(b.get("quote") or "").strip()
        pos = _quote_pos(quote, text_words)
        if pos == -1:
            dropped += 1
            continue
        if pos in seen:
            continue
        seen.add(pos)
        kind = re.sub(r"[\s-]+", "_", str(b.get("type") or "").strip().lower())
        beat = {"type": kind if kind in _HUMOR_TYPES else "other", "quote": quote}
        gid = str(b.get("gag") or "").strip().upper()
        if gid in known_ids:
            beat["gag"] = gid
        elif isinstance(b.get("new_gag"), str) and b["new_gag"].strip():
            beat["new_gag"] = b["new_gag"].strip()[:120]
        beats.append(beat)
    by_type = {}
    for b in beats:
        by_type[b["type"]] = by_type.get(b["type"], 0) + 1
    by_type = dict(sorted(by_type.items(), key=lambda kv: -kv[1]))
    slap_ids = {s["id"] for s in (slaps or [])}
    face_slaps = []
    for fs in (data.get("face_slaps") or []) if isinstance(data, dict) else []:
        if not isinstance(fs, dict) or fs.get("role") not in ("setup", "payoff"):
            continue
        quote = str(fs.get("quote") or "").strip()
        if _quote_pos(quote, text_words) == -1:
            continue
        sid = str(fs.get("slap") or "").strip().upper()
        face_slaps.append({"role": fs["role"], "quote": quote, "target": str(fs.get("target") or "").strip()[:80],
                           "name": str(fs.get("name") or "").strip()[:120], **({"slap": sid} if sid in slap_ids else {})})
    return {"count": len(beats), "beats": beats, "by_type": by_type, "dropped": dropped, "face_slaps": face_slaps}


def _humor_target(project: Optional[dict]) -> Optional[dict]:
    """The Humor DNA target for the end-of-chapter check: the profile's average
    beats per chapter, the whole number a chapter should reach (rounded half up,
    at least 1), and its main types. None when the profile has no humor target."""
    hd = _profile_dna(project, "humor_dna")
    avg = hd.get("beats_per_chapter")
    if not isinstance(avg, (int, float)) or avg <= 0:
        return None
    return {"average": avg, "minimum": max(1, int(avg + 0.5)),
            "types": [t for t in (hd.get("top_types") or []) if isinstance(t, str)][:4]}


def _humor_polish_note(found: int, target: dict, due_gags: Optional[list] = None) -> Optional[str]:
    """The polish pass's HUMOR item when a chapter falls short of its Humor DNA
    target. Asks for at most two added beats, pointing at running gags that are
    due a callback when there are any; None when nothing is short."""
    short = target["minimum"] - found
    if short <= 0:
        return None
    add = min(2, short)
    types = ", ".join(t.replace("_", " ") for t in target["types"]) or "whatever kind fits the scene"
    note = (f"HUMOR (Humor DNA): this chapter has {found} humor beat{'' if found == 1 else 's'}; the author's corpus "
            f"averages about {target['average']} per chapter, mostly {types}. Add {add} short humor "
            f"beat{'' if add == 1 else 's'} of those kinds at natural moments, without changing what happens. If "
            f"this chapter's tone makes humor wrong (a death, a betrayal, real grief), add none.")
    if due_gags:
        note += (" If one fits naturally, make it a callback to a running gag that's due: "
                 + "; ".join(f"{g['id']} {g['name']} (quiet for {g['quiet']} chapters)" for g in due_gags[:2]) + ".")
    return note


def _humor_summary(h: dict) -> str:
    """'3 beats (2 deadpan reaction, character dynamic)' for the console."""
    n = h.get("count", 0)
    kinds = ", ".join(f"{c} {t.replace('_', ' ')}" if c > 1 else t.replace("_", " ")
                      for t, c in (h.get("by_type") or {}).items())
    return f"{n} beat{'' if n == 1 else 's'}" + (f" ({kinds})" if kinds else "")


# ── Running-gag ledger (per project) ─────────────────────────────────────────
# This book's own running gags: seeded from the author's craft notes (a named
# comedy/gag/humor section), then kept current by the end-of-chapter humor check,
# which says which beats call back to a known gag and which set up a new one. A
# new gag starts as a candidate and turns active once a later chapter calls back
# to it. The chapter prompt lists the active ones with when each last appeared,
# flagging any quiet for longer than Humor DNA's due_after. Its own file
# (projects/<id>/gag_ledger.json), never project.json.
_GAG_LEDGER_LOCK = _threading.RLock()
_GAG_STATUSES = ("active", "candidate", "retired")


def _gag_ledger_path(project_id: str) -> Path:
    return CORPUS_PATH / "projects" / project_id / "gag_ledger.json"


def _gag_seed_names(project: Optional[dict]) -> list:
    """Running gags named in the craft notes: every named section whose key
    mentions comedy, gags, humor or jokes, one gag per top-level comma or
    semicolon (commas inside parentheses or double quotes don't split)."""
    notes = (project or {}).get("craft_notes")
    if not isinstance(notes, dict):
        return []
    names = []
    for key, val in notes.items():
        if not re.search(r"comed|gag|humou?r|joke", str(key), re.I):
            continue
        for text in (val if isinstance(val, list) else [val]):
            if not isinstance(text, str):
                continue
            text = re.sub(r"^\s*(?:running\s+gags?|comedy\s+beats?|gags?|jokes?)\s*:\s*", "", text.strip(), flags=re.I)
            depth, quoted, cur = 0, False, ""
            for c in text + ",":
                if c in "([":
                    depth += 1
                elif c in ")]":
                    depth = max(0, depth - 1)
                elif c in "\"\u201c\u201d":
                    quoted = not quoted
                if c in ",;" and depth == 0 and not quoted:
                    cur = cur.strip().rstrip(".").strip()
                    if len(cur) >= 4:
                        names.append(cur[:160])
                    cur = ""
                else:
                    cur += c
    return list(dict.fromkeys(names))


def _save_gag_ledger(project_id: str, led: dict):
    path = _gag_ledger_path(project_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    led["updated"] = _time.time()
    tmp = path.with_name("gag_ledger.json.tmp")
    tmp.write_text(json.dumps(led, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


def _load_gag_ledger(project_id: str, project: Optional[dict] = None) -> dict:
    """The project's running-gag ledger, created and seeded from its craft notes on
    first use. An unreadable file is set aside (renamed), never overwritten."""
    path = _gag_ledger_path(project_id)
    with _GAG_LEDGER_LOCK:
        if path.exists():
            try:
                led = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(led, dict) and isinstance(led.get("gags"), list):
                    return led
            except Exception:
                pass
            path.replace(path.with_name(f"gag_ledger.unreadable-{int(_time.time())}.json"))
        if project is None:
            try:
                project = json.loads((CORPUS_PATH / "projects" / project_id / "project.json").read_text(encoding="utf-8"))
            except Exception:
                project = {}
        gags = [{"id": f"G{i}", "name": n, "status": "active", "source": "craft notes", "beats": []}
                for i, n in enumerate(_gag_seed_names(project), 1)]
        led = {"version": 1, "next_id": len(gags) + 1, "gags": gags}
        _save_gag_ledger(project_id, led)
        return led


def _written_chapter_numbers(project_id: str) -> set:
    gen_dir = CORPUS_PATH / "generated" / project_id
    out = set()
    for f in (gen_dir.glob("ch*_generated.txt") if gen_dir.exists() else []):
        m = re.match(r"ch(\d+)_generated\.txt$", f.name)
        if m:
            out.add(int(m.group(1)))
    return out


def _gag_rows(led: dict, project_id: str, before_chapter: Optional[int] = None) -> list:
    """Each gag plus the chapters it has appeared in (only chapters whose prose
    still exists, and only those before `before_chapter` when writing that one),
    its last appearance, how many chapters it has been quiet since, and its
    payoff state: not_set_up (no appearance yet), needs_payoff (set up in one
    chapter, not called back since) or paid_off (a later chapter called back)."""
    written = _written_chapter_numbers(project_id)
    if before_chapter is not None:
        written = {c for c in written if c < before_chapter}
    latest = (before_chapter - 1) if before_chapter is not None else max(written, default=0)
    rows = []
    for g in led.get("gags", []):
        chs = sorted({b["chapter"] for b in g.get("beats", []) if isinstance(b, dict) and b.get("chapter") in written})
        last = chs[-1] if chs else None
        rows.append({**g, "chapters": chs, "last_seen": last, "quiet": None if last is None else latest - last,
                     "state": "not_set_up" if not chs else "paid_off" if len(chs) > 1 else "needs_payoff",
                     "setup_chapter": chs[0] if chs else None, "payoff_chapters": chs[1:]})
    return rows


def _gag_due_after(project: Optional[dict]) -> int:
    """Quiet chapters after which a running gag is due a callback: Humor DNA's
    setups.due_after, else the whole corpus's, else _GAG_DUE_AFTER_DEFAULT."""
    v = (_profile_dna(project, "humor_dna").get("setups") or {}).get("due_after")
    if not isinstance(v, (int, float)) or v < 1:
        v = _humor_setups_for(None).get("due_after")
    return int(v) if isinstance(v, (int, float)) and v >= 1 else _GAG_DUE_AFTER_DEFAULT


def _gag_ledger_block(project: dict, project_id: Optional[str], chapter_number: int) -> str:
    """The chapter prompt's RUNNING GAGS block: the book's active running gags, when
    each last appeared, and which are due a callback. Empty when there are none."""
    if not project_id:
        return ""
    try:
        rows = [g for g in _gag_rows(_load_gag_ledger(project_id, project), project_id, chapter_number)
                if g.get("status") == "active"]
        due_after = _gag_due_after(project)
    except Exception:
        return ""
    if not rows:
        return ""

    def is_due(g):
        return g["quiet"] is not None and g["quiet"] > due_after

    # Due first (longest quiet first), then not yet in the text, then the rest.
    rows.sort(key=lambda g: (not is_due(g), g["last_seen"] is not None, -(g["quiet"] or 0)))
    lines = []
    for g in rows[:8]:
        if g["last_seen"] is None:
            lines.append(f"  {g['id']} {g['name']} — not in the text yet"
                         + (f"; planned as: {g['plan'][:240]}" if g.get("plan") else ""))
        elif is_due(g):
            lines.append(f"  {g['id']} {g['name']} — DUE: last appeared in ch {g['last_seen']}, quiet for {g['quiet']} "
                         f"chapters (running gags in this voice usually come back within {due_after}). Give it a "
                         f"beat this chapter if a scene allows it, without forcing it.")
        else:
            lines.append(f"  {g['id']} {g['name']} — last appeared in ch {g['last_seen']}")
    return "RUNNING GAGS IN THIS BOOK (tracked from the chapters written so far):\n" + "\n".join(lines)


def _slap_rows(led: dict, project_id: str, before_chapter: Optional[int] = None) -> list:
    """Each tracked face slap with its humiliation chapters, its payback chapters
    (only chapters whose prose still exists, and only before `before_chapter`
    when writing that one), its state (planned: not in the text yet; waiting:
    humiliated, not paid back; slapped) and, while waiting, the chapters since
    the first humiliation."""
    written = _written_chapter_numbers(project_id)
    if before_chapter is not None:
        written = {c for c in written if c < before_chapter}
    latest = (before_chapter - 1) if before_chapter is not None else max(written, default=0)
    rows = []
    for s in led.get("slaps", []):
        beats = [b for b in s.get("beats", []) if isinstance(b, dict) and b.get("chapter") in written]
        setups = sorted({b["chapter"] for b in beats if b.get("role") != "payoff"})
        payoffs = sorted({b["chapter"] for b in beats if b.get("role") == "payoff"})
        state = "planned" if not beats else "slapped" if payoffs else "waiting"
        quote = next((b.get("quote") for b in beats if b.get("role") != "payoff" and b.get("quote")), "")
        rows.append({**s, "setup_chapters": setups, "payoff_chapters": payoffs, "state": state, "quote": quote,
                     "quiet": (latest - setups[0]) if state == "waiting" and setups else None})
    return rows


def _face_slap_due_after(project: Optional[dict]) -> int:
    v = (_profile_dna(project, "humor_dna").get("face_slaps") or {}).get("due_after")
    if not isinstance(v, (int, float)) or v < 1:
        v = _face_slaps_for(None).get("due_after")
    return int(v) if isinstance(v, (int, float)) and v >= 1 else _FACE_SLAP_DUE_DEFAULT


def _face_slap_block(project: dict, project_id: Optional[str], chapter_number: int) -> str:
    """The chapter prompt's FACE SLAPS block: humiliations not paid back yet (due
    ones first and flagged) and planned slaps. Empty when there are none."""
    if not project_id:
        return ""
    try:
        rows = [s for s in _slap_rows(_load_gag_ledger(project_id, project), project_id, chapter_number)
                if s.get("status") != "retired" and s["state"] in ("waiting", "planned")]
        due_after = _face_slap_due_after(project)
    except Exception:
        return ""
    if not rows:
        return ""
    rows.sort(key=lambda s: (s["state"] != "waiting", -(s["quiet"] or 0)))
    lines = []
    for s in rows[:6]:
        who = s.get("target") or "someone"
        if s["state"] == "waiting":
            due = s["quiet"] is not None and s["quiet"] > due_after
            lines.append(f"  {s['id']} {s['name']} ({who}) — humiliated him in ch {s['setup_chapters'][0]}"
                         + (f' ("{s["quote"][:120]}")' if s.get("quote") else "")
                         + (f"; DUE: unpaid for {s['quiet']} chapters, the corpus usually pays one back within "
                            f"{due_after}. Turn it on {who} in front of others if a scene allows it."
                            if due else f"; waiting {s['quiet']} chapter{'' if s['quiet'] == 1 else 's'}")
                         + (f"; planned slap: {s['plan'][:200]}" if s.get("plan") else ""))
        else:
            lines.append(f"  {s['id']} {s['name']} ({who}) — planned, not in the text yet"
                         + (f": {s['plan'][:240]}" if s.get("plan") else ""))
    return ("FACE SLAPS IN THIS BOOK (someone looked down on the protagonist and hasn't paid for it yet; a slap "
            "turns it back on them in front of others):\n" + "\n".join(lines))


def _slap_ledger_record(project_id: str, project: Optional[dict], chapter_number: int, found: list) -> dict:
    """Record a finished chapter's face slaps from the humor check: a humiliation
    (role setup) and a payback (role payoff), matched to a tracked slap by id, or a
    payback by its target to a slap still waiting. A humiliation by someone not
    tracked yet starts a new one. Idempotent per chapter, like _gag_ledger_record.
    Returns names {"new", "again", "slapped"}."""
    new, again, slapped = [], [], []
    with _GAG_LEDGER_LOCK:
        led = _load_gag_ledger(project_id, project)
        slaps = led.setdefault("slaps", [])
        for s in slaps:
            s["beats"] = [b for b in s.get("beats", []) if b.get("chapter") != chapter_number]
        by_id = {s["id"]: s for s in slaps}

        def open_on(target):
            t = (target or "").strip().lower()
            return next((x for x in slaps if t and str(x.get("target") or "").strip().lower() == t
                         and not any(b.get("role") == "payoff" for b in x.get("beats", []))), None)

        for fs in found:
            s = by_id.get(fs.get("slap")) or open_on(fs.get("target"))
            if s is None and fs["role"] == "setup":
                sid = f"S{led.get('next_slap_id') or len(slaps) + 1}"
                led["next_slap_id"] = int(sid[1:]) + 1
                s = {"id": sid, "name": (fs.get("name") or f"{fs.get('target') or 'Someone'}'s contempt")[:120],
                     "target": (fs.get("target") or "")[:80], "status": "active", "source": "chapter",
                     "planted_chapter": chapter_number, "beats": []}
                slaps.append(s)
                by_id[sid] = s
                new.append(s["name"])
            elif s is None:
                continue   # a payback for a humiliation nobody tracked
            elif fs["role"] == "setup" and s["name"] not in new:
                again.append(s["name"])
            if fs["role"] == "payoff":
                slapped.append(s["name"])
            s["beats"].append({"chapter": chapter_number, "role": fs["role"], "quote": fs["quote"][:200]})
        led["slaps"] = [x for x in slaps if x.get("beats") or x.get("source") != "chapter"
                        or x.get("planted_chapter") != chapter_number]
        _save_gag_ledger(project_id, led)
    return {"new": list(dict.fromkeys(new)), "again": list(dict.fromkeys(again)), "slapped": list(dict.fromkeys(slapped))}


def _gag_ledger_record(project_id: str, project: Optional[dict], chapter_number: int, beats: list) -> dict:
    """Record a finished chapter's humor beats in the ledger: a beat tagged with a
    known gag id is an appearance of that gag; one tagged new_gag starts a
    candidate, which turns active once a later chapter calls back to it.
    Idempotent per chapter: a rewritten chapter's old entries are replaced.
    Returns gag names {"called_back", "promoted", "new"} for the console."""
    called, promoted, new = [], [], []
    with _GAG_LEDGER_LOCK:
        led = _load_gag_ledger(project_id, project)
        for g in led["gags"]:
            g["beats"] = [b for b in g.get("beats", []) if b.get("chapter") != chapter_number]
        by_id = {g["id"]: g for g in led["gags"]}
        for b in beats:
            g = by_id.get(b.get("gag"))
            if g is None and b.get("new_gag"):
                name = str(b["new_gag"]).strip()[:120]
                g = next((x for x in led["gags"] if x["name"].lower() == name.lower()), None)
                if g is None:
                    gid = f"G{led.get('next_id') or len(led['gags']) + 1}"
                    led["next_id"] = int(gid[1:]) + 1
                    g = {"id": gid, "name": name, "status": "candidate", "source": "chapter",
                         "planted_chapter": chapter_number, "beats": []}
                    led["gags"].append(g)
                    by_id[gid] = g
            if g is None:
                continue
            g["beats"].append({"chapter": chapter_number, "quote": str(b.get("quote") or "")[:200],
                               "type": b.get("type")})
            if g.get("status") == "candidate" and any(x.get("chapter") != chapter_number for x in g["beats"]):
                g["status"] = "active"
                promoted.append(g["name"])
            elif g.get("planted_chapter") == chapter_number and g.get("status") == "candidate":
                new.append(g["name"])
            else:
                called.append(g["name"])
        # A candidate this chapter planted that the rewrite no longer has.
        led["gags"] = [g for g in led["gags"] if g.get("beats") or g.get("status") != "candidate"
                       or g.get("planted_chapter") != chapter_number]
        _save_gag_ledger(project_id, led)
    return {"called_back": list(dict.fromkeys(called)), "promoted": list(dict.fromkeys(promoted)),
            "new": list(dict.fromkeys(new))}


@router.get("/gag-ledger/{project_id}")
def get_gag_ledger(project_id: str):
    """This book's running gags (seeded from the craft notes on first use): each
    with the chapters it appeared in, when it last did, and whether it's due."""
    project_file = CORPUS_PATH / "projects" / project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    led = _load_gag_ledger(project_id, project)
    due_after = _gag_due_after(project)
    rows = _gag_rows(led, project_id)
    for r in rows:
        r["due"] = r.get("status") != "retired" and r["quiet"] is not None and r["quiet"] > due_after
    return {"ok": True, "gags": rows, "due_after": due_after,
            "latest_chapter": max(_written_chapter_numbers(project_id), default=0)}


class GagLedgerOp(BaseModel):
    project_id: str
    op: str                       # add | update | delete
    id: Optional[str] = None      # update / delete
    name: Optional[str] = None    # add / update
    status: Optional[str] = None  # update: active | candidate | retired


@router.post("/gag-ledger")
def gag_ledger_op(req: GagLedgerOp):
    """One edit to the running-gag ledger, applied on its own so it can't clobber a
    chapter that finishes at the same moment: add a gag, rename it or change its
    status, or delete it. Returns the ledger as get_gag_ledger does."""
    if not (CORPUS_PATH / "projects" / req.project_id / "project.json").exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    name = (req.name or "").strip()[:160]
    with _GAG_LEDGER_LOCK:
        led = _load_gag_ledger(req.project_id)
        g = next((x for x in led["gags"] if x["id"] == req.id), None)
        if req.op == "add":
            if not name:
                raise HTTPException(400, "A running gag needs a name.")
            gid = f"G{led.get('next_id') or len(led['gags']) + 1}"
            led["next_id"] = int(gid[1:]) + 1
            led["gags"].append({"id": gid, "name": name, "status": "active", "source": "author", "beats": []})
        elif req.op not in ("update", "delete"):
            raise HTTPException(400, "op must be add, update or delete")
        elif g is None:
            raise HTTPException(404, f"No running gag {req.id}")
        elif req.op == "update":
            if name:
                g["name"] = name
            if req.status in _GAG_STATUSES:
                g["status"] = req.status
        else:
            led["gags"].remove(g)
        _save_gag_ledger(req.project_id, led)
    return get_gag_ledger(req.project_id)


def _gag_ledger_add(project_id: str, project: Optional[dict], chapter_number: int, quote: str,
                    gag_id: Optional[str] = None, new_gag: Optional[str] = None) -> Optional[str]:
    """One appearance added by hand (a Humor tab suggestion the author applied): a
    callback to a known gag, or a new gag planted as a candidate. Unlike
    _gag_ledger_record it keeps the chapter's other entries. Returns the gag's name."""
    with _GAG_LEDGER_LOCK:
        led = _load_gag_ledger(project_id, project)
        g = next((x for x in led["gags"] if x["id"] == gag_id), None) if gag_id else None
        if g is None and new_gag:
            g = next((x for x in led["gags"] if x["name"].lower() == new_gag.lower()), None)
            if g is None:
                gid = f"G{led.get('next_id') or len(led['gags']) + 1}"
                led["next_id"] = int(gid[1:]) + 1
                g = {"id": gid, "name": new_gag[:120], "status": "candidate", "source": "humor tab",
                     "planted_chapter": chapter_number, "beats": []}
                led["gags"].append(g)
        if g is None:
            return None
        g["beats"].append({"chapter": chapter_number, "quote": quote[:200], "type": "added"})
        if g.get("status") == "candidate" and any(b.get("chapter") != chapter_number for b in g["beats"]):
            g["status"] = "active"
        _save_gag_ledger(project_id, led)
        return g["name"]


# ── Humor tab: chapter scan, suggestions, corpus gag search ───────────────────
# The scan reads one written chapter and suggests where humor could go: a payoff
# for a running gag set up earlier, a setup a later chapter can pay off, or a
# one-off beat. Every suggestion quotes the exact spot (an anchor) and the exact
# lines, and nothing changes until the author applies one, which is a plain
# insertion (no second AI call) with the old chapter kept in _versions.
# Suggestions live in projects/<id>/humor_scans.json.
_HUMOR_SCANS_LOCK = _threading.RLock()
_HUMOR_KINDS = ("payoff", "setup", "beat")


def _humor_scans_path(project_id: str) -> Path:
    return CORPUS_PATH / "projects" / project_id / "humor_scans.json"


def _load_humor_scans(project_id: str) -> dict:
    """{chapter number (str): {at, suggestions, dropped, examples}}. An unreadable
    file is set aside (renamed), never overwritten."""
    path = _humor_scans_path(project_id)
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    path.replace(path.with_name(f"humor_scans.unreadable-{int(_time.time())}.json"))
    return {}


def _save_humor_scans(project_id: str, scans: dict):
    path = _humor_scans_path(project_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name("humor_scans.json.tmp")
    tmp.write_text(json.dumps(scans, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


def _locate_anchor(text: str, anchor: str) -> Optional[int]:
    """Character offset where a model-quoted anchor starts in the chapter: the
    whole quote, else its first or last six words (models retouch a word or two
    when they copy a line). Words only, so punctuation, quote marks and line
    breaks don't matter. None when it isn't there."""
    flat = (text or "").replace("\u2019", "'").replace("\u2018", "'")
    toks = [(m.group(0).lower(), m.start()) for m in re.finditer(r"[A-Za-z0-9']+", flat)]
    words = [t[0] for t in toks]
    q = re.findall(r"[a-z0-9']+", (anchor or "").replace("\u2019", "'").replace("\u2018", "'").lower())
    if len(q) < 4:
        return None
    for probe in [q] + ([q[:6], q[-6:]] if len(q) > 6 else []):
        n = len(probe)
        for i in range(len(words) - n + 1):
            if words[i] == probe[0] and words[i:i + n] == probe:
                return toks[i][1]
    return None


def _paragraph_sep(text: str) -> str:
    """Blank-line paragraphs normally; single newlines for a chapter without any."""
    return r"\n[ \t]*\n" if re.search(r"\n[ \t]*\n", text) else r"\n"


def _paragraph_bounds(text: str, pos: int) -> tuple:
    """(start, end) of the paragraph holding character offset pos."""
    start = 0
    for m in re.finditer(_paragraph_sep(text), text):
        if m.start() >= pos:
            return start, m.start()
        start = m.end()
    return start, len(text)


def _rewrite_keeps_paragraph(original: str, lines: str) -> bool:
    """A rewrite may work a joke into a paragraph, never swap it for another one:
    at least 70% of the original paragraph's words must still be in it."""
    old = set(re.findall(r"[a-z0-9']+", original.lower()))
    new = set(re.findall(r"[a-z0-9']+", lines.lower()))
    return bool(old) and len(old & new) / len(old) >= 0.7


def _humor_insert(text: str, anchor: str, mode: str, lines: str) -> Optional[str]:
    """The chapter with a suggestion applied: "after" adds the lines as a new
    paragraph after the anchor's paragraph, "rewrite" replaces that paragraph
    with them. None when the anchor isn't in the chapter any more."""
    pos = _locate_anchor(text, anchor)
    lines = (lines or "").strip()
    if pos is None or not lines:
        return None
    start, end = _paragraph_bounds(text, pos)
    if mode == "rewrite":
        return text[:start] + lines + text[end:]
    gap = "\n\n" if _paragraph_sep(text) != r"\n" else "\n"
    return text[:end] + gap + lines + text[end:]


def _humor_index_count() -> int:
    """How many corpus humor beats the semantic index holds (0 = not built yet)."""
    try:
        import sqlite3 as _sq
        from routers.corpus_tools.corpus import _KNOWLEDGE_DB
        if not _KNOWLEDGE_DB.exists():
            return 0
        conn = _sq.connect(_KNOWLEDGE_DB, timeout=5)
        try:
            return conn.execute("SELECT COUNT(*) FROM chunks WHERE category = 'humor'").fetchone()[0]
        finally:
            conn.close()
    except Exception:
        return 0


def _novel_label(novel_id: str, stored: Optional[str], titles: Optional[dict] = None) -> str:
    """A corpus novel's readable title: the registry's, else the index's stored one
    unless it's just the id again, else the id prettified."""
    if (titles or {}).get(novel_id):
        return titles[novel_id]
    if stored and stored != novel_id:
        return stored
    return str(novel_id or "").replace("_", " ").title()


def _humor_hit(r: dict, titles: Optional[dict] = None) -> dict:
    """One humor search result for the Humor tab. The registry title wins over the
    index's stored one (often just the id), and a type is kept only when it reads
    as a kind of joke: older beats used one-off labels ("bai_heng_admires_qin_nan_now")."""
    meta = r.get("meta") or {}
    kind = str(meta.get("type") or "")
    if kind not in _HUMOR_TYPES and len(kind.split("_")) > 2:
        kind = ""
    return {"novel_id": r.get("novel_id"),
            "novel_title": _novel_label(r.get("novel_id"), r.get("novel_title"), titles),
            "chapter": r.get("chapter"), "type": kind,
            "setup": meta.get("setup") or "", "payoff": meta.get("payoff") or "",
            "text": r.get("text"), "family_size": meta.get("family_size") or 1,
            "recurrence": meta.get("recurrence"), "score": round(float(r.get("score") or 0), 3)}


def _corpus_humor_examples(queries: list, per_query: int = 2, limit: int = 6) -> list:
    """Corpus humor beats semantically closest to each query (gag names, a chapter
    summary), running gags first. [] when the humor index isn't built or Ollama is
    down; the scan works without them."""
    if not _humor_index_count():
        return []
    try:
        from routers.corpus_tools.corpus import knowledge_search
    except Exception:
        return []
    titles = _corpus_novel_titles()
    out, seen = [], set()
    for q in queries:
        if not q or len(out) >= limit:
            continue
        try:
            hits = [_humor_hit(r, titles) for r in knowledge_search(str(q)[:600], top_k=per_query * 3, category="humor")]
        except Exception:
            return out
        hits.sort(key=lambda h: h["family_size"] < 2)   # stable: running gags first, each group by score
        for h in [h for h in hits if h["text"] not in seen][:per_query]:
            seen.add(h["text"])
            out.append(h)
    return out[:limit]


@router.get("/humor/{project_id}")
def humor_overview(project_id: str):
    """Everything the Humor tab shows: Humor DNA (as in force), the running gags
    with their payoff state, every written chapter with its end-of-chapter humor
    count and scan suggestions, and whether the corpus humor index is built."""
    project_file = CORPUS_PATH / "projects" / project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    profile = project.get("author_profile") or {}
    led = _load_gag_ledger(project_id, project)
    due_after = _gag_due_after(project)
    gags = _gag_rows(led, project_id)
    for g in gags:
        g["due"] = g.get("status") != "retired" and g["quiet"] is not None and g["quiet"] > due_after
    gen_dir = CORPUS_PATH / "generated" / project_id
    scans = _load_humor_scans(project_id)
    chapters = []
    for n in sorted(_written_chapter_numbers(project_id)):
        humor = None
        side = gen_dir / f"ch{n:03d}_voice.json"
        if side.exists():
            try:
                humor = json.loads(side.read_text(encoding="utf-8")).get("humor")
            except Exception:
                pass
        chapters.append({"number": n, "humor": humor, "scan": scans.get(str(n))})
    titles = _corpus_novel_titles()
    vs_novels = _voice_source_novels(profile)
    slap_due = _face_slap_due_after(project)
    slaps = _slap_rows(led, project_id)
    for s in slaps:
        s["due"] = s.get("status") != "retired" and s["quiet"] is not None and s["quiet"] > slap_due
    return {"ok": True, "has_profile": bool(profile), "picks": _load_humor_picks(project_id)["picks"],
            "slaps": slaps, "slap_due_after": slap_due,
            "humor_dna": _profile_dna(project, "humor_dna"),
            "humor_dna_saved": isinstance(profile.get("humor_dna"), dict) and bool(profile.get("humor_dna")),
            "voice_source": ", ".join(titles.get(n, n) for n in vs_novels) if vs_novels else "whole corpus",
            "gags": gags, "due_after": due_after, "chapters": chapters,
            "index": {"beats": _humor_index_count()}}


class HumorDnaRequest(BaseModel):
    project_id: str
    humor_dna: dict


@router.post("/humor/dna")
def save_humor_dna(req: HumorDnaRequest):
    """Save the Humor tab's Humor DNA into the author profile, touching nothing else in it."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    profile = project.get("author_profile")
    if not profile:
        raise HTTPException(400, "Set up the Author DNA tab first; Humor DNA is part of the author profile.")
    profile["humor_dna"] = req.humor_dna
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)
    return {"ok": True, "humor_dna": req.humor_dna}


class HumorScanRequest(BaseModel):
    project_id: str
    chapter_number: int
    provider: Optional[str] = None


@router.post("/humor/scan")
def humor_scan(req: HumorScanRequest):
    """One AI call over one written chapter: places it could take a payoff for a
    running gag set up earlier, a setup a later chapter can pay off, or a one-off
    beat. A suggestion whose quoted spot isn't in the chapter is dropped. Replaces
    the chapter's earlier open suggestions; applied ones stay on record."""
    pid, n = req.project_id, req.chapter_number
    project_file = CORPUS_PATH / "projects" / pid / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {pid} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    ch_path = CORPUS_PATH / "generated" / pid / f"ch{n:03d}_generated.txt"
    if not ch_path.exists():
        raise HTTPException(404, f"Chapter {n} has not been written yet.")
    text = ch_path.read_text(encoding="utf-8")
    gen_cfg = _get_generation_cfg()
    provider = req.provider or gen_cfg.get("default_provider", "anthropic")
    api_key = _get_key(provider)
    model = _get_models_cfg().get(provider, "")

    led = _load_gag_ledger(pid, project)
    rows = [g for g in _gag_rows(led, pid, n) if g.get("status") != "retired"]
    here = {g["id"] for g in led["gags"] for b in g.get("beats", []) if b.get("chapter") == n}
    due_after = _gag_due_after(project)
    gag_lines = []
    for g in rows:
        if g["id"] in here:
            state = "already in this chapter"
        elif g["state"] == "not_set_up":
            state = "not in the text yet (set it up here only if it fits)" + (f"; planned as: {g['plan'][:240]}"
                                                                              if g.get("plan") else "")
        elif g["state"] == "needs_payoff":
            state = f"set up in ch {g['setup_chapter']}, NEEDS PAYOFF"
        else:
            state = "paid off in ch " + ", ".join(str(c) for c in g["payoff_chapters"])
        if g["id"] not in here and g["quiet"] is not None and g["quiet"] > due_after:
            state += f"; DUE: quiet for {g['quiet']} chapters"
        gag_lines.append(f"  {g['id']} {g['name']} — {state}")

    tgt = _humor_target(project)
    hs = _profile_dna(project, "humor_dna").get("setups") or {}
    dna = ""
    if tgt:
        types = ", ".join(t.replace("_", " ") for t in tgt["types"]) or "any kind"
        dna = f"Humor DNA: about {tgt['average']} humor beats per chapter, mostly {types}."
    gap = hs.get("callback_gap") or {}
    if gap.get("low") is not None and gap.get("high") is not None:
        dna += f" A running gag usually pays off {gap['low']}–{gap['high']} chapters after its setup."
    count = ""
    try:
        side = json.loads((CORPUS_PATH / "generated" / pid / f"ch{n:03d}_voice.json").read_text(encoding="utf-8"))
        if isinstance(side.get("humor"), dict):
            count = f"This chapter has {side['humor'].get('after')} humor beats now (counted at the end of generation)."
    except Exception:
        pass
    summary = ""
    try:
        sums = json.loads((CORPUS_PATH / "projects" / pid / "chapter_summaries.json").read_text(encoding="utf-8"))
        summary = next((s.get("summary") for s in sums if s.get("chapter") == n), "") or ""
    except Exception:
        pass
    examples = _corpus_humor_examples(
        [g["name"] for g in rows if g["id"] not in here and g["state"] != "not_set_up"][:3] + [summary or text[:600]])
    ex_block = ("CORPUS EXAMPLES (how other novels set up and pay off similar jokes; adapt the mechanism to this "
                "book, never copy names or lines):\n" + "\n".join(
                    f"  - [{e['type'].replace('_', ' ')}] {e['setup']} → {e['payoff']} ({e['novel_title']}, ch "
                    f"{e['chapter']}{', became a running gag' if e['family_size'] >= 2 else ''})" for e in examples)
                if examples else "")
    notes = _craft_note_lines(project.get("craft_notes"))
    notes_block = ("THE AUTHOR'S CRAFT NOTES (follow them in anything you write):\n" + "\n".join(notes)) if notes else ""
    try:    # the book's whole plan (lore, timeline, foes, cast, arc, chapter plan, the tree's writer-safe surface)
        from routers.pre_generation.canon import craft_context_block as _ccb
        notes_block += "\n\n" + _ccb(project, n, "humor", 8000)
    except Exception:
        pass
    gag_block = "\n".join(gag_lines) or "  (none yet)"
    # Corpus jokes the author picked and adapted, not yet turned into running gags.
    ideas = [x["adapted"] for x in _load_humor_picks(pid)["picks"] if x.get("adapted") and not x.get("gag_id")][:5]
    if ideas:
        ex_block = (ex_block + "\n\n" if ex_block else "") + (
            "HUMOR IDEAS THE AUTHOR PICKED FOR THIS BOOK (already adapted to its cast; suggest one as a \"beat\" or "
            "\"setup\" where it fits):\n" + "\n".join(f"  - {i['name']}: {i['setup']} → {i['payoff']}" for i in ideas))
    type_names = ", ".join(_HUMOR_TYPES)
    prompt = f"""{_house_style_upfront_block()}

You are a comedy editor on a web novel. Find the best places in Chapter {n} below to add humor WITHOUT changing what happens: no new events, no changed outcome, nobody acting out of character.

{dna}
{count}

THIS BOOK'S RUNNING GAGS:
{gag_block}

{ex_block}

{notes_block}

THE CHAPTER:
{text}

Suggest up to 5 additions, best first. Kinds:
- "payoff": pay off a running gag marked NEEDS PAYOFF or DUE, at a moment where it lands naturally. Give its id in "gag".
- "setup": plant something small that a LATER chapter can pay off (a habit, a boast, a running bet, a catchphrase). Name it in "new_gag".
- "beat": a one-off humor beat in a flat stretch, in the book's main humor types.

For each, quote an ANCHOR: 8-25 words copied exactly from the chapter.
- mode "after": your lines become a NEW paragraph right after the paragraph containing the anchor. Use this by default.
- mode "rewrite": your lines REPLACE the anchor's whole paragraph, so write out that full paragraph with the joke worked in, keeping everything else it says.
"lines" is the exact new text: 1-3 sentences, in this chapter's voice, tense and POV, following the craft notes.

Respond with JSON only, nothing before or after it:
{{"suggestions": [{{"kind": "payoff|setup|beat", "gag": "<running-gag id, payoffs only>", "new_gag": "<short name, setups only>", "type": "<one of: {type_names}>", "anchor": "<exact quote from the chapter>", "mode": "after|rewrite", "lines": "<the new text>", "why": "<one short sentence>"}}]}}

{_house_style_reminder_block()}"""
    _progress_log(pid, f"HUMOR Ch.{n}: scanning for places to add humor…")
    try:
        prompt += _word_budget_note(project, n, text, kind="insert", chapter_text=text, pid=pid, label="humor scan")
        raw = _call_llm(prompt, provider, model, api_key, timeout=300) or ""
        data = _parse_json_from_text(raw)
    except Exception as e:
        _log_error("humor_scan", f"project={pid} chapter={n} error={e}")
        raise HTTPException(502, f"The humor scan failed: {str(e)[:200]}")
    items = data.get("suggestions") if isinstance(data, dict) else data
    if not isinstance(items, list):
        raise HTTPException(502, "The humor scan's reply had no list of suggestions.")
    ids = {g["id"]: g["name"] for g in rows}
    found, dropped, stamp = [], 0, int(_time.time())
    for i, s in enumerate(items[:8]):
        if not isinstance(s, dict):
            continue
        anchor, lines = str(s.get("anchor") or "").strip(), str(s.get("lines") or "").strip()
        mode = "rewrite" if s.get("mode") == "rewrite" else "after"
        pos = _locate_anchor(text, anchor)
        if pos is None or not lines or len(lines) > 1500:
            dropped += 1
            continue
        start, end = _paragraph_bounds(text, pos)
        paragraph = text[start:end]
        if mode == "rewrite" and not _rewrite_keeps_paragraph(paragraph, lines):
            dropped += 1
            continue
        kind = s.get("kind") if s.get("kind") in _HUMOR_KINDS else "beat"
        htype = re.sub(r"[\s-]+", "_", str(s.get("type") or "").strip().lower())
        sug = {"id": f"{n}-{stamp}-{i}", "kind": kind, "type": htype if htype in _HUMOR_TYPES else "other",
               "anchor": anchor, "mode": mode, "lines": lines, "why": str(s.get("why") or "").strip()[:300],
               "paragraph": paragraph[:1500], "status": "open"}
        gid = str(s.get("gag") or "").strip().upper()
        if kind == "payoff":
            if gid in ids:
                sug.update(gag=gid, gag_name=ids[gid])
            else:
                sug["kind"] = "beat"   # a payoff for no known gag is just a beat
        elif kind == "setup" and isinstance(s.get("new_gag"), str) and s["new_gag"].strip():
            sug["new_gag"] = s["new_gag"].strip()[:120]
        found.append(sug)
    with _HUMOR_SCANS_LOCK:
        scans = _load_humor_scans(pid)
        kept = [s for s in (scans.get(str(n)) or {}).get("suggestions", []) if s.get("status") == "applied"]
        scans[str(n)] = {"at": _time.time(), "suggestions": kept + found, "dropped": dropped, "examples": examples}
        _save_humor_scans(pid, scans)
    _progress_log(pid, f"HUMOR Ch.{n}: {len(found)} place(s) to add humor"
                       + (f" ({dropped} dropped: the spot they quoted isn't in the chapter)" if dropped else ""),
                  "success")
    return {"ok": True, "chapter": n, "scan": scans[str(n)]}


class HumorSuggestionRequest(BaseModel):
    project_id: str
    chapter_number: int
    suggestion_id: str
    action: str                   # apply | dismiss
    lines: Optional[str] = None   # apply: the author's edited lines (default: the suggestion's own)


@router.post("/humor/suggestion")
def humor_suggestion(req: HumorSuggestionRequest):
    """Apply or dismiss one scan suggestion. Apply inserts the lines exactly where
    the suggestion says (no AI call), keeps the old chapter in _versions, records
    a payoff or new setup in the running-gag ledger, and adds the beat to the
    chapter's humor count."""
    pid, n = req.project_id, req.chapter_number
    project_file = CORPUS_PATH / "projects" / pid / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {pid} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    gen_dir = CORPUS_PATH / "generated" / pid
    ch_path = gen_dir / f"ch{n:03d}_generated.txt"
    if not ch_path.exists():
        raise HTTPException(404, f"Chapter {n} has not been written yet.")
    with _HUMOR_SCANS_LOCK:
        scans = _load_humor_scans(pid)
        sug = next((s for s in (scans.get(str(n)) or {}).get("suggestions", []) if s.get("id") == req.suggestion_id), None)
        if sug is None:
            raise HTTPException(404, "That suggestion isn't there any more; scan the chapter again.")
        if sug.get("status") != "open":
            raise HTTPException(409, f"That suggestion was already {sug.get('status')}.")
        if req.action == "dismiss":
            sug["status"] = "dismissed"
            _save_humor_scans(pid, scans)
            return {"ok": True, "suggestion": sug}
        if req.action != "apply":
            raise HTTPException(400, "action must be apply or dismiss")
        lines = (req.lines if req.lines is not None else sug.get("lines") or "").strip()
        if not lines:
            raise HTTPException(400, "Nothing to add: the lines are empty.")
        text = ch_path.read_text(encoding="utf-8")
        pos = _locate_anchor(text, sug["anchor"])
        if pos is None:
            raise HTTPException(409, "The spot this suggestion points at isn't in the chapter any more (it was "
                                     "edited since the scan). Scan the chapter again.")
        if sug["mode"] == "rewrite":
            s0, e0 = _paragraph_bounds(text, pos)
            if not _rewrite_keeps_paragraph(text[s0:e0], lines):
                raise HTTPException(400, "That rewrite drops too much of the original paragraph. Keep its "
                                         "content and work the joke in.")
        new_text = _humor_insert(text, sug["anchor"], sug["mode"], lines)
        vdir = gen_dir / "_versions"
        vdir.mkdir(exist_ok=True)
        v = len(list(vdir.glob(f"ch{n:03d}_v*.txt"))) + 1
        (vdir / f"ch{n:03d}_v{v}.txt").write_text(text, encoding="utf-8")
        ch_path.write_text(new_text, encoding="utf-8")
        _index_chapter_async(pid, n)
        (gen_dir / f"ch{n:03d}_audio.wav").unlink(missing_ok=True)   # stale — was synthesized from the old text
        sug.update(status="applied", applied_lines=lines, applied_version=v, applied_at=_time.time())
        _save_humor_scans(pid, scans)
    gag = None
    try:
        if sug.get("gag") or sug.get("new_gag"):
            gag = _gag_ledger_add(pid, project, n, lines, gag_id=sug.get("gag"), new_gag=sug.get("new_gag"))
    except Exception as e:
        _log_error("gag_ledger", f"project={pid} chapter={n} error={e}")
    try:
        side_path = gen_dir / f"ch{n:03d}_voice.json"
        side = json.loads(side_path.read_text(encoding="utf-8"))
        h = side.get("humor")
        if isinstance(h, dict):
            h["after"] = (h.get("after") or 0) + 1
            h["added"] = (h.get("added") or []) + [lines]
            h["ok"] = h["after"] >= (h.get("minimum") or 0)
            side_path.write_text(json.dumps(side, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass
    _progress_log(pid, f"HUMOR Ch.{n}: added a {sug['kind']}" + (f" ({gag})" if gag else "")
                       + f"; the old chapter is kept as version {v}", "success")
    return {"ok": True, "suggestion": sug, "version": v, "text": new_text}


# ── Humor tab: picked corpus humor instances ──────────────────────────────────
# Like the Characters tab's Corpus DNA picker, which pulls one trait at a time from
# a corpus character: the author picks corpus humor beats into the book, adapts each
# to this book's own cast (one AI call), and can turn one into a running gag, whose
# plan (the adapted setup → payoff) then reaches chapter prompts and scans. Stored in
# projects/<id>/humor_picks.json.
_HUMOR_PICKS_LOCK = _threading.RLock()


def _humor_picks_path(project_id: str) -> Path:
    return CORPUS_PATH / "projects" / project_id / "humor_picks.json"


def _load_humor_picks(project_id: str) -> dict:
    """{"picks": [...], "next_id": n}. An unreadable file is set aside, never overwritten."""
    path = _humor_picks_path(project_id)
    if path.exists():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(data, dict) and isinstance(data.get("picks"), list):
                return data
        except Exception:
            pass
        path.replace(path.with_name(f"humor_picks.unreadable-{int(_time.time())}.json"))
    return {"picks": [], "next_id": 1}


def _save_humor_picks(project_id: str, data: dict):
    path = _humor_picks_path(project_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name("humor_picks.json.tmp")
    tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


def _book_cast_lines(project: dict, limit: int = 14) -> list:
    """The book's cast for an adapt prompt: "  Name (role): three traits"."""
    cast = []
    for c in (project.get("character_list") or [])[:limit]:
        if isinstance(c, dict) and c.get("name"):
            traits = c.get("personality_traits")
            traits = ", ".join(traits[:3]) if isinstance(traits, list) else str(traits or "")
            cast.append(f"  {c['name']} ({c.get('role') or 'character'}): {traits}"[:200])
    return cast


def _adapt_humor_pick(project: dict, source: dict, provider: str, model: str, api_key: str) -> dict:
    """One AI call: a corpus joke rewritten for this book, mechanism kept, every
    specific (names, setting, items) replaced with this book's own.
    {"name", "setup", "payoff", "characters"}."""
    cast = _book_cast_lines(project)
    gags = [g["name"] for g in _load_gag_ledger(project.get("id") or "", project)["gags"]][:10] if project.get("id") else []
    notes = _craft_note_lines(project.get("craft_notes"))
    brief = (project.get("creative_brief") or {}).get("premise") or ""
    cast_block = "\n".join(cast) or "  (no cast yet)"
    gag_block = ("RUNNING GAGS ALREADY IN THIS BOOK: " + "; ".join(gags)) if gags else ""
    notes_block = ("THE AUTHOR'S CRAFT NOTES:\n" + "\n".join(notes)) if notes else ""
    try:    # the book's whole plan (lore, timeline, foes, cast, arc, chapter plan, the tree's writer-safe surface)
        from routers.pre_generation.canon import craft_context_block as _ccb
        notes_block += "\n\n" + _ccb(project, None, "humor", 14000)
    except Exception:
        pass
    prompt = f"""Adapt this joke from another web novel to the book below. Keep the comic MECHANISM (what makes it funny) and replace everything specific: its characters with this book's own cast, its setting, items and powers with this world's. Never reuse a name, place or item from the source novel.

THE CORPUS JOKE ({str(source.get('type') or 'humor').replace('_', ' ')}, from {source.get('novel_title') or 'the corpus'}):
Setup: {source.get('setup') or ''}
Payoff: {source.get('payoff') or ''}

THIS BOOK:
Premise: {brief[:600]}
Cast:
{cast_block}
{gag_block}

{notes_block}

Pick the cast members whose personalities fit the joke best.

Respond with JSON only, nothing before or after it:
{{"name": "<a short name for the joke in this book, under 10 words>", "setup": "<1-2 sentences: how it is set up in this book>", "payoff": "<1-2 sentences: how it pays off>", "characters": ["<cast members involved>"]}}"""
    raw = _call_llm(prompt, provider, model, api_key, timeout=180) or ""
    data = _parse_json_from_text(raw)
    if not isinstance(data, dict) or not str(data.get("name") or "").strip():
        raise ValueError("the reply had no adapted joke")
    return {"name": str(data["name"]).strip()[:120], "setup": str(data.get("setup") or "").strip()[:600],
            "payoff": str(data.get("payoff") or "").strip()[:600],
            "characters": [str(c)[:60] for c in (data.get("characters") or []) if isinstance(c, str)][:6]}


class HumorPickOp(BaseModel):
    project_id: str
    op: str                         # add | update | delete | adapt | to_gag | to_slap
    id: Optional[str] = None        # every op but add
    source: Optional[dict] = None   # add: a corpus humor search result
    adapted: Optional[dict] = None  # update: {name, setup, payoff} as the author edited them
    provider: Optional[str] = None  # adapt


@router.post("/humor/picks")
def humor_picks_op(req: HumorPickOp):
    """One edit to the book's picked corpus humor instances: add one (from the
    Corpus gags search), edit its adaptation, adapt it to this book (one AI call),
    turn it into a running gag, or remove it. Returns {"picks": [...]} and, for
    to_gag, the gag ledger as get_gag_ledger does ("ledger"); for to_slap, the
    face slaps ("slaps", "slap_due_after")."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    project.setdefault("id", req.project_id)
    extra = {}
    with _HUMOR_PICKS_LOCK:
        data = _load_humor_picks(req.project_id)
        pick = next((x for x in data["picks"] if x["id"] == req.id), None)
        if req.op == "add":
            s = req.source or {}
            source = {k: s.get(k) for k in ("novel_id", "novel_title", "chapter", "type", "setup", "payoff",
                                            "family_size", "text")}
            if not (source.get("setup") or source.get("payoff") or source.get("text")):
                raise HTTPException(400, "That result has no setup or payoff to pick.")
            dup = next((x for x in data["picks"] if x["source"].get("text") == source.get("text")), None)
            if dup is None:
                pid = f"P{data.get('next_id') or len(data['picks']) + 1}"
                data["next_id"] = int(pid[1:]) + 1
                data["picks"].append({"id": pid, "source": source, "adapted": None, "gag_id": None,
                                      "added_at": _time.time()})
        elif req.op not in ("update", "delete", "adapt", "to_gag", "to_slap"):
            raise HTTPException(400, "op must be add, update, delete, adapt, to_gag or to_slap")
        elif pick is None:
            raise HTTPException(404, f"No picked humor instance {req.id}")
        elif req.op == "delete":
            data["picks"].remove(pick)
        elif req.op == "update":
            a = req.adapted or {}
            pick["adapted"] = {"name": str(a.get("name") or "").strip()[:120], "setup": str(a.get("setup") or "").strip()[:600],
                               "payoff": str(a.get("payoff") or "").strip()[:600],
                               "characters": (pick.get("adapted") or {}).get("characters") or []}
        elif req.op == "adapt":
            gen_cfg = _get_generation_cfg()
            provider = req.provider or gen_cfg.get("default_provider", "anthropic")
            try:
                pick["adapted"] = _adapt_humor_pick(project, pick["source"], provider,
                                                    _get_models_cfg().get(provider, ""), _get_key(provider))
            except Exception as e:
                _log_error("humor_adapt", f"project={req.project_id} pick={req.id} error={e}")
                raise HTTPException(502, f"Adapting failed: {str(e)[:200]}")
        elif req.op == "to_slap":
            a = pick.get("adapted") or {}
            src_ = pick["source"]
            plan = (f"{a['setup']} → {a['payoff']}" if a.get("setup") and a.get("payoff")
                    else f"{src_.get('setup') or ''} → {src_.get('payoff') or ''}").strip(" →")
            hero = str((project.get("character_list") or [{}])[0].get("name") or "").lower()
            target = next((c for c in (a.get("characters") or []) if c.lower() != hero), "")
            with _GAG_LEDGER_LOCK:
                led = _load_gag_ledger(req.project_id, project)
                slaps = led.setdefault("slaps", [])
                s = next((x for x in slaps if x["id"] == pick.get("slap_id")), None)
                if s is None:
                    sid = f"S{led.get('next_slap_id') or len(slaps) + 1}"
                    led["next_slap_id"] = int(sid[1:]) + 1
                    s = {"id": sid, "name": (a.get("name") or src_.get("setup") or "")[:120], "target": target,
                         "status": "active", "source": "corpus pick", "beats": []}
                    slaps.append(s)
                s["plan"] = plan[:500]
                _save_gag_ledger(req.project_id, led)
            pick["slap_id"] = s["id"]
            due = _face_slap_due_after(project)
            rows = _slap_rows(led, req.project_id)
            for r in rows:
                r["due"] = r.get("status") != "retired" and r["quiet"] is not None and r["quiet"] > due
            extra = {"slaps": rows, "slap_due_after": due}
        else:   # to_gag
            a = pick.get("adapted") or {}
            src_ = pick["source"]
            name = (a.get("name") or src_.get("setup") or src_.get("text") or "")[:120]
            plan = (f"{a['setup']} → {a['payoff']}" if a.get("setup") and a.get("payoff")
                    else f"{src_.get('setup') or ''} → {src_.get('payoff') or ''}").strip(" →")
            with _GAG_LEDGER_LOCK:
                led = _load_gag_ledger(req.project_id, project)
                g = next((x for x in led["gags"] if x["id"] == pick.get("gag_id")), None)
                if g is None:
                    gid = f"G{led.get('next_id') or len(led['gags']) + 1}"
                    led["next_id"] = int(gid[1:]) + 1
                    g = {"id": gid, "name": name, "status": "active", "source": "corpus pick", "beats": []}
                    led["gags"].append(g)
                g["plan"] = plan[:500]
                _save_gag_ledger(req.project_id, led)
            pick["gag_id"] = g["id"]
            extra = {"ledger": get_gag_ledger(req.project_id)}
        _save_humor_picks(req.project_id, data)
    return {"ok": True, "picks": data["picks"], **extra}


class SlapOp(BaseModel):
    project_id: str
    op: str                       # add | update | delete
    id: Optional[str] = None      # update / delete
    name: Optional[str] = None
    target: Optional[str] = None
    plan: Optional[str] = None
    status: Optional[str] = None  # active | retired


@router.post("/humor/slaps")
def slap_op(req: SlapOp):
    """One edit to the book's tracked face slaps: add one by hand (a planned slap),
    rename it / set its target or planned slap / retire it, or delete it. Returns
    {"slaps": rows, "slap_due_after"} as the Humor tab shows them."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    with _GAG_LEDGER_LOCK:
        led = _load_gag_ledger(req.project_id, project)
        slaps = led.setdefault("slaps", [])
        s = next((x for x in slaps if x["id"] == req.id), None)
        if req.op == "add":
            if not (req.name or "").strip():
                raise HTTPException(400, "A face slap needs a name.")
            sid = f"S{led.get('next_slap_id') or len(slaps) + 1}"
            led["next_slap_id"] = int(sid[1:]) + 1
            slaps.append({"id": sid, "name": req.name.strip()[:120], "target": (req.target or "").strip()[:80],
                          "plan": (req.plan or "").strip()[:500], "status": "active", "source": "author", "beats": []})
        elif req.op not in ("update", "delete"):
            raise HTTPException(400, "op must be add, update or delete")
        elif s is None:
            raise HTTPException(404, f"No face slap {req.id}")
        elif req.op == "update":
            if (req.name or "").strip():
                s["name"] = req.name.strip()[:120]
            if req.target is not None:
                s["target"] = req.target.strip()[:80]
            if req.plan is not None:
                s["plan"] = req.plan.strip()[:500]
            if req.status in ("active", "retired"):
                s["status"] = req.status
        else:
            slaps.remove(s)
        _save_gag_ledger(req.project_id, led)
    due = _face_slap_due_after(project)
    rows = _slap_rows(led, req.project_id)
    for r in rows:
        r["due"] = r.get("status") != "retired" and r["quiet"] is not None and r["quiet"] > due
    return {"ok": True, "slaps": rows, "slap_due_after": due}


class HumorCorpusSearchRequest(BaseModel):
    query: str
    top_k: int = 12
    running_only: bool = False
    face_slaps_only: bool = False   # beats whose setup or payoff reads as a face slap


@router.post("/humor/corpus-search")
def humor_corpus_search(req: HumorCorpusSearchRequest):
    """Corpus humor beats closest in meaning to an idea ("a gambler who always
    loses"): local embeddings, no AI call. running_only keeps beats that became
    running gags (a gag family of 2+, or labelled a running gag or callback)."""
    if not req.query.strip():
        raise HTTPException(400, "Type what kind of joke to look for.")
    if not _humor_index_count():
        raise HTTPException(409, "The corpus humor index isn't built yet. Run Humor Index (nomic) in the Pipeline tab.")
    from routers.corpus_tools.corpus import knowledge_search
    k = max(1, min(req.top_k, 40))
    try:
        titles = _corpus_novel_titles()
        widen = 4 if req.running_only else 1
        widen *= 5 if req.face_slaps_only else 1
        hits = [_humor_hit(r, titles) for r in knowledge_search(req.query.strip(), top_k=k * widen, category="humor")]
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(502, f"Corpus search failed: {str(e)[:200]}")
    if req.running_only:
        hits = [h for h in hits if h["family_size"] >= 2 or str(h["recurrence"] or "") in ("running_gag", "callback")]
    if req.face_slaps_only:
        hits = [h for h in hits if _FACE_SLAP_TEXT_RE.search(f"{h['setup']} {h['payoff']} {h['text']}")]
    return {"ok": True, "results": hits[:k]}


# ── Combat tab ────────────────────────────────────────────────────────────────
_COMBAT_PROSE_TYPES = {"combat_reaction": "Getting hit", "combat_technique": "Attacks",
                       "dialogue_threat": "Ruthless speech", "power_reveal": "Power reveals"}


@router.get("/combat/{project_id}")
def combat_overview(project_id: str):
    """Everything the Combat tab shows: Combat DNA (as in force), every written
    chapter's fight check (free, measured now) with what its end-of-chapter polish
    changed, and how many labelled corpus fight passages are searchable."""
    project_file = CORPUS_PATH / "projects" / project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    profile = project.get("author_profile") or {}
    gen_dir = CORPUS_PATH / "generated" / project_id
    chapters = []
    for n in sorted(_written_chapter_numbers(project_id)):
        try:
            text = (gen_dir / f"ch{n:03d}_generated.txt").read_text(encoding="utf-8")
        except Exception:
            continue
        plan = _chapter_plan_has_fight(project, n)
        polish = None
        try:
            polish = json.loads((gen_dir / f"ch{n:03d}_voice.json").read_text(encoding="utf-8")).get("combat")
        except Exception:
            pass
        chapters.append({"number": n, "plan_fight": plan, "check": _combat_check(project, text, plan),
                         "polish": polish})
    try:
        from routers.corpus_tools.corpus import prose_type_counts
        searchable = prose_type_counts(list(_COMBAT_PROSE_TYPES))
    except Exception:
        searchable = {}
    titles = _corpus_novel_titles()
    vs_novels = _voice_source_novels(profile)
    return {"ok": True, "has_profile": bool(profile), "picks": _load_fight_picks(project_id)["picks"],
            "combat_dna": _profile_dna(project, "combat_dna"),
            "combat_dna_saved": isinstance(profile.get("combat_dna"), dict) and bool(profile.get("combat_dna")),
            "voice_source": ", ".join(titles.get(n, n) for n in vs_novels) if vs_novels else "whole corpus",
            "chapters": chapters, "searchable": searchable, "types": _COMBAT_PROSE_TYPES}


class CombatDnaRequest(BaseModel):
    project_id: str
    combat_dna: dict


@router.post("/combat/dna")
def save_combat_dna(req: CombatDnaRequest):
    """Save the Combat tab's Combat DNA into the author profile, touching nothing else in it."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    profile = project.get("author_profile")
    if not profile:
        raise HTTPException(400, "Set up the Author DNA tab first; Combat DNA is part of the author profile.")
    profile["combat_dna"] = req.combat_dna
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)
    return {"ok": True, "combat_dna": req.combat_dna}


class CombatSearchRequest(BaseModel):
    query: str
    types: Optional[list] = None   # any of _COMBAT_PROSE_TYPES; default all
    top_k: int = 12


@router.post("/combat/corpus-search")
def combat_corpus_search(req: CombatSearchRequest):
    """Corpus fight passages closest in meaning to a description ("a punch that
    sends him flying through a wall"): the labelled prose samples the knowledge
    index already holds (hit reactions, attacks, threats, power reveals). Local
    embeddings, no AI call."""
    if not req.query.strip():
        raise HTTPException(400, "Describe the kind of fight moment to look for.")
    types = [t for t in (req.types or list(_COMBAT_PROSE_TYPES)) if t in _COMBAT_PROSE_TYPES]
    if not types:
        raise HTTPException(400, f"types must be among: {', '.join(_COMBAT_PROSE_TYPES)}")
    from routers.corpus_tools.corpus import knowledge_search
    try:
        hits = knowledge_search(req.query.strip(), top_k=max(1, min(req.top_k, 40)), category="prose", prose_types=types)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(502, f"Corpus search failed: {str(e)[:200]}")
    titles = _corpus_novel_titles()
    return {"ok": True, "results": [
        {"novel_id": r.get("novel_id"), "novel_title": _novel_label(r.get("novel_id"), r.get("novel_title"), titles),
         "chapter": r.get("chapter"), "type": (r.get("meta") or {}).get("type"), "text": r.get("text"),
         "score": round(float(r.get("score") or 0), 3)} for r in hits]}


# ── Combat tab: picked corpus fight moves ─────────────────────────────────────
# The fight twin of the humor picker: the author picks labelled corpus fight
# passages (a hit landing, an attack, a threat, a power reveal) into the book,
# adapts each to this book's cast and power system (one AI call) or writes their
# own version, and assigns it to a chapter or leaves it for any fight chapter.
# Adapted, ready moves reach those chapters' prompts. Stored in
# projects/<id>/fight_picks.json.
_FIGHT_PICKS_LOCK = _threading.RLock()


def _fight_picks_path(project_id: str) -> Path:
    return CORPUS_PATH / "projects" / project_id / "fight_picks.json"


def _load_fight_picks(project_id: str) -> dict:
    """{"picks": [...], "next_id": n}. An unreadable file is set aside, never overwritten."""
    path = _fight_picks_path(project_id)
    if path.exists():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(data, dict) and isinstance(data.get("picks"), list):
                return data
        except Exception:
            pass
        path.replace(path.with_name(f"fight_picks.unreadable-{int(_time.time())}.json"))
    return {"picks": [], "next_id": 1}


def _save_fight_picks(project_id: str, data: dict):
    path = _fight_picks_path(project_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name("fight_picks.json.tmp")
    tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(path)


def _book_power_lines(project: dict) -> list:
    """The book's power system for an adapt prompt: its realm ladder and the
    techniques / weapons overviews, trimmed."""
    out = []
    tiers = ((project.get("world_bible") or {}).get("power_tiers") or []) if isinstance(project.get("world_bible"), dict) else []
    if isinstance(tiers, list) and tiers:
        out.append("Power tiers: " + "; ".join(str(t) for t in tiers[:6]))
    systems = project.get("systems") if isinstance(project.get("systems"), dict) else {}
    for key, label in (("power_levels", "Power levels"), ("techniques", "Techniques"), ("weapons", "Weapons")):
        v = systems.get(key)
        if isinstance(v, dict) and v.get("overview"):
            out.append(f"{label}: {str(v['overview'])[:450]}")
    return out


def _adapt_fight_pick(project: dict, source: dict, provider: str, model: str, api_key: str) -> dict:
    """One AI call: a corpus fight passage rewritten for this book, with the move,
    how the blow lands and how the body takes it (or the threat's edge) kept, and
    every specific replaced with this book's own. {"name", "text", "characters"}."""
    kind = _COMBAT_PROSE_TYPES.get(source.get("type"), "fight moment")
    cast_block = "\n".join(_book_cast_lines(project)) or "  (no cast yet)"
    power_block = "\n".join(_book_power_lines(project))
    notes = _craft_note_lines(project.get("craft_notes"))
    notes_block = ("THE AUTHOR'S CRAFT NOTES (follow them):\n" + "\n".join(notes)) if notes else ""
    try:    # the book's whole plan (lore, timeline, foes, cast, arc, chapter plan, the tree's writer-safe surface)
        from routers.pre_generation.canon import craft_context_block as _ccb
        notes_block += "\n\n" + _ccb(project, None, "combat", 14000)
    except Exception:
        pass
    brief = (project.get("creative_brief") or {}).get("premise") or ""
    prompt = f"""Adapt this fight passage from another web novel to the book below. Keep what makes it work (the move, how the blow lands and how the body takes it, or the threat's edge) and replace everything specific: its fighters with this book's own cast, its techniques, weapons and powers with this world's, its places with this world's. Never reuse a name, technique, item or place from the source.

THE CORPUS PASSAGE ({kind}, from {source.get('novel_title') or 'the corpus'}):
{source.get('text') or ''}

THIS BOOK:
Premise: {brief[:600]}
{power_block}
Cast:
{cast_block}

{notes_block}

Pick the cast members who fit this fight best.

Respond with JSON only, nothing before or after it:
{{"name": "<a short name for this move in the book, under 10 words>", "text": "<the adapted passage: 1-4 sentences, ready to work into a chapter>", "characters": ["<cast members involved>"]}}

{_house_style_reminder_block()}"""
    raw = _call_llm(prompt, provider, model, api_key, timeout=180) or ""
    data = _parse_json_from_text(raw)
    if not isinstance(data, dict) or not str(data.get("text") or "").strip():
        raise ValueError("the reply had no adapted passage")
    return {"name": str(data.get("name") or "").strip()[:120], "text": str(data["text"]).strip()[:900],
            "characters": [str(c)[:60] for c in (data.get("characters") or []) if isinstance(c, str)][:6]}


def _fight_picks_block(project: dict, project_id: Optional[str], chapter_number: int) -> str:
    """The chapter prompt's picked fight moves: adapted, ready picks assigned to
    this chapter (always), plus unassigned ones when this chapter's plan has a
    fight. At most three."""
    if not project_id:
        return ""
    try:
        picks = [x for x in _load_fight_picks(project_id)["picks"]
                 if x.get("status", "ready") == "ready" and (x.get("adapted") or {}).get("text")]
    except Exception:
        return ""
    mine = [x for x in picks if x.get("chapter") == chapter_number]
    loose = [x for x in picks if not x.get("chapter")] if _chapter_plan_has_fight(project, chapter_number) else []
    chosen = (mine + loose)[:3]
    if not chosen:
        return ""
    lines = ["FIGHT MOVES THE AUTHOR PICKED (from the corpus, already adapted to this book):"]
    for x in chosen:
        a = x["adapted"]
        lines.append(f"  - {a.get('name') or 'Move'}: {a['text'][:450]}"
                     + ("  [planned for this chapter: use it]" if x in mine else "  [use it if this chapter's fight allows]"))
    return "\n".join(lines)


class FightPickOp(BaseModel):
    project_id: str
    op: str                          # add | update | delete | adapt
    id: Optional[str] = None         # every op but add
    source: Optional[dict] = None    # add: a Corpus fights search result
    adapted: Optional[dict] = None   # update: {name, text} as the author edited them
    chapter: Optional[int] = None    # update: the chapter it's planned for (0 = any fight chapter)
    status: Optional[str] = None     # update: ready | used
    provider: Optional[str] = None   # adapt


@router.post("/combat/picks")
def fight_picks_op(req: FightPickOp):
    """One edit to the book's picked corpus fight moves: add one (from the Corpus
    fights search), adapt it to this book (one AI call), edit its adaptation, plan
    it for a chapter or mark it used, or remove it. Returns {"picks": [...]}."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    with _FIGHT_PICKS_LOCK:
        data = _load_fight_picks(req.project_id)
        pick = next((x for x in data["picks"] if x["id"] == req.id), None)
        if req.op == "add":
            s = req.source or {}
            source = {k: s.get(k) for k in ("novel_id", "novel_title", "chapter", "type", "text")}
            if not str(source.get("text") or "").strip():
                raise HTTPException(400, "That result has no passage to pick.")
            if not any(x["source"].get("text") == source["text"] for x in data["picks"]):
                fid = f"F{data.get('next_id') or len(data['picks']) + 1}"
                data["next_id"] = int(fid[1:]) + 1
                data["picks"].append({"id": fid, "source": source, "adapted": None, "chapter": None,
                                      "status": "ready", "added_at": _time.time()})
        elif req.op not in ("update", "delete", "adapt"):
            raise HTTPException(400, "op must be add, update, delete or adapt")
        elif pick is None:
            raise HTTPException(404, f"No picked fight move {req.id}")
        elif req.op == "delete":
            data["picks"].remove(pick)
        elif req.op == "update":
            if req.adapted is not None:
                a = req.adapted
                pick["adapted"] = {"name": str(a.get("name") or "").strip()[:120], "text": str(a.get("text") or "").strip()[:900],
                                   "characters": (pick.get("adapted") or {}).get("characters") or []}
            if req.chapter is not None:
                pick["chapter"] = req.chapter if req.chapter > 0 else None
            if req.status in ("ready", "used"):
                pick["status"] = req.status
        else:   # adapt
            gen_cfg = _get_generation_cfg()
            provider = req.provider or gen_cfg.get("default_provider", "anthropic")
            try:
                pick["adapted"] = _adapt_fight_pick(project, pick["source"], provider,
                                                    _get_models_cfg().get(provider, ""), _get_key(provider))
            except Exception as e:
                _log_error("fight_adapt", f"project={req.project_id} pick={req.id} error={e}")
                raise HTTPException(502, f"Adapting failed: {str(e)[:200]}")
        _save_fight_picks(req.project_id, data)
    return {"ok": True, "picks": data["picks"]}


class VoiceMatchRequest(BaseModel):
    project_id: str
    chapter_number: int
    text: Optional[str] = None   # the Reader's current draft (unsaved edits included); else the saved file


@router.post("/voice-match")
def voice_match(req: VoiceMatchRequest):
    """Corpus voice-match score for a chapter (see _voice_match), plus the score it
    had before its end-of-chapter polish when one ran — a free, deterministic
    check, no LLM call. Also returns the end-of-chapter humor count when one ran;
    that one is read back from the sidecar, never re-counted here."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    project = json.loads(project_file.read_text(encoding="utf-8"))
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    text = req.text
    if not text:
        path = gen_dir / f"ch{req.chapter_number:03d}_generated.txt"
        if not path.exists():
            raise HTTPException(404, f"Chapter {req.chapter_number} has not been written yet.")
        text = path.read_text(encoding="utf-8")
    result = _voice_match(project, text)
    try:
        chk = _combat_check(project, text, _chapter_plan_has_fight(project, req.chapter_number))
        if chk.get("signals"):
            result["combat"] = chk   # measured live, like the voice signals; not part of the score
    except Exception:
        pass
    sidecar = gen_dir / f"ch{req.chapter_number:03d}_voice.json"
    if sidecar.exists():
        try:
            saved = json.loads(sidecar.read_text(encoding="utf-8"))
            before = saved.get("before") or {}
            if before.get("total"):
                result["before_polish"] = {"score": before.get("score"), "total": before.get("total")}
            if isinstance(saved.get("humor"), dict):
                result["humor"] = saved["humor"]
        except Exception:
            pass
    return {"ok": True, **result}


def _scene_seam_polish_pass(project_id: str, chapter_number: int, full_text: str, parts: list,
                            ch_plan: dict, provider: str, model: str, api_key: str,
                            project: Optional[dict] = None, humor_note: Optional[str] = None,
                            combat_note: Optional[str] = None) -> Optional[tuple]:
    """Final pass over an Interactive/scene-by-scene chapter, once every
    segment is written — looks ONLY at the finished prose (no re-planning,
    no new corpus search), and tightens what's already there:
      1. Seams — segments were each written in isolation with only a short
         prose tail as context, so a transition between two scenes can read
         slightly disjoint (a repeated beat, an abrupt tone jump, a dangling
         reference to something the previous segment already resolved).
      2. This chapter's OWN self-check fields — hard_constraints and
         anti_patterns were given as WRITING instructions, never verified
         after the fact; min_dialogue_lines per scene is the same. This pass
         is the first thing that actually checks the finished prose against
         them, the way the skeleton schema's hard_constraints docstring says
         it should be used.
      3. Sentence-mix drift against the author's own style DNA — the same
         analyze_style_dna measurement Round-Trip Validation uses (a real,
         non-heuristic signal, unlike its scene-count check), so if a chapter
         leans too hard on short/long sentences at the expense of the
         author's target medium-sentence ratio, this pass can rebalance
         individual sentences without touching plot or content.

      4. The chapter-level house-style rules (explicit realization, stated
         point, named emotion) — add-only-if-missing, once per chapter.
      5. Humor, only when humor_note is given (the end-of-chapter Humor DNA
         check found the chapter short of its target): add that many beats.
      6. Combat, only when combat_note is given (the free Combat DNA check found
         the chapter's fight missing sounds, a hit landing, a ruthless line...):
         add those to the fight as written. The caller re-measures it after.

    Returns (status, polished_text, info, humor_added): status "changed" (text +
    one-line summary), "unchanged" (nothing needed fixing), "failed" (info says
    why — the caller must surface it, not report it as "nothing needed fixing"),
    or "skipped" (not applicable). humor_added is None without a humor_note, else
    the added beats as {"text", "gag"} (gag: the running-gag id the polish tagged
    it with, or None), each one checked to be new and present in the polished
    chapter. The caller versions the pre-polish draft before writing the polished
    text back.

    Deliberately NOT run when there was only one segment (nothing to seam)
    and NOT run for the non-scene-plan fallback path (no per-scene checks to
    verify), so it costs nothing on projects that don't use scene plans."""
    humor_added = [] if humor_note else None
    if len(parts) < 2 or not ch_plan:
        return ("skipped", None, "", humor_added)

    checks = []
    hard_constraints = ch_plan.get("hard_constraints")
    if isinstance(hard_constraints, dict) and hard_constraints.get("description"):
        checks.append(f"HARD CONSTRAINTS (must all hold true in the text below): {hard_constraints['description']}")
    anti_patterns = ch_plan.get("anti_patterns") or []
    if anti_patterns:
        checks.append("MUST NOT BE PRESENT (explicitly forbidden for this chapter):\n"
                      + "\n".join(f"  - {a}" for a in anti_patterns))
    scenes = ch_plan.get("scenes") or []
    dialogue_reqs = [f"  - Scene {s.get('scene_number','?')} ({s.get('scene_type','?')}): at least "
                     f"{s['min_dialogue_lines']} distinct spoken lines from different voices"
                     for s in scenes if s.get("min_dialogue_lines")]
    if dialogue_reqs:
        checks.append("DIALOGUE DENSITY REQUIRED PER SCENE (verify actual quoted lines, not narrator summary):\n"
                      + "\n".join(dialogue_reqs))

    # Style DNA drift against the Author Profile (seeded from the corpus's own
    # style DNA) — sentence mix, paragraph mix, transitions. See _style_dna_drift_notes.
    checks.extend(_style_dna_drift_notes(project, full_text))

    # Chapter-level house style — the three "the chapter does this SOMEWHERE" rules,
    # moved here off the per-segment house-style gate. Judged per ~300-word segment
    # they failed the corpus's own prose 73% (realizations, at ~450 words) / 100%
    # (stated point) / 81% (named emotion), and the segment judge flip-flopped on
    # "stated point". Here: once, over the whole chapter, as presence-only
    # instructions that add at most one line each and never touch a chapter that
    # already does it — no pass/fail verdict to misread, nothing blocking.
    house_style_items = []
    if len(full_text.split()) >= 400 and not any(p in full_text.lower() for p in _NARRATOR_INTRUSION_PHRASES):
        house_style_items.append(
            "REALIZATION: nowhere in this chapter is a character's realization narrated explicitly (e.g. \"Only then "
            "did he realize...\", \"He understood...\"). At the single most natural moment where a character figures "
            "something out, add ONE short explicit realization line.")
    house_style_items.append(
        "STATED POINT: this house style narrates what at least one key beat MEANS, directly, once per chapter (e.g. "
        "\"This proved his resolve.\"). If no sentence anywhere in the chapter already does that, add ONE such "
        "sentence at the most important beat. If at least one already exists, change nothing for this item.")
    house_style_items.append(
        "NAMED EMOTION: this house style names a character's emotion with an actual emotion word at least once near a "
        "charged moment — any emotion word counts (shame, fury, dread, relief, love, grief...). If no emotion is "
        "named anywhere in the chapter, name one at the most charged moment. If one already is, change nothing for "
        "this item.")
    checks.append("CHAPTER-LEVEL HOUSE STYLE (judge the WHOLE chapter, not any one part of it):\n"
                  + "\n".join(f"  - {item}" for item in house_style_items))
    if humor_note:
        checks.append(humor_note)
    if combat_note:
        checks.append(combat_note)
    extra_jobs, extra_nums = "", []
    if humor_note:
        extra_nums.append(str(5 + len(extra_nums)))
        extra_jobs += (f"\n{extra_nums[-1]}. HUMOR: add the number of humor beats the HUMOR item asks for, each a line "
                       "or two woven into a moment that's already there (a reaction, a dry remark, an ironic aside). "
                       "Never a new scene, and never a change to what happens.")
    if combat_note:
        extra_nums.append(str(5 + len(extra_nums)))
        extra_jobs += (f"\n{extra_nums[-1]}. COMBAT: add only what the COMBAT item asks for, inside the fight as "
                       "written: sounds on impacts that already happen, a hit landing on a blow that already happens, "
                       "one ruthless line where the fight already has dialogue, sharper verbs. Never a new blow, move "
                       "or outcome.")
    additions = ("This and item" + ("s " + " and ".join(extra_nums) if len(extra_nums) > 1 else f" {extra_nums[0]}")
                 + " are the only kinds of addition allowed in this pass" if extra_nums
                 else "This is the only kind of addition allowed in this pass")
    humor_format = ('HUMOR ADDED: the exact text of each humor beat you added, separated by " | ", with a running '
                    'gag\'s id in brackets before a beat that calls back to it, e.g. [G2] (write none if you added '
                    'none)\n' if humor_note else "")

    if not checks:
        checks.append("No specific hard constraints were set for this chapter — focus entirely on seam smoothness below.")

    prompt = f"""You are doing a FINAL POLISH PASS on Chapter {chapter_number}, which was written in {len(parts)} separate segments (the author answered interactive questions between each one). You are NOT re-planning or rewriting the story — you are looking ONLY at the prose below and fixing what's actually wrong with it as written.

THE FULL CHAPTER AS WRITTEN:
{full_text}

CHECK AGAINST THIS CHAPTER'S OWN REQUIREMENTS:
{chr(10).join(checks)}

YOUR JOB — fix ONLY these categories of problem, nothing else:
1. SEAMS: because each segment was written with only a short prose tail as context, a transition between two segments may repeat a beat that already happened, jump tone abruptly, or leave a dangling reference to something already resolved. Smooth these — the reader should never be able to tell where one segment ended and the next began.
2. SELF-CHECK VIOLATIONS: if the prose actually violates a hard constraint, contains something on the forbidden list, or a scene is short on required dialogue lines, fix it directly in the text.
3. STYLE DNA DRIFT (only what's listed above): sentence mix — rebalance by rewriting individual sentences (combining short ones, splitting long ones) where it reads naturally; paragraph mix — insert paragraph breaks only, never change the words; transitions — add one or two only where a beat genuinely shifts; corpus voice — change punctuation on existing lines (or rephrase a line into a question) exactly as each item says, never add new lines. None of this may change what happens, only how the prose is built.
4. CHAPTER-LEVEL HOUSE STYLE: for each item listed above, look at the WHOLE chapter first. Only if the chapter genuinely lacks it anywhere, add the ONE short line that item describes, at the most natural spot. {additions}, and never more than one line per item.{extra_jobs}

DO NOT: change the plot, add new scenes, remove content that isn't actually a problem, rewrite dialogue/prose style that's merely a matter of taste, or pad length. This is a targeted fix pass, not a rewrite. If the chapter already reads seamlessly and satisfies its own requirements, change nothing.

Respond in EXACTLY this format, nothing before or after it:
CHANGED: yes or no
SUMMARY: one sentence describing what you fixed (leave blank if nothing changed)
{humor_format}<<<CHAPTER
the full chapter text with your fixes applied — omit this whole block if CHANGED is no
CHAPTER>>>"""

    # Plain text between markers, not the whole chapter inside a JSON string: a
    # dialogue-heavy chapter is full of quote marks, one unescaped quote broke the
    # JSON, and the failure was swallowed and reported upstream as "nothing needed
    # fixing". A 600s timeout because this rewrites the entire chapter in one call.
    try:
        prompt += _word_budget_note(project, chapter_number, full_text, pid=project_id, label="seam polish")
        raw = _call_llm(prompt, provider, model, api_key, timeout=600) or ""
    except Exception as e:
        _log_error("scene_seam_polish", f"project={project_id} chapter={chapter_number} error={e}")
        return ("failed", None, f"the model call failed ({str(e)[:120]})", humor_added)
    m_changed = re.search(r"^\s*CHANGED:\s*(yes|no)\b", raw, re.I | re.M)
    if not m_changed:
        return ("failed", None, "the reply didn't follow the expected format", humor_added)
    if m_changed.group(1).lower() == "no":
        return ("unchanged", None, "", humor_added)
    m_text = re.search(r"<<<CHAPTER\s*\n(.*?)\n\s*CHAPTER>>>", raw, re.S)
    if not m_text:
        return ("failed", None, "the polished chapter was missing or cut off before its end marker", humor_added)
    polished = m_text.group(1).strip()
    # This pass may smooth a repeated beat but never cut content; a big drop means
    # the output was truncated or the model rewrote instead of polishing.
    before, after = len(full_text.split()), len(polished.split())
    if after < before * 0.85:
        return ("failed", None, f"the polished text came back at {after} words vs {before} — rejected as "
                                f"truncated or over-cut", humor_added)
    m_sum = re.search(r"^\s*SUMMARY:\s*(.*)$", raw, re.I | re.M)
    if humor_note:
        # Count a claimed beat only if its text is in the polished chapter and wasn't
        # already in the draft — the polish can't claim an existing line as added.
        m_humor = re.search(r"^\s*HUMOR ADDED:\s*(.*)$", raw, re.I | re.M)
        if m_humor:
            new_words, old_words = _quote_words(polished), _quote_words(full_text)
            for q in m_humor.group(1).split("|"):
                tag = re.match(r"\s*\[(G\d+)\]\s*", q, re.I)
                q = (q[tag.end():] if tag else q).strip().strip('"\u201c\u201d').strip()
                if q and q.lower() != "none" and any(
                        pr in new_words and pr not in old_words for pr in _quote_probes(q)):
                    humor_added.append({"text": q, "gag": tag.group(1).upper() if tag else None})
    return ("changed", polished, m_sum.group(1).strip() if m_sum else "", humor_added)


_REPEAT_STOP = frozenset("the a an and or but of to in on at for with from by as is was were be been he she it his her him they them their its that this these those then than so not no into out up down over under again had has have do did does would could should will can may might said asked there here when while which who whom what where how all any each both more most other some such only own same too very just".split())


def _repeat_matches(prose: str, parts: list) -> dict:
    """Word-matching layer: {paragraph index: the earlier paragraph it matches} for paragraphs of `prose` that re-tell something
    already in `parts`: near-verbatim copies and paraphrases (same content words, similar length). Short lines only count next
    to a repeated long one. These are CANDIDATES: the AI judge decides whether each re-telling is allowed."""
    import difflib
    paras = [q.strip() for q in re.split(r"\n\s*\n", prose or "") if q.strip()]
    earlier = [q.strip() for part in (parts or []) for q in re.split(r"\n\s*\n", part or "") if q.strip()]
    if not paras or not earlier:
        return {}
    norm = lambda q: re.sub(r"\W+", " ", q.lower()).strip()
    words = lambda q: {w for w in re.findall(r"[a-z']+", q.lower()) if w not in _REPEAT_STOP and len(w) > 2}
    e_norm = [norm(q) for q in earlier]
    first_at = {}
    for k, nq in enumerate(e_norm):
        first_at.setdefault(nq, k)
    e_words = [words(q) for q in earlier]
    e_len = [len(q.split()) for q in earlier]
    match = [None] * len(paras)
    for j, q in enumerate(paras):
        n, w, ln = norm(q), words(q), len(q.split())
        if n in first_at:
            match[j] = earlier[first_at[n]]
            continue
        if not w:
            continue
        for k, (m, ew, el) in enumerate(zip(e_norm, e_words, e_len)):
            if not ew:
                continue
            ov = len(w & ew) / min(len(w), len(ew))
            if ln >= 18 and el >= 18 and 0.5 <= ln / el <= 2.0 and ov >= 0.7:
                match[j] = earlier[k]                 # same content words at a similar length: a paraphrase
                break
            if ov >= 0.6 and len(n) > 60 and abs(len(m) - len(n)) < 0.3 * len(n) \
                    and difflib.SequenceMatcher(None, m, n).ratio() > 0.8:
                match[j] = earlier[k]                 # near-verbatim
                break
    for j, q in enumerate(paras):
        if match[j] is not None and len(q.split()) < 6:       # a refrain on its own is not a re-telling
            near = (j > 0 and match[j - 1] is not None and len(paras[j - 1].split()) >= 6) or \
                   (j + 1 < len(paras) and match[j + 1] is not None and len(paras[j + 1].split()) >= 6)
            if not near:
                match[j] = None
    return {j: m for j, m in enumerate(match) if m is not None}


def _repeated_paragraph_idx(prose: str, parts: list) -> list:
    """Indices of the paragraphs of `prose` that the word-matching layer says re-tell something in `parts`."""
    return sorted(_repeat_matches(prose, parts))


_REPEAT_RULE = "DON'T re-tell what is already written — every part must add new story"


def _llm_repeat_gate_on() -> bool:
    """The AI judge of the repeat gate is on unless config.json says "llm_repeat_gate": false (it costs one AI call per attempt)."""
    try:
        return bool(_read_config().get("llm_repeat_gate", True))
    except Exception:
        return True
_LENGTH_RULE = "DON'T run over the scene's word budget"
_LENGTH_TOLERANCE = 1.25     # a part may run up to 25% over its budget before the gate objects


def _read_text_safe(path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return ""


def _chapter_budget_words(project: dict, ch: int) -> int:
    """A chapter's word budget: the sum of its plan's scene budgets, else the fixed chapter length."""
    sk = next((c for c in ((project or {}).get("chapter_skeletons") or []) if isinstance(c, dict) and c.get("number") == ch), None)
    tot = sum(x["estimated_word_count"] for x in ((sk or {}).get("scenes") or [])
              if isinstance(x, dict) and isinstance(x.get("estimated_word_count"), (int, float)) and x["estimated_word_count"] > 0)
    return int(tot) if tot else _CHAPTER_TARGET_WORDS


def _word_budget_note(project, ch, text=None, kind: str = "chapter", chapter_text=None, pid=None, label: str = "",
                      words=None) -> str:
    """Every post-generation operation that can change a chapter's length counts the words of what it is about to change
    FIRST, so it knows the budget (author's rule). Returns a prompt block stating that count, the budget and the ceiling,
    and logs the count. kind: "chapter" (the whole chapter is rewritten), "passage" (a selection/paragraph inside the
    chapter: it may grow only by the chapter's remaining headroom), "insert" (lines added to the chapter)."""
    if project is None and pid:
        try:
            project = json.loads((CORPUS_PATH / "projects" / pid / "project.json").read_text(encoding="utf-8"))
        except Exception:
            project = {}
    w = int(words) if words is not None else len((text or "").split())
    budget = _chapter_budget_words(project or {}, ch)
    limit = int(budget * _LENGTH_TOLERANCE)
    if kind == "chapter":
        cap = limit if w <= limit else w
        body = f"Chapter {ch} is {w} words now. Its planned budget is {budget} words (up to {limit} allowed)."
        what = f"chapter {ch}"
    else:
        ch_words = len(chapter_text.split()) if chapter_text is not None else w
        headroom = max(0, limit - ch_words)
        if kind == "insert":
            cap = ch_words + headroom
            body = (f"Chapter {ch} is {ch_words} words now against a {budget}-word budget (up to {limit} allowed), so everything "
                    f"you add may come to at most {headroom} words in total.")
            w, what = ch_words, f"chapter {ch}"
        else:
            cap = w + headroom
            body = (f"The passage you are changing is {w} words now. Chapter {ch} is {ch_words} words against a {budget}-word "
                    f"budget (up to {limit} allowed), so this passage may grow by at most {headroom} words.")
            what = "the passage"
    over = (w >= limit) if kind == "chapter" else (cap <= w)
    tail = (" It is already at or over its budget: your version must NOT be longer than it is now - the same length or shorter."
            if over else f" Your version must not exceed {cap} words.")
    if pid:
        _progress_log(pid, f"WORD BUDGET{' (' + label + ')' if label else ''}: counted {w} words in {what} before changing it; "
                           f"budget {budget}, ceiling {cap}")
    return f"\n\nWORD COUNT (counted before you start): {body}{tail}\n"


# ── Fuzzy layer: nomic-embed-text embeddings of the WRITTEN chapters. A finished chapter indexes itself (every paragraph embedded and
#    saved in generated/<project>/_chapter_index.json); the repeat gate and the skeleton check search it, so a paragraph that
#    re-tells earlier text in different words is caught by meaning. Calibrated on a real chapter with known re-tellings: at 0.88 it
#    catches 109 of the 113 paragraphs the word-matcher flagged and finds real ones the word-matcher missed. ──
_EMBED_REPEAT_THRESHOLD = 0.88
_EMBED_MIN_WORDS = 12
_PARA_EMB_CACHE: dict = {}
_CHAPTER_INDEX_LOCK = _threading.Lock()


def _embed_repeat_gate_on() -> bool:
    """The fuzzy (embedding) layer of the repeat gate is on unless config.json says "embed_repeat_gate": false."""
    try:
        return bool(_read_config().get("embed_repeat_gate", True))
    except Exception:
        return True


def _unit_embed(text: str):
    """A unit-length nomic embedding of `text` (cached in memory by its hash), or None when it can't be made."""
    import numpy as np, hashlib
    key = hashlib.sha1(text.encode("utf-8")).hexdigest()
    v = _PARA_EMB_CACHE.get(key)
    if v is None:
        from routers.corpus_tools.corpus import _embed_query
        raw = np.array(_embed_query(text), dtype=np.float32)
        n = float(np.linalg.norm(raw))
        if n == 0:
            return None
        v = raw / n
        if len(_PARA_EMB_CACHE) > 6000:
            _PARA_EMB_CACHE.clear()
        _PARA_EMB_CACHE[key] = v
    return v


def _chapter_index_path(pid: str) -> Path:
    return CORPUS_PATH / "generated" / pid / "_chapter_index.json"


def _load_chapter_index(pid: str) -> dict:
    try:
        d = json.loads(_chapter_index_path(pid).read_text(encoding="utf-8"))
        if isinstance(d, dict) and isinstance(d.get("chapters"), dict):
            return d
    except Exception:
        pass
    return {"model": "nomic-embed-text", "chapters": {}}


def _index_chapter(pid: str, ch: int, text: str = None) -> int:
    """Embed every paragraph of a written chapter (12+ words) and save it in the project's chapter index. A chapter whose text
    has not changed since it was indexed is skipped. Returns how many paragraphs are indexed."""
    import numpy as np, hashlib, base64
    if text is None:
        text = _read_text_safe(CORPUS_PATH / "generated" / pid / f"ch{ch:03d}_generated.txt")
    if not text.strip():
        return 0
    h = hashlib.sha1(text.encode("utf-8")).hexdigest()
    idx = _load_chapter_index(pid)
    cur = idx["chapters"].get(str(ch))
    if cur and cur.get("hash") == h:
        gen = CORPUS_PATH / "generated" / pid          # up to date, but a chapter deleted since still drops out of the index
        gone = [k for k in idx["chapters"] if not (gen / f"ch{int(k):03d}_generated.txt").exists()]
        if gone:
            with _CHAPTER_INDEX_LOCK:
                idx = _load_chapter_index(pid)
                for k in gone:
                    idx["chapters"].pop(k, None)
                tmp = _chapter_index_path(pid).with_suffix(".tmp")
                tmp.write_text(json.dumps(idx, ensure_ascii=False), encoding="utf-8")
                tmp.replace(_chapter_index_path(pid))
        return len(cur.get("paras") or [])
    rows = []
    for q in _paragraphs_of(text):
        if len(q.split()) >= _EMBED_MIN_WORDS:
            v = _unit_embed(q)
            if v is not None:
                rows.append({"t": q, "v": base64.b64encode(v.astype(np.float16).tobytes()).decode("ascii")})
    with _CHAPTER_INDEX_LOCK:
        idx = _load_chapter_index(pid)
        idx["chapters"][str(ch)] = {"hash": h, "paras": rows, "at": _time.time()}
        # chapters that no longer exist on disk drop out of the index
        gen = CORPUS_PATH / "generated" / pid
        for k in list(idx["chapters"]):
            if not (gen / f"ch{int(k):03d}_generated.txt").exists():
                idx["chapters"].pop(k, None)
        path = _chapter_index_path(pid)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps(idx, ensure_ascii=False), encoding="utf-8")
        tmp.replace(path)
    return len(rows)


def _index_chapter_async(pid: str, ch: int):
    """A chapter indexes itself right after it is finished, in the background (a failure just means the next use re-indexes it)."""
    def run():
        try:
            n = _index_chapter(pid, ch)
            _progress_log(pid, f"INDEX Ch.{ch}: {n} paragraph(s) embedded (nomic) — the repeat gate and the skeleton check can now search it", "success")
        except Exception as e:
            _progress_log(pid, f"INDEX Ch.{ch}: couldn't be indexed yet ({str(e)[:80]}) — it will be when first needed", "warn")
    _threading.Thread(target=run, daemon=True).start()


def _earlier_chapter_vectors(pid: str, before: int) -> list:
    """[(chapter, paragraph text, unit vector)] for every written chapter earlier than `before`; stale or missing entries are
    (re)indexed first, so an edited chapter is always searched as it reads now."""
    import numpy as np, base64
    out = []
    for n, text in _written_chapters(pid, before):
        try:
            _index_chapter(pid, n, text)
        except Exception:
            continue
        for row in (_load_chapter_index(pid)["chapters"].get(str(n)) or {}).get("paras", []):
            v = np.frombuffer(base64.b64decode(row["v"]), dtype=np.float16).astype(np.float32)
            nn = float(np.linalg.norm(v))
            if nn:
                out.append((n, row["t"], v / nn))
    return out


def _embedding_repeat_matches(prose: str, session: dict, pid: str) -> dict:
    """The fuzzy layer: {paragraph index: (where, earlier text, similarity)} for paragraphs of the new segment whose nomic
    embedding is within _EMBED_REPEAT_THRESHOLD of a paragraph of an earlier chapter or an earlier part of this chapter."""
    import numpy as np
    paras = _paragraphs_of(prose)
    cand = [(i, q) for i, q in enumerate(paras) if len(q.split()) >= _EMBED_MIN_WORDS]
    if not cand:
        return {}
    earlier = [(f"chapter {n}", t, v) for n, t, v in _earlier_chapter_vectors(pid, session.get("chapter_number") or 1)]
    for pi, part in enumerate(session.get("parts") or []):
        for q in _paragraphs_of(part):
            if len(q.split()) >= _EMBED_MIN_WORDS:
                v = _unit_embed(q)
                if v is not None:
                    earlier.append((f"part {pi + 1} of this chapter", q, v))
    if not earlier:
        return {}
    M = np.stack([e[2] for e in earlier])
    out = {}
    for i, q in cand:
        v = _unit_embed(q)
        if v is None:
            continue
        sims = M @ v
        k = int(sims.argmax())
        if float(sims[k]) >= _EMBED_REPEAT_THRESHOLD:
            out[i] = (earlier[k][0], earlier[k][1], float(sims[k]))
    return out


def _nearest_written_hint(pid: str, ch: int, sk: dict) -> str:
    """Evidence for the skeleton overlap check: for the plan's key event, hook, beats and scenes, the closest passages of the
    written chapters by nomic embedding. The AI judge decides what it means."""
    import numpy as np
    earlier = _earlier_chapter_vectors(pid, ch)
    if not earlier:
        return ""
    M = np.stack([e[2] for e in earlier])
    items = [("key event", sk.get("key_event")), ("hook", sk.get("hook"))]
    items += [("beat", b.get("event") if isinstance(b, dict) else b) for b in (sk.get("beats") or [])]
    items += [(f"scene {x.get('scene_number')}", x.get("structure_notes")) for x in (sk.get("scenes") or []) if isinstance(x, dict)]
    hits = []
    for label, txt in items:
        if not txt or not str(txt).strip():
            continue
        try:
            v = _unit_embed(str(txt)[:600])
        except Exception:
            return ""
        if v is None:
            continue
        sims = M @ v
        k = int(sims.argmax())
        if float(sims[k]) >= 0.6:
            hits.append((float(sims[k]), f"- plan {label}: {str(txt)[:90]!r} ≈ written chapter {earlier[k][0]}: {earlier[k][1][:140]!r} (similarity {float(sims[k]):.2f})"))
    hits.sort(key=lambda h: -h[0])
    return ("NEAREST WRITTEN PASSAGES for the plan's parts (nomic embedding search; evidence only, you decide):\n"
            + "\n".join(h[1] for h in hits[:6]) + "\n\n") if hits else ""


def _llm_repeat_adjudicate(prose: str, session: dict, pid: str, provider, model, api_key, cands: dict):
    """The AI judge of the repeat gate. The word-matching and embedding layers only PROPOSE candidates (`cands`: paragraph index ->
    {"match": earlier text, "by": layers}); the judge rules on each one, case by case, whether the re-telling is ALLOWED, and
    also names any paragraph that re-tells earlier text which neither layer saw. Allowed: a deliberate callback or echo, a
    recurring motif or running line, a brief recap the story needs that adds something new, the same moment from another
    point of view with new information. Not allowed: re-narrating an event, reveal, discovery, answer or image already on
    the page with nothing new. Returns (allowed {idx: reason}, extra_blocked [idx], notes {idx: reason}) or None (could not run)."""
    paras = [q.strip() for q in re.split(r"\n\s*\n", prose or "") if q.strip()]
    parts = [t for t in (session.get("parts") or []) if t]
    block = _written_so_far_block(pid, session.get("chapter_number") or 1) if pid else ""
    if not paras or (not block and not parts and not cands):
        return {}, [], {}
    earlier_parts = " ".join(" ".join(parts).split()[-1400:])
    numbered = "\n\n".join(f"[{i + 1}] {q[:900]}" for i, q in enumerate(paras[:60]))
    cand_lines = "\n".join(
        f"  [{i + 1}] resembles earlier text ({'+'.join(sorted(c.get('by') or []))}): \"{str(c.get('match'))[:260]}\""
        for i, c in sorted(cands.items()) if i < 60)
    prompt = ("You are a continuity editor judging a NEW SEGMENT of a web novel chapter for RE-TELLING.\n\n"
              + (block + "\n\n" if block else "")
              + (f"EARLIER PARTS OF THIS SAME CHAPTER (most recent words):\n\"\"\"\n{earlier_parts}\n\"\"\"\n\n" if earlier_parts else "")
              + f"NEW SEGMENT, paragraphs numbered:\n{numbered}\n\n"
              + (f"A similarity check flagged these paragraphs as resembling earlier text. Rule on EACH ONE, case by case:\n{cand_lines}\n\n" if cand_lines else "")
              + "A re-telling is ALLOWED when it is a deliberate callback or echo, a recurring motif or running line, a brief recap "
                "the story needs that adds something new, or the same moment from another point of view with new information. "
                "It is NOT ALLOWED when it re-narrates an event, reveal, discovery, answer or image already on the page and "
                "adds nothing. Also name any OTHER numbered paragraph that is a real, not-allowed re-telling (even in different "
                "words) that the check did not flag. Output ONLY this JSON, no fences:\n"
              + "{\"verdicts\": [{\"paragraph\": 3, \"allowed\": true, \"reason\": \"<=20 words\"}], "
                "\"other_repeats\": [{\"paragraph\": 5, \"already\": \"what it re-tells and where (<=20 words)\"}]}")
    try:
        data = _parse_json_from_text(_call_llm(prompt, provider, model, api_key, timeout=240, abort_key=(pid, "interactive")))
    except Exception:
        return None
    if not isinstance(data, dict) or not isinstance(data.get("verdicts", []), list) or not isinstance(data.get("other_repeats", []), list):
        return None
    def _i(x):
        try:
            return int(x.get("paragraph")) - 1
        except Exception:
            return None
    allowed, notes = {}, {}
    for v in data.get("verdicts", []):
        i = _i(v) if isinstance(v, dict) else None
        if i is None or i not in cands:
            continue
        if v.get("allowed") is True:
            allowed[i] = str(v.get("reason") or "")[:160]
        else:
            notes[i] = str(v.get("reason") or "")[:160]
    extra = []
    for o in data.get("other_repeats", []):
        i = _i(o) if isinstance(o, dict) else None
        if i is not None and 0 <= i < len(paras) and i not in cands and i not in extra:
            extra.append(i)
            notes[i] = str(o.get("already") or "")[:160]
    return allowed, sorted(extra), notes


def _scene_gate_failures(prose: str, session: dict, llm=None) -> list:
    """The scene gate: two more checks that sit beside the house-style gate and go through exactly the same flow
    (two automatic rewrites, then the author's Keep / Try again). Same record shape as _house_style_gate's."""
    out = []
    paras = [q.strip() for q in re.split(r"\n\s*\n", prose or "") if q.strip()]
    pid_ = session.get("project_id")
    cands = {}      # paragraph index -> {"match": earlier text, "by": [layers]}
    for j, m in _repeat_matches(prose, (session.get("parts") or []) + (session.get("prior_chapters") or [])).items():
        cands.setdefault(j, {"match": m, "by": []})["by"].append("word-match")
    if prose and pid_ and _embed_repeat_gate_on():       # fuzzy layer: nomic embeddings of what is written
        try:
            for j, (where, text, sim) in _embedding_repeat_matches(prose, session, pid_).items():
                c = cands.setdefault(j, {"match": f"{where}: {text}", "by": []})
                c["by"].append(f"embedding {sim:.2f}")
        except Exception as e:
            _progress_log(pid_, f"REPEAT GATE: the embedding layer couldn't run ({str(e)[:80]}) - Ollama/nomic down?", "warn")
    rep_idx = sorted(cands)
    notes = []
    if llm and prose and (cands or session.get("parts") or session.get("prior_chapters")
                          or _written_chapters(llm[3], session.get("chapter_number") or 1)):
        # (provider, model, api_key, project_id): the AI rules on every candidate, case by case, and adds what the checks missed
        verdict = _llm_repeat_adjudicate(prose, session, llm[3], llm[0], llm[1], llm[2], cands)
        if verdict is None:
            _progress_log(llm[3], "REPEAT GATE: the AI judge couldn't run - every flagged re-telling is treated as not allowed", "warn")
        else:
            allowed, extra, jnotes = verdict
            for i, why in sorted(allowed.items()):
                _progress_log(llm[3], f"REPEAT GATE: paragraph {i + 1} echoes earlier text, judged ALLOWED"
                                      + (f" — {why}" if why else ""), "info")
            rep_idx = sorted((set(cands) - set(allowed)) | set(extra))
            notes = [jnotes[i] for i in rep_idx if jnotes.get(i)]
    if not notes:
        notes = [f"{str(cands[i]['match'])[:80]}" for i in rep_idx if i in cands][:1]
    if rep_idx:
        out.append({
            "rule": _REPEAT_RULE,
            "hint": "delete each repeated paragraph, or replace it with the NEXT new moment — never re-narrate events or "
                    "images already in the chapter so far or in an earlier chapter",
            "detail": f"{len(rep_idx)} paragraph(s) re-tell earlier parts or chapters"
                      + (f" (e.g. {notes[0]})" if notes and notes[0] else ""),
            "paragraphs": rep_idx,
            "examples": [paras[j][:300] for j in rep_idx[:8]],
            "example_label": "PARAGRAPHS THAT RE-TELL EARLIER PARTS — remove or replace each with new story; copy every "
                             "other paragraph of the previous attempt unchanged",
        })
    budget = session.get("_seg_budget")
    words = len((prose or "").split())
    if budget and words > budget * _LENGTH_TOLERANCE:      # up to 25% over the budget is allowed
        out.append({
            "rule": _LENGTH_RULE,
            "hint": f"cut to {int(budget)} words if you can (never more than {int(budget * _LENGTH_TOLERANCE)}): same events, tighter",
            "detail": f"{words} words against a {int(budget)}-word budget (up to {int(budget * _LENGTH_TOLERANCE)} is allowed)",
        })
    return out


def _interactive_handle_segment(sid: str, session: dict, raw: str, provider: str, model: str,
                                api_key: str, project: dict, force_done: bool = False,
                                prompt: str = None, project_id: str = None, _gate_attempt: int = 0,
                                bypass_gate: bool = False):
    """Split a segment response into prose + (optional) decision block, update
    the session, and either return the next question or finish + save.

    prompt/project_id: the exact prompt that produced `raw` and the owning
    project — only needed for the house-style gate's own retry calls below;
    None is accepted (and the gate silently skipped) for any future caller
    that doesn't have them, so this stays backward-compatible rather than
    a hard requirement threaded through every call site.

    _gate_attempt: internal — how many times the gate has already bounced
    THIS segment back to the LLM. Caller never passes this.

    bypass_gate: True only when replaying the exact raw response the author
    already explicitly chose to "keep as written" after 2 failed retries —
    skips the check entirely so that replay can't loop straight back into
    the same "still fails" prompt with nothing new to try."""
    m = _DECISION_RE.search(raw) or _DECISION_RE_UNCLOSED.search(raw)
    decision = None
    if m and not force_done:
        prose = raw[:m.start()].strip()
        try:
            decision = json.loads(m.group(1))
        except Exception:
            decision = None
    else:
        prose = _DECISION_RE.sub("", raw).strip()

    # ── CORPUS HOUSE-STYLE GATE — every per-answer prose segment squeezes
    # through this before being accepted into session["parts"]. On failure,
    # bounce back to the LLM with the specific rule(s) it failed and why
    # (never a bare "try again"), up to 2 retries (3 attempts total, matching
    # this file's existing retry-cap convention — see _field_interactive_
    # finish's "retry once" comment for the precedent, extended by one here
    # since this is a compound multi-rule check rather than a single parse
    # failure). After 2 failed retries, don't silently give up OR silently
    # keep it — surface a real choice to the author via the SAME decision-
    # block mechanism the model itself uses, so the existing frontend needs
    # zero changes to render it (see the payload shape a few lines below).
    if prose:
        prose, _n_split = _split_long_paragraphs(prose)
        if _n_split:
            _progress_log(session.get("project_id") or project_id or "", f"INTERACTIVE Ch.{session.get('chapter_number','?')}: "
                          f"split {_n_split} long paragraph(s) at beat breaks (paragraph breaks only, no words changed)")
    if prompt is not None and project_id is not None and prose and not bypass_gate:
        _gate_failures = _house_style_gate(prose) + _scene_gate_failures(
            prose, session, (provider, model, api_key, project_id) if _llm_repeat_gate_on() else None)
        if _gate_failures and _gate_attempt < 2:
            _progress_log(project_id, f"INTERACTIVE Ch.{session.get('chapter_number','?')}: segment failed house-style "
                                      f"check — retrying ({_gate_attempt + 1}/2)…", "warn")
            _log_house_style_reasons(project_id, _gate_failures)
            # Always built on the ORIGINAL prompt (never the previous retry prompt),
            # so fix blocks don't nest; the block itself carries the failing draft.
            _retry_prompt = f"{prompt}\n\n" + _house_style_retry_block(prose, _gate_failures)
            raw2 = _call_llm(_retry_prompt, provider, model, api_key, timeout=300,
                             abort_key=(project_id, "interactive"))
            return _interactive_handle_segment(sid, session, raw2, provider, model, api_key, project,
                                               force_done=force_done, prompt=prompt, project_id=project_id,
                                               _gate_attempt=_gate_attempt + 1)
        if _gate_failures:
            # 2 retries already spent and still failing — ask the author
            # directly instead of looping forever or silently accepting
            # prose that misses the house style. Synthetic decision block:
            # same {question, options, recommended} shape the model's own
            # <<<DECISION>>> blocks use, so the existing frontend rendering
            # needs no special-casing for this path. "Keep it as written"
            # replays THIS EXACT raw/decision through a gate-bypassed call
            # (see the "continue" branch's _gate_pending_raw handling) —
            # it does NOT trigger a new LLM call, so the kept prose is
            # exactly what the author saw when deciding to keep it, not a
            # fresh, different generation.
            _rules_hit = ", ".join(f["rule"] for f in _gate_failures)
            _progress_log(project_id, f"INTERACTIVE Ch.{session.get('chapter_number','?')}: segment still fails "
                                      f"house-style check after 2 retries — asking you", "warn")
            _log_house_style_reasons(project_id, _gate_failures)
            gate_decision_payload = {
                "ok": True, "done": False, "session_id": sid,
                "segment": "",   # nothing new written yet — the draft is in gate_preview
                "parts_so_far": len(session["parts"]),
                "question": f"This segment doesn't match the corpus house style after 2 rewrite attempts "
                            f"({_rules_hit}). Keep it as written, or try rewriting once more?",
                "options": [
                    {"label": "Keep it as written", "description": "Accept this segment despite the style miss and continue the chapter.", "evidence": ""},
                    {"label": "Try rewriting again", "description": "Revise this draft once more, fixing the issues listed above.", "evidence": ""},
                ],
                "recommended": 0,
                # The failing draft and exactly why it failed — the popup shows both, so the
                # author decides keep/retry on what's actually wrong, not a bare rule name.
                "gate_preview": prose[:4000],
                "gate_reasons": [{"rule": f["rule"], "detail": f.get("detail", ""),
                                  "examples": f.get("examples") or [], "paragraphs": f.get("paragraphs")} for f in _gate_failures],
            }
            session["_gate_pending_raw"] = raw          # the FULL original response — replayed verbatim on "keep it"
            session["_gate_pending_force_done"] = force_done
            session["_gate_pending_prompt"] = prompt    # only needed if the author instead picks "try again"
            # The failing draft + its fix notes, for "try again" — that path used to
            # re-send the bare original prompt, so each author-level retry started
            # from zero and re-made failures the previous round had already fixed
            # (confirmed live: a realization line one draft added was gone again in
            # the next round's first draft).
            session["_gate_pending_retry_block"] = _house_style_retry_block(prose, _gate_failures)
            session["pending"] = gate_decision_payload
            session["in_flight"] = False
            session.pop("_rollback", None)
            session.setdefault("history", []).append(gate_decision_payload)
            _persist_interactive_session(sid, session)
            return gate_decision_payload

    _fp = session.get("_flight_parts")
    if prose and _fp is not None and len(session["parts"]) != _fp:
        _progress_log(session.get("project_id") or project_id or "", f"INTERACTIVE Ch.{session.get('chapter_number','?')}: a late result "
                      f"from an interrupted generation was dropped (the interview had moved on)", "warn")
        raise HTTPException(409, "That part was written for an earlier point in the interview, which has since been "
                                 "continued or rewound — it was dropped so nothing is duplicated.")
    if prose:
        session["parts"].append(prose)
        _wb = session.get("_seg_budget")
        if _wb and len(prose.split()) > _wb * _LENGTH_TOLERANCE:
            # Accepted over its word budget (the author chose "Keep it as written"): remembered, so the page shows
            # the segment in orange; clicking it offers the same Fix / Edit by hand as any flagged paragraph.
            session.setdefault("over_budget", {})[str(len(session["parts"]) - 1)] = {
                "words": len(prose.split()), "budget": int(_wb)}
    session.pop("_flight_parts", None)
    session.pop("_seg_budget", None)

    if decision and isinstance(decision.get("options"), list) and decision["options"]:
        payload = {
            "ok": True, "done": False, "session_id": sid,
            "segment": prose,
            "parts_so_far": len(session["parts"]),
            "question": decision.get("question", "Which direction should the story take?"),
            "options": [{"label": _trim_option_text(o.get("label", ""), 160), "description": _trim_option_text(o.get("description", ""), 600),
                        "evidence": _trim_option_text(o.get("evidence", ""), 200)}
                        for o in decision["options"][:3]],
            "recommended": decision.get("recommended", 0) if isinstance(decision.get("recommended"), int) else 0,
            "scene_words": _scene_word_status(session),
        }
        # Persist the pending question so an interrupted client (device lock,
        # closed tab) OR a backend restart can resume this exact state by
        # pressing Interactive again.
        session["pending"] = payload
        session["in_flight"] = False
        session.pop("_rollback", None)
        # Recorded at index len(decisions) — this IS the payload shown when
        # decisions has its current length, matching how "back" looks it up.
        session.setdefault("history", []).append(payload)
        _persist_interactive_session(sid, session)
        return payload

    # No decision block (model chose to finish, or final segment forced) → done: save.
    req_pid, ch_num = session["project_id"], session["chapter_number"]
    full_text = "\n\n".join(session["parts"]).strip()
    session["_finishing"] = True          # every part, the last included, is on disk while the finishing steps run
    _persist_interactive_session(sid, session)
    if not full_text:
        raise HTTPException(502, "Interactive generation produced no prose.")
    gen_dir = CORPUS_PATH / "generated" / req_pid
    gen_dir.mkdir(parents=True, exist_ok=True)
    gen_path = gen_dir / f"ch{ch_num:03d}_generated.txt"
    archived_v = None
    # The chapter is NOT written to disk yet: until the polish, humor and combat steps below are done it isn't a
    # finished chapter, so it must not appear in the Reader (or archive the previous version) half-finished. It is
    # written once, as the finished text, right after those steps.
    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: draft complete — {len(full_text.split())} words, "
                           f"{len(session['decisions'])} author decisions — finishing it (polish and checks)…", "success")

    # ── Seam polish — only when the chapter was actually written across
    # multiple scene segments (nothing to smooth for a single-shot chapter,
    # or the non-scene-plan fallback path). Looks only at the finished prose
    # and this chapter's own skeleton self-check fields — see
    # _scene_seam_polish_pass's docstring. Runs BEFORE the auto-summary below
    # so the summary describes the polished text, not the pre-polish draft.
    polish_note = ""
    # The Reader's Voice Match panel reads this chapter's end-of-chapter results back
    # from here. Rewritten on every finish; a stale one would describe an older draft.
    _sidecar = {}
    if len(session["parts"]) >= 2:
        _skeleton = project.get("chapter_skeletons", []) or []
        _ch_plan = next((c for c in _skeleton if c.get("number") == ch_num), None)
        if _ch_plan:
            # Humor DNA check: one AI call counts the finished chapter's humor beats.
            # A chapter short of the profile's target gets beats added by the polish
            # below. Never blocks: a failed count just means no humor item.
            _humor, _humor_note, _humor_tgt = None, None, _humor_target(project)
            if _humor_tgt:
                # The book's running gags, so the count can say which beats call back
                # to one, and the polish can aim an added beat at one that's due.
                _gags_known, _gags_due = [], []
                try:
                    _due_after = _gag_due_after(project)
                    _gags_known = sorted((g for g in _gag_rows(_load_gag_ledger(req_pid, project), req_pid, ch_num)
                                          if g.get("status") in ("active", "candidate")),
                                         key=lambda g: -(g["last_seen"] or 0))[:20]
                    _gags_due = sorted((g for g in _gags_known if g.get("status") == "active"
                                        and g["quiet"] is not None and g["quiet"] > _due_after),
                                       key=lambda g: -g["quiet"])
                except Exception as e:
                    _log_error("gag_ledger", f"project={req_pid} chapter={ch_num} error={e}")
                _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: humor check — counting humor beats…")
                try:
                    _slaps_open = [s for s in _slap_rows(_load_gag_ledger(req_pid, project), req_pid, ch_num)
                                   if s.get("status") != "retired" and s["state"] != "slapped"][:15]
                except Exception:
                    _slaps_open = []
                _humor = _humor_beats(full_text, provider, model, api_key, gags=_gags_known, slaps=_slaps_open)
                if _humor.get("error"):
                    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: humor check couldn't run — {_humor['error']}. "
                                           f"Carrying on without it.", "warn")
                    _humor = None
                else:
                    _humor_note = _humor_polish_note(_humor["count"], _humor_tgt, _gags_due)
                    _dropped = (f"; {_humor['dropped']} listed beat{'' if _humor['dropped'] == 1 else 's'} dropped, "
                                f"quote not found in the chapter" if _humor["dropped"] else "")
                    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: humor check — {_humor_summary(_humor)}; Humor "
                                           f"DNA target about {_humor_tgt['average']} per chapter{_dropped}"
                                           + (f" → the polish will add {min(2, _humor_tgt['minimum'] - _humor['count'])}"
                                              if _humor_note else " ✓"))
            # Combat DNA check: free (no AI call), only for a chapter with a fight. What the
            # fight lacks goes to the polish as add-if-absent asks; never blocks.
            _combat, _combat_note, _plan_fight = None, None, _chapter_plan_has_fight(project, ch_num)
            try:
                _combat = _combat_check(project, full_text, _plan_fight)
                if _combat.get("signals"):
                    _combat_note = _combat_polish_note(_combat, _profile_dna(project, "combat_dna"))
                    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: combat check — {_combat_summary(_combat)}"
                                           + (f" → the polish will add: {', '.join(_combat['missing'])}" if _combat_note
                                              else " ✓"))
            except Exception as e:
                _log_error("combat_check", f"project={req_pid} chapter={ch_num} error={e}")
                _combat = None
            _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: seam polish — checking scene transitions and self-check fields…")
            status, polished_text, polish_info, humor_added = _scene_seam_polish_pass(
                req_pid, ch_num, full_text, _scene_parts(session["parts"], session.get("scene_q_budget")), _ch_plan, provider, model, api_key, project=project,
                humor_note=_humor_note, combat_note=_combat_note)
            if status == "changed":
                # The polish rewrites the whole chapter in place. It used to archive the unpolished draft as a second
                # version, so every finished interview left TWO versions; the author wants ONE version after the
                # last interview question, so no copy is made here. (The unpolished parts are still in the chapter's
                # parts sidecar, written just before this step.)
                _dna_change = _style_dna_report(project, full_text, polished_text)
                if _dna_change:
                    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: style DNA — {_dna_change}")
                try:
                    # Before/after voice-match score, read back by the Reader's Voice Match panel.
                    _vm_before, _vm_after = _voice_match(project, full_text), _voice_match(project, polished_text)
                    _sidecar.update({"before": _vm_before, "after": _vm_after})
                    if _vm_before["total"]:
                        _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: corpus voice match "
                                               f"{_vm_before['score']}/{_vm_before['total']} → "
                                               f"{_vm_after['score']}/{_vm_after['total']}", "success")
                except Exception:
                    pass
                full_text = polished_text
                polish_note = f"\nSeam polish: {polish_info}" if polish_info else "\nSeam polish applied."
                _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: seam polish applied — "
                                       f"{polish_info or 'fixed transitions/self-check issues'}", "success")
            elif status == "failed":
                _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: seam polish couldn't be applied — {polish_info}. "
                                       f"The chapter was saved as written, unpolished.", "warn")
            elif status == "unchanged":
                _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: seam polish — nothing needed fixing")
            if _humor:
                _added = humor_added or []
                _after = _humor["count"] + len(_added)
                _sidecar["humor"] = {"before": _humor["count"], "after": _after, "added": [a["text"] for a in _added],
                                     "by_type": _humor["by_type"], "average": _humor_tgt["average"],
                                     "minimum": _humor_tgt["minimum"], "ok": _after >= _humor_tgt["minimum"]}
                # Running-gag ledger: the counted beats, plus any added beat the polish
                # tagged as a callback to a known gag.
                try:
                    _gags = _gag_ledger_record(req_pid, project, ch_num, _humor["beats"] + [
                        {"type": "added", "quote": a["text"], "gag": a["gag"]} for a in _added if a.get("gag")])
                    _sidecar["humor"]["gags"] = _gags
                    _bits = [f"{label}: " + "; ".join(_gags[k]) for k, label in
                             (("called_back", "called back"), ("promoted", "now a running gag"), ("new", "new candidate"))
                             if _gags[k]]
                    if _bits:
                        _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: running gags — " + " · ".join(_bits))
                except Exception as e:
                    _log_error("gag_ledger", f"project={req_pid} chapter={ch_num} error={e}")
                try:
                    _fs = _slap_ledger_record(req_pid, project, ch_num, _humor.get("face_slaps") or [])
                    _sidecar["humor"]["face_slaps"] = _fs
                    _bits = [f"{label}: " + "; ".join(_fs[k]) for k, label in
                             (("new", "waiting for the slap"), ("again", "humiliated him again"), ("slapped", "slapped"))
                             if _fs[k]]
                    if _bits:
                        _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: face slaps — " + " · ".join(_bits))
                except Exception as e:
                    _log_error("slap_ledger", f"project={req_pid} chapter={ch_num} error={e}")
                if _humor_note and _added:
                    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: humor beats {_humor['count']} → {_after} — added: "
                                           + " | ".join(f"\"{a['text'][:80]}\"" for a in _added), "success")
                elif _humor_note:
                    _why = ("the polish couldn't be applied" if status == "failed" else
                            "the polish left the chapter as it was" if status == "unchanged" else
                            "no added humor beat could be found in the polished chapter")
                    _tone = "" if status == "failed" else " It may have judged the chapter's tone wrong for humor."
                    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: humor — none added: {_why}. Still "
                                           f"{_humor['count']} vs a target of about {_humor_tgt['average']}.{_tone}",
                                  "warn")
            if _combat and _combat.get("signals"):
                _combat_after = None
                if status == "changed":
                    try:
                        _combat_after = _combat_check(project, polished_text, _plan_fight)
                        if _combat_note:
                            _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: combat after the polish — "
                                                   f"{_combat_summary(_combat_after)}"
                                                   + (f" (still missing: {', '.join(_combat_after['missing'])})"
                                                      if _combat_after["missing"] else " ✓"),
                                          "success" if not _combat_after["missing"] else "warn")
                    except Exception:
                        _combat_after = None
                _sidecar["combat"] = {"before": _combat, "after": _combat_after}
    _sidecar_path = gen_dir / f"ch{ch_num:03d}_voice.json"
    try:
        if _sidecar:
            _sidecar_path.write_text(json.dumps({**_sidecar, "at": _time.time()}, ensure_ascii=False), encoding="utf-8")
        else:
            _sidecar_path.unlink(missing_ok=True)
    except Exception:
        pass

    # ── The finished chapter is written NOW, once: the previous chapter text (if any) is archived as a version, the
    #    final text replaces it, and the parts sidecar records the parts it was written in.
    if gen_path.exists():
        import shutil as _sh
        vdir = gen_dir / "_versions"
        vdir.mkdir(exist_ok=True)
        archived_v = len(list(vdir.glob(f"ch{ch_num:03d}_v*.txt"))) + 1
        _sh.move(str(gen_path), str(vdir / f"ch{ch_num:03d}_v{archived_v}.txt"))
    gen_path.write_text(full_text, encoding="utf-8")
    _index_chapter_async(req_pid, ch_num)      # the finished chapter embeds itself (nomic), in the background
    _write_chapter_parts_sidecar(req_pid, ch_num, _scene_parts(session["parts"], session.get("scene_q_budget")),
                                 list(session.get("decisions") or []),
                                 flags=[{**f, "para_start": 0, "para_count": -1} for f in _part_flags(session)])
    (gen_dir / f"ch{ch_num:03d}_audio.wav").unlink(missing_ok=True)   # stale — was synthesized from the old text

    project_file = CORPUS_PATH / "projects" / req_pid / "project.json"

    # ── ONE-SHOT-PARITY POST-PIPELINE — same finishing steps as the regular
    # Write button: influences file, auto-summary, and a full project-memory
    # entry. Dialogue shaping is no longer run automatically here — it's now
    # a separate interactive wizard the author triggers deliberately (see
    # _dialogue_shaping_apply / "dialogue_shaping" field-interactive).
    shaping = None

    # Influences file (captured at session start by _build_chapter_prompt)
    corpus_influences = session.get("corpus_influences") or []
    try:
        (gen_dir / f"ch{ch_num:03d}_influences.json").write_text(
            json.dumps(corpus_influences, indent=2, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass

    # Auto-summary so future chapters know what happened here
    summary_text = ""
    try:
        # 24000 chars (~4400 words) — was 4000 (~700 words), which silently
        # truncated the summary input to only the OPENING of any chapter over
        # ~700 words. Confirmed live: an interactive chapter that ran to 3522
        # words (compounding segment overshoots — a known behavior, see
        # _decision_instr_for) got summarized from only its first ~700 words,
        # producing a summary that described just the opening ambush and
        # falsely claimed the chapter "cuts off mid-sentence" — a summary
        # every FUTURE chapter's prompt relies on for continuity, so this was
        # silently blinding later chapters to everything past that point.
        summary_prompt = (f"Summarize this web novel chapter in 2-3 sentences. Focus on: what happened externally, "
                          f"any power-ups or reveals, and how it ended (the hook/cliffhanger). Be specific about "
                          f"character names and events. No vague language.\n\nCHAPTER {ch_num}:\n{full_text[:24000]}\n\n"
                          f"Write only the summary, no labels.")
        summary_text = _call_llm(summary_prompt, provider, model, api_key).strip()
        if summary_text.lower().startswith("summary:"):
            summary_text = summary_text[8:].strip()
        summaries_file = CORPUS_PATH / "projects" / req_pid / "chapter_summaries.json"
        all_summaries = []
        if summaries_file.exists():
            with open(summaries_file, encoding="utf-8") as f:
                all_summaries = json.load(f)
        all_summaries = [s for s in all_summaries if s.get("chapter") != ch_num]
        all_summaries.append({"chapter": ch_num, "summary": summary_text})
        all_summaries.sort(key=lambda s: s["chapter"])
        with open(summaries_file, "w", encoding="utf-8") as f:
            json.dump(all_summaries, f, indent=2, ensure_ascii=False)
    except Exception:
        summary_text = ""   # summary failure never blocks the response

    shaping_note = ""
    if shaping and shaping.get("changed"):
        shaping_note = f"\nDialogue shaping: {shaping.get('summary', '')}"
        if shaping.get("invented_characters"):
            shaping_note += f" Invented: {', '.join(shaping['invented_characters'])}."
    _log_project_memory(req_pid, f"Interactive chapter {ch_num}",
                        f"Author-steered generation (grep={session.get('grep_mode', '?')}) · {len(full_text.split())} words."
                        + "\nChoices: " + " | ".join(session["decisions"])[:400]
                        + (f"\nSummary: {summary_text}" if summary_text else "") + shaping_note + polish_note)
    _progress_log(req_pid, f"INTERACTIVE Ch.{ch_num}: complete", "success")
    with _INTERACTIVE_LOCK:
        _INTERACTIVE_SESSIONS.pop(sid, None)
    _delete_interactive_session_file(sid)
    return {
        "ok": True, "done": True, "session_id": sid,
        "segment": prose, "text": full_text,
        "word_count": len(full_text.split()),
        "decisions": session["decisions"],
        "archived_version": archived_v,
        "dialogue_shaping": shaping,
        "summary": summary_text,
        "seam_polish": polish_note.strip() or None,
    }


def _generate_chapter_impl(req: GenerateChapterRequest):
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)

    # Load previous chapter summaries
    summaries_file = CORPUS_PATH / "projects" / req.project_id / "chapter_summaries.json"
    prev_summaries = []
    if summaries_file.exists():
        with open(summaries_file, encoding="utf-8") as f:
            all_summaries = json.load(f)
        prev_summaries = [s for s in all_summaries if s.get("chapter", 0) < req.chapter_number]

    # Load previous chapter's full text so the LLM can continue seamlessly
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    prev_chapter_text = ""
    if req.chapter_number > 1:
        prev_path = gen_dir / f"ch{req.chapter_number - 1:03d}_generated.txt"
        if prev_path.exists():
            with open(prev_path, encoding="utf-8") as f:
                prev_chapter_text = f.read()

    # Get API key
    gen_cfg = _get_generation_cfg()
    provider = req.provider or gen_cfg.get("default_provider", "anthropic")
    api_key = _get_key(provider)
    models_cfg = _get_models_cfg()
    model = models_cfg.get(provider, "")
    using_cli = not api_key
    effective_provider = f"{_get_agent_engine()}-cli (subscription)" if using_cli else provider

    # Build the prompt from project data (the FAST/inject path). The recent
    # project memory is placed INSIDE the prompt (before the "Chapter N:" cue),
    # not appended after it — appending after the cue weakened continuation.
    verbatim_splice = _resolve_verbatim_splice(req.verbatim_splice)
    _progress_clear(req.project_id)
    _progress_log(req.project_id, f"Chapter {req.chapter_number}: building prompt from project data "
                                  f"({len(prev_summaries)} prior summaries, prev chapter: {'yes' if prev_chapter_text else 'no'})")
    target_words = _CHAPTER_TARGET_WORDS
    grep_mode = _resolve_grep_mode(req.grep_mode)
    _progress_log(req.project_id, f"Grep mode: {grep_mode}" + (" (project override)" if req.grep_mode else " (settings default)"))
    prompt, corpus_influences = _build_chapter_prompt(
        req.chapter_number, project, prev_summaries, prev_chapter_text,
        memory_tail=_memory_tail(req.project_id), verbatim_splice=verbatim_splice,
        target_words=target_words, project_id=req.project_id,
        semantic_top_k=12 if grep_mode == "agentic" else 5)
    if corpus_influences:
        # corpus_influences is a list of dicts ({"novel": ..., "humor_type": ..., ...}),
        # not bare strings — build a short label from each rather than joining directly.
        labels = [inf.get("novel", "?") if isinstance(inf, dict) else str(inf) for inf in corpus_influences]
        _progress_log(req.project_id, f"Corpus influences mixed in: {', '.join(labels)}")

    # Corpus-inspired "extras" for original invention, scaled by grep level.
    extras = _corpus_extras_block(project, "fast" if grep_mode == "fast" else grep_mode)
    if extras:
        _progress_log(req.project_id, f"Corpus extras block ready ({len(extras)} chars of invention inspiration)")

    # Corpus VOICE DNA — real character dialogue + prose lines, already built
    # INTO `prompt` by _build_chapter_prompt itself; only log it here (do NOT
    # rebuild/re-append it below — that duplicated the whole block in FAST/
    # TARGETED output until this fix).
    _voice_dna_logged = "CORPUS VOICE DNA" in prompt
    if _voice_dna_logged:
        _progress_log(req.project_id, "Voice DNA style reference ready (excerpts to study, not to copy)")

    # Established facts — prevents contradicting something stated in an earlier chapter.
    facts_block = _facts_block(project, req.chapter_number)
    if facts_block:
        _progress_log(req.project_id, f"Facts block ready ({facts_block.count(chr(10)) - 1} established facts for continuity)")

    # Local geography — prevents placing a scene somewhere inconsistent with
    # established adjacency/distance (e.g. a duty at a location that isn't
    # actually near where the character is supposed to be).
    geo_block = _location_map_block(project)
    if geo_block:
        _progress_log(req.project_id, f"Location map block ready ({geo_block.count(chr(10)) - 1} geography facts)")

    def _fast():
        _progress_log(req.project_id, f"FAST: 🤖 Using {_model_label(effective_provider, provider, model, using_cli)} with injected prompt…")
        p = (prompt + ("\n\n" + extras if extras else "")
             + ("\n\n" + facts_block if facts_block else "") + ("\n\n" + geo_block if geo_block else ""))
        # 600s, not _call_llm's 300s default — confirmed live: a full-chapter
        # write on Nemotron Ultra 550B (the tier this session switched back to
        # from the faster nano tier, deliberately, for quality) routinely runs
        # past 300s with a corpus-grounded prompt this size, timing out a
        # chapter that would have succeeded with more headroom.
        out = _call_llm(p, provider, model, api_key, timeout=600, abort_key=(req.project_id, "chapter")).strip()
        _progress_log(req.project_id, f"FAST: draft received ({len(out.split())} words)", "success")
        return out

    def _targeted():
        _progress_log(req.project_id, "TARGETED: grepping corpus schema (8 humor + 8 prose samples)…")
        tb = _targeted_corpus_block(project, "chapter", n_humor=8, n_prose=8)
        _progress_log(req.project_id, f"TARGETED: retrieval block built ({len(tb)} chars); 🤖 Using {_model_label(effective_provider, provider, model, using_cli)}…")
        p = prompt + "\n\n" + tb
        if extras:
            p += "\n\n" + extras
        if facts_block:
            p += "\n\n" + facts_block
        if geo_block:
            p += "\n\n" + geo_block
        out = _call_llm(p, provider, model, api_key, timeout=600, abort_key=(req.project_id, "chapter")).strip()
        _progress_log(req.project_id, f"TARGETED: draft received ({len(out.split())} words)", "success")
        return out

    def _agentic():
        # Let the CLI agent read the project + corpus files while writing the chapter.
        _progress_log(req.project_id, "AGENTIC: agent will grep/read corpus files while writing (slowest, richest)…")
        wp = _build_chapter_workspace_prompt(req.chapter_number, req.project_id, project, prev_chapter_text,
                                             verbatim_splice=verbatim_splice, target_words=target_words)
        out = _call_agent_workspace(wp, CORPUS_PATH, req.project_id, abort_key=(req.project_id, "chapter")).strip()
        _progress_log(req.project_id, f"AGENTIC: draft received ({len(out.split())} words)", "success")
        return out

    if grep_mode == "agentic" and _agent_cli_ready():
        effective_provider = f"{_get_agent_engine()}-cli (agentic-grep)"
        try:
            text = _agentic()
        except Exception as e:
            _progress_log(req.project_id, f"AGENTIC failed ({str(e)[:80]}) — falling back to FAST", "warn")
            text = _fast()   # never fail a chapter — fall back to inject
    elif grep_mode == "targeted":
        effective_provider += " · targeted"
        text = _targeted()
    else:
        text = _fast()
    _progress_log(req.project_id, f"Saving chapter {req.chapter_number}…")

    # Save generated chapter — NEVER overwrite: an existing chapter is archived
    # into _versions/ as v1, v2, … and the new text becomes the current version.
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    gen_dir.mkdir(parents=True, exist_ok=True)
    gen_path = gen_dir / f"ch{req.chapter_number:03d}_generated.txt"
    archived_v = None
    if gen_path.exists():
        import shutil as _sh
        vdir = gen_dir / "_versions"
        vdir.mkdir(exist_ok=True)
        archived_v = len(list(vdir.glob(f"ch{req.chapter_number:03d}_v*.txt"))) + 1
        _sh.move(str(gen_path), str(vdir / f"ch{req.chapter_number:03d}_v{archived_v}.txt"))
    with open(gen_path, "w", encoding="utf-8") as f:
        f.write(text)
    (gen_dir / f"ch{req.chapter_number:03d}_audio.wav").unlink(missing_ok=True)   # stale — was synthesized from the archived text

    # Dialogue Shaping is no longer run automatically here — it's now a
    # separate interactive wizard (Dialogue Shaping Interactive button, see
    # _dialogue_shaping_apply / "dialogue_shaping" field-interactive) that
    # interviews the author about which narration to convert instead of an
    # agent deciding autonomously after every draft.
    shaping = None

    # Save influences alongside the chapter
    inf_path = gen_dir / f"ch{req.chapter_number:03d}_influences.json"
    with open(inf_path, "w", encoding="utf-8") as f:
        json.dump(corpus_influences, f, indent=2, ensure_ascii=False)

    # Auto-generate a summary of this chapter and append to chapter_summaries.json
    # so future chapters know what happened here
    try:
        # 24000 chars, not 4000 — see the matching fix in _interactive_handle_segment's
        # summary_prompt for why (truncating the summary INPUT silently blinded
        # future chapters' continuity to everything past a chapter's opening).
        summary_prompt = f"""Summarize this web novel chapter in 2-3 sentences. Focus on: what happened externally, any power-ups or reveals, and how it ended (the hook/cliffhanger). Be specific about character names and events. No vague language.

CHAPTER {req.chapter_number}:
{text[:24000]}

Write only the summary, no labels."""
        summary_text = _call_llm(summary_prompt, provider, model, api_key).strip()
        # Remove any leading/trailing label like "Summary:" if the LLM added one
        if summary_text.lower().startswith("summary:"):
            summary_text = summary_text[8:].strip()

        all_summaries = []
        if summaries_file.exists():
            with open(summaries_file, encoding="utf-8") as f:
                all_summaries = json.load(f)
        # Replace if this chapter already has a summary (re-generate case)
        all_summaries = [s for s in all_summaries if s.get("chapter") != req.chapter_number]
        all_summaries.append({"chapter": req.chapter_number, "summary": summary_text})
        all_summaries.sort(key=lambda s: s["chapter"])
        with open(summaries_file, "w", encoding="utf-8") as f:
            json.dump(all_summaries, f, indent=2, ensure_ascii=False)
    except Exception:
        summary_text = ""  # summary failure never blocks the response

    # ── project memory: record what was generated and what inspired it ──
    insp = ""
    if corpus_influences:
        seen_novels = []
        for inf in corpus_influences:
            tag = f"{inf.get('novel', '?')} ({inf.get('humor_type') or inf.get('type', '')})"
            if tag not in seen_novels:
                seen_novels.append(tag)
        insp = "\nCorpus inspirations: " + "; ".join(seen_novels[:8])
    shaping_note = ""
    if shaping and shaping.get("changed"):
        shaping_note = f"\nDialogue shaping: {shaping.get('summary', '')}"
        if shaping.get("invented_characters"):
            shaping_note += f" Invented: {', '.join(shaping['invented_characters'])}."
        if shaping.get("earlier_chapters_edited"):
            shaping_note += f" Seeded into earlier chapters: {shaping['earlier_chapters_edited']}."
    _log_project_memory(
        req.project_id, f"Chapter {req.chapter_number} generated",
        f"Mode: {effective_provider} · grep={grep_mode} · {len(text.split())} words."
        + (f"\nPrevious version archived as v{archived_v}." if archived_v else "")
        + (f"\nSummary: {summary_text}" if summary_text else "") + insp + shaping_note)

    return {
        "ok": True,
        "chapter": req.chapter_number,
        "provider": effective_provider,
        "word_count": len(text.split()),
        "text": text,
        "corpus_influences": corpus_influences,
        "archived_version": archived_v,
        "dialogue_shaping": shaping,
    }


@router.get("/chapter-plan/{project_id}/{chapter_number}")
def get_chapter_plan(project_id: str, chapter_number: int):
    """Return what would be used to generate a chapter — for the Plan Viewer."""
    project_file = CORPUS_PATH / "projects" / project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)

    skeleton = project.get("chapter_skeletons", [])
    ch_plan = next((c for c in skeleton if c.get("number") == chapter_number), None)
    arcs = project.get("arcs", [])
    arc = next((a for a in arcs if chapter_number in (a.get("chapters") or [])), None)

    return {
        "project_id": project_id,
        "chapter_number": chapter_number,
        "chapter_skeleton": ch_plan,
        "arc": arc,
        "premise": project.get("creative_brief", {}).get("premise", ""),
        "themes": project.get("creative_brief", {}).get("themes", []),
        "protagonist": project.get("protagonist_name", ""),
        "characters": project.get("character_list", []),
        "world": project.get("world_bible", {}),
        "power_system": project.get("power_system", ""),
        "genre": project.get("genre", ""),
    }


class ReviseRequest(BaseModel):
    project_id: str
    provider: Optional[str] = None
    note: Optional[str] = None


@router.post("/revise")
def revise_chapters(req: ReviseRequest):
    """
    Two-pass continuity revision:
      Pass 1 — critique: read all chapters, identify contradictions, timeline breaks, system inconsistencies.
      Pass 2 — patch: rewrite each chapter minimally to fix only the flagged issues.
    Returns per-chapter issues found and whether each was patched.
    """
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)

    gen_dir = CORPUS_PATH / "generated" / req.project_id
    if not gen_dir.exists():
        raise HTTPException(404, "No generated chapters found")

    # Load all generated chapters in order
    chapter_files = sorted(gen_dir.glob("ch*_generated.txt"),
                           key=lambda f: int(f.stem.split("_")[0][2:]))
    if not chapter_files:
        raise HTTPException(404, "No generated chapters found")

    chapters = []
    for cf in chapter_files:
        num = int(cf.stem.split("_")[0][2:])
        text = cf.read_text(encoding="utf-8")
        chapters.append({"number": num, "path": cf, "text": text})

    # Get LLM config
    gen_cfg = _get_generation_cfg()
    provider = req.provider or gen_cfg.get("default_provider", "anthropic")
    api_key = _get_key(provider)
    models_cfg = _get_models_cfg()
    model = models_cfg.get(provider, "")
    using_cli = not api_key
    effective_provider = f"{_get_agent_engine()}-cli (subscription)" if using_cli else provider
    _progress_clear(req.project_id)
    _progress_log(req.project_id, f"CONTINUITY REVISION: 🤖 using {_model_label(effective_provider, provider, model, using_cli)} — critiquing {len(chapters)} chapter(s)…")

    # ── Pull ALL project engines ──────────────────────────────────────
    title       = project.get("title", "Untitled")
    genre       = project.get("genre", "Cultivation")
    genre_tags  = project.get("genre_tags", [])
    protagonist = project.get("protagonist_name", "the protagonist")
    power       = project.get("power_system", "")
    brief       = project.get("creative_brief", {})
    premise     = brief.get("premise", "")
    themes      = brief.get("themes", [])
    re_scores   = brief.get("reader_experience", {})
    story_dna   = project.get("story_dna", {})
    characters  = project.get("character_list", [])
    world       = project.get("world_bible", {})
    arcs        = project.get("arcs", [])
    story_state = project.get("story_state", {})
    skeleton    = project.get("chapter_skeletons", [])

    note = req.note or ""
    note_block = f"\nAUTHOR DIRECTION (treat this as a hard constraint):\n{note}\n" if note else ""

    # Build a shared project spec block used by both passes
    char_lines = [
        f"  {c.get('name','?')} [{c.get('role','')}] — {c.get('archetype','')}. Motivation: {c.get('motivation','')}. Secret: {c.get('secret','')}"
        for c in characters[:8]
    ]
    char_block = ("CHARACTERS:\n" + "\n".join(char_lines)) if char_lines else ""

    world_block = ""
    if world:
        tiers = " → ".join(world.get("power_tiers", []))
        factions = ", ".join(f["name"] for f in world.get("factions", [])[:6])
        locs = ", ".join(l["name"] for l in world.get("key_locations", [])[:6])
        rules = "\n".join(f"  • {r}" for r in world.get("rules", [])[:5])
        world_block = f"WORLD: {world.get('world_name','')}\nPower tiers: {tiers}\nFactions: {factions}\nKey locations: {locs}\nRules:\n{rules}"

    arc_lines = [
        f"  Arc {i+1} '{a.get('label','')}' (ch {a.get('chapters',[])[0] if a.get('chapters') else '?'}–{a.get('chapters',[])[-1] if a.get('chapters') else '?'}): {a.get('description','')}"
        for i, a in enumerate(arcs[:8])
    ]
    arc_block = ("STORY ARCS:\n" + "\n".join(arc_lines)) if arc_lines else ""

    dna_items = [f"{k}={v}/10" for k, v in story_dna.items() if isinstance(v, (int, float))]
    dna_block = f"Story DNA: {', '.join(dna_items)}" if dna_items else ""

    re_items = [f"{k}={v}/10" for k, v in re_scores.items() if isinstance(v, (int, float))]
    re_block = f"Reader Experience Target: {', '.join(re_items)}" if re_items else ""

    state_items = [f"{k}={v}" for k, v in story_state.items() if isinstance(v, (int, float)) and k not in ("target_ending_tension",)]
    state_block = f"Story State Counters: {', '.join(state_items)}" if state_items else ""

    theme_block = f"Themes: {', '.join(themes)}" if themes else ""

    # Skeleton lookup for chapter plans
    skeleton_map = {c.get("number"): c for c in skeleton}

    prose_ref = _load_raw_prose_sample()
    corpus_samples = _pick_corpus_samples(2)
    corpus_block = _format_corpus_block(corpus_samples, "general") if corpus_samples else ""

    project_spec = f"""NOVEL: "{title}" — {genre}
Protagonist: {protagonist} | Power system: {power}
Premise: {premise}
{theme_block}
{dna_block}
{re_block}
{state_block}

{char_block}

{world_block}

{arc_block}"""

    # ── PASS 1: CRITIQUE ──────────────────────────────────────────────
    chapters_block = "\n\n".join(
        f"--- CHAPTER {c['number']} ---\n{c['text'][:3000]}"
        for c in chapters
    )

    try:
        from routers.pre_generation.canon import craft_context_block as _ccb
        _plan_all = _ccb(project, None, "edit", 6000)
    except Exception:
        _plan_all = ""
    if _plan_all:
        _plan_all += ("\nAlso flag anything that contradicts the plan above: a realm that does not fit the arc, a foe or ally who is not in play yet, "
                      "a character talking against their voice, or a happening the chapter plan does not allow.\n")
    critique_prompt = f"""You are a story editor for the web novel "{title}".
{project_spec}
{_plan_all}
{note_block}
Read all chapters below and identify concrete problems across ALL of these dimensions:

TRUNCATION (highest priority — always flag):
- A chapter ends mid-word, mid-sentence, or mid-thought with no punctuation (e.g. "Pain spiked throug" or "before the system tries to kill me f")
- This is a generation artifact, never intentional. Always flag and fix.
- DO NOT confuse truncation with cliff-hangers — see cliff-hanger rules below.

CLIFF-HANGERS (never flag these):
- A chapter ends on unresolved tension, an unanswered question, a decision not yet made, or a threat about to land — these are intentional narrative devices, do not flag them.
- A chapter ending with "Footsteps. Running. Coming closer." is a cliff-hanger. Do not flag it.
- A chapter ending with "This was going to be a problem." is a cliff-hanger. Do not flag it.
- Only flag a chapter ending if it is a mid-sentence truncation OR if the next chapter's opening is factually incompatible with where this chapter left off.

CONTINUITY:
- Contradictions (power system works differently, stats change without explanation, character knowledge resets)
- Timeline breaks (time jumps with no acknowledgment)
- A character references doing something that did not happen on-screen (e.g. "he pulled up the help menu again" when /help was never shown)
- A status screen reflects a completed action that hasn't been executed yet in the narrative

CHARACTER CONSISTENCY:
- A character acts against their stated motivation or archetype
- A character knows something they shouldn't yet / forgets something they learned
- A character's relationship to the protagonist doesn't match their role/faction

WORLD & POWER SYSTEM:
- Power tier rules violated (someone does something their tier can't do)
- Faction behavior contradicts their stated agenda
- World rules broken without explanation

PACING vs. READER EXPERIENCE TARGET ({', '.join(re_items) if re_items else 'balanced'}):
- Chapter feels flat if mystery/tension target is high (add a hook or unanswered question)
- Chapter feels too grimdark if comedy target is high (needs at least one light beat)
- Chapter has no power progression if power scaling matters

THEME ALIGNMENT ({', '.join(themes) if themes else 'none set'}):
- A scene actively contradicts the stated themes without ironic intent

Do NOT flag:
- Style preferences or content you personally dislike
- Intentional cliff-hangers, unresolved tension, or open questions at chapter endings
- Narrative ambiguity that is clearly deliberate

For each problem:
{{
  "chapter": <number>,
  "dimension": "truncation|continuity|character|world|pacing|theme",
  "issue": "<one sentence: what is wrong>",
  "fix": "<one sentence: minimal change to fix it>"
}}

Output a JSON array. If nothing to flag, output [].

CHAPTERS:
{chapters_block}"""

    critique_raw = _call_llm(critique_prompt, provider, model, api_key)
    _progress_log(req.project_id, f"CONTINUITY REVISION: critique received ({len(critique_raw)} chars)")

    try:
        issues = _parse_json_from_text(critique_raw)
        if not isinstance(issues, list):
            issues = []
    except Exception:
        issues = []

    if not issues:
        return {
            "ok": True,
            "provider": effective_provider,
            "issues_found": 0,
            "chapters_patched": 0,
            "issues": [],
            "patches": [],
        }

    # ── PASS 2: PATCH each affected chapter ───────────────────────────
    issues_by_chapter: dict[int, list] = {}
    for issue in issues:
        ch = issue.get("chapter")
        if isinstance(ch, int):
            issues_by_chapter.setdefault(ch, []).append(issue)

    patches = []
    for ch_data in chapters:
        num = ch_data["number"]
        if num not in issues_by_chapter:
            continue

        ch_issues = issues_by_chapter[num]
        _progress_log(req.project_id, f"CONTINUITY REVISION: Ch.{num}: 🤖 patching {len(ch_issues)} issue(s) with {_model_label(effective_provider, provider, model, using_cli)}…")
        issues_block = "\n".join(
            f"- [{i.get('dimension','?')}] {i['issue']}\n  Fix: {i['fix']}"
            for i in ch_issues
        )

        prev = next((c for c in chapters if c["number"] == num - 1), None)
        prev_tail = ""
        if prev:
            words = prev["text"].strip().split()
            prev_tail = " ".join(words[-400:]) if len(words) > 400 else prev["text"].strip()
            prev_tail = f"\nCHAPTER {num-1} ENDING (for continuity reference):\n{prev_tail}"

        ch_plan = skeleton_map.get(num)
        plan_block = ""
        if ch_plan:
            plan_block = f"\nCHAPTER {num} INTENT: {ch_plan.get('purpose','')} | Key event: {ch_plan.get('key_event','')} | Tension: {ch_plan.get('tension',50)}/100"

        prose_block = f"\n{prose_ref}\n" if prose_ref else ""

        try:
            from routers.pre_generation.canon import craft_context_block as _ccb
            _plan_ch = _ccb(project, num, "edit", 9000)
        except Exception:
            _plan_ch = ""
        patch_prompt = f"""You are a story editor revising Chapter {num} of "{title}".
{project_spec}
{_plan_ch}
{note_block}{plan_block}{prev_tail}

{prose_block}
{corpus_block}

YOUR TASKS (in priority order):
1. FIX all listed issues — mandatory, fix every single one
   - TRUNCATION issues: complete the cut-off sentence/thought naturally, consistent with the chapter's voice. If the chapter ended mid-word, complete it and add a closing beat. Never add more than 1-2 sentences for a truncation fix.
   - CONTINUITY issues: minimal edit — change only the specific word, line, or reference that is wrong. Do not restructure scenes.
   - All other issues: targeted fix only, do not expand scope.
2. CHARACTER VOICE — if any character speaks/acts inconsistently with their archetype or motivation (see spec above), adjust that passage
3. READER EXPERIENCE — apply these nudges ONLY where you are already rewriting:
   - Mystery/tension target high → chapter should end with an unanswered question or threat
   - Comedy target high → if a scene is pure grimness, add one light beat (banter, irony, mishap)
   - Power scaling matters → protagonist should show or think about their cultivation progress at least once
4. CORPUS PROSE QUALITY — while rewriting, apply:
   - Event density: after 2-3 sentences of internal thought, something external must happen
   - Paragraph rhythm: break walls of text into short punchy paragraphs
   - Chapter hook: last paragraph must pull the reader to the next chapter — but PRESERVE intentional cliff-hangers; do not resolve them

RULES:
- Fix ALL listed issues (primary job)
- Only apply tasks 2-4 in sections you're already touching for task 1
- Do NOT rewrite sections that have no issues
- Do NOT resolve intentional cliff-hangers or open tension at chapter endings
- Keep length within ±150 words of the original
- Output ONLY the revised chapter text

ISSUES TO FIX IN CHAPTER {num}:
{issues_block}

CHAPTER {num} (ORIGINAL):
{ch_data['text']}"""

        patch_prompt += _word_budget_note(project, num, ch_data.get("text", ""), pid=req.project_id, label="continuity revision")
        revised = _call_llm(patch_prompt, provider, model, api_key).strip()

        backup_path = ch_data["path"].with_suffix(".bak.txt")
        if not backup_path.exists():
            backup_path.write_text(ch_data["text"], encoding="utf-8")
        ch_data["path"].write_text(revised, encoding="utf-8")
        _index_chapter_async(req.project_id, num)

        # Update the chapter summary since content changed
        try:
            summ_prompt = f"""Summarize this revised chapter in 2-3 sentences. What happened, any power-ups/reveals, how it ended. Specific names. No vague language.

CHAPTER {num}:
{revised[:4000]}

Write only the summary."""
            summ = _call_llm(summ_prompt, provider, model, api_key).strip()
            summaries_file = CORPUS_PATH / "projects" / req.project_id / "chapter_summaries.json"
            all_summ = json.load(open(summaries_file, encoding="utf-8")) if summaries_file.exists() else []
            all_summ = [s for s in all_summ if s.get("chapter") != num]
            all_summ.append({"chapter": num, "summary": summ})
            all_summ.sort(key=lambda s: s["chapter"])
            with open(summaries_file, "w", encoding="utf-8") as f:
                json.dump(all_summ, f, indent=2, ensure_ascii=False)
        except Exception:
            pass

        patches.append({
            "chapter": num,
            "issues_fixed": [f"[{i.get('dimension','?')}] {i['issue']}" for i in ch_issues],
            "backup": backup_path.name,
        })

    return {
        "ok": True,
        "provider": effective_provider,
        "issues_found": len(issues),
        "chapters_patched": len(patches),
        "issues": issues,
        "patches": patches,
    }


class ShortenChapterRequest(BaseModel):
    project_id: str
    chapter_number: int
    text: str            # the current draft (Edit mode's textarea) — not re-read from disk,
                          # so unsaved edits get shortened too, same as Rewrite Selection
    target_words: int
    provider: Optional[str] = None


@router.post("/shorten-chapter")
def shorten_chapter(req: ShortenChapterRequest):
    """Condense the chapter draft to approximately target_words, preserving as much of the
    actual plot/dialogue/content as possible — cutting padding and slow beats, not events.

    Stateless transform, same shape as /rewrite-selection: returns the shortened text for
    Edit mode's textarea, writes nothing to disk itself. The author reviews the result and
    clicks Save (or doesn't) exactly like any other manual edit — no separate archiving here,
    since Edit mode's own Save already doesn't archive either (confirmed: engines.py's
    save_generated is a plain overwrite) and this shouldn't behave more riskily than a normal edit."""
    if not req.text or not req.text.strip():
        raise HTTPException(400, "No chapter text to shorten.")
    orig_words = len(req.text.split())
    target = max(50, min(orig_words, req.target_words))
    if orig_words <= target:
        raise HTTPException(400, f"Chapter is already {orig_words} words — at or under the {target}-word target.")

    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)

    gen_cfg = _get_generation_cfg()
    provider = req.provider or gen_cfg.get("default_provider", "anthropic")
    api_key = _get_key(provider)
    models_cfg = _get_models_cfg()
    model = models_cfg.get(provider, "")
    using_cli = not api_key
    effective_provider = f"{_get_agent_engine()}-cli (subscription)" if using_cli else provider
    _progress_clear(req.project_id)
    _progress_log(req.project_id, f"SHORTEN Ch.{req.chapter_number}: {orig_words} → ~{target} words · "
                                  f"🤖 using {_model_label(effective_provider, provider, model, using_cli)}")

    title = project.get("title", "Untitled")
    protagonist = project.get("protagonist_name", "the protagonist")

    def _build_prompt(overshoot_note: str = "") -> str:
        # HARD CEILING framing, not a soft "approximately" ask — this codebase
        # already learned that lesson the hard way for chapter length itself
        # (see _craft_rules_for's docstring: a loose "~80-107%" framing still
        # produced a 2708-word chapter against a 1500 target). Confirmed live
        # for shortening specifically too: a first attempt at a 1200-word
        # target with a soft "stay within 90-110%" ask returned 2857 words —
        # barely trimmed at all.
        return f"""You are a surgical prose editor for the web novel "{title}". Protagonist: {protagonist}.

TASK: Cut this {orig_words}-word chapter down to {target} words. {int(target * 1.15)} words is a HARD
CEILING — not a suggestion, not "approximately." If your draft runs long, cut MORE, not just trim
phrasing.{(" " + overshoot_note) if overshoot_note else ""}

HOW TO GET THERE: this requires removing entire beats, not just tightening sentences — merge back-to-back
similar actions into one line, cut secondary reaction/description paragraphs, compress multi-line dialogue
exchanges into their essential lines. Tightening word choice alone will NOT get a chapter this size down to
{target} words.

WHAT TO KEEP: every plot event, reveal, power-up/system notification, named character, and any single line
of dialogue essential to a scene landing — but keep only the essential line, not the surrounding exchange.
This must still read as full prose throughout — not a summary, not bullet points.

CHAPTER (chapter {req.chapter_number}):
\"\"\"
{req.text}
\"\"\"

Output ONLY the shortened chapter prose, under {int(target * 1.15)} words. No title, no chapter number, no notes, no word count, no commentary."""

    try:
        from services.nemotron_agent import strip_thinking
        raw = _call_llm(_build_prompt(), provider, model, api_key, timeout=600,
                        abort_key=(req.project_id, "shorten")).strip()
        shortened = strip_thinking(raw)
        new_words = len(shortened.split())
        # One retry with an explicit, numeric callout of the overshoot — same
        # "state the actual miss" approach that closed the compounding-overshoot
        # gap in _decision_instr_for's segment lengths earlier this session.
        if shortened and new_words > int(target * 1.3):
            _progress_log(req.project_id, f"SHORTEN Ch.{req.chapter_number}: first pass only reached "
                                          f"{new_words} words (target {target}) — retrying with a harder cut…", "warn")
            note = (f"A previous attempt at this SAME task returned {new_words} words against a {target}-word "
                    f"target — nowhere close enough. This time actually remove content, don't just trim phrasing.")
            raw = _call_llm(_build_prompt(note), provider, model, api_key, timeout=600,
                            abort_key=(req.project_id, "shorten")).strip()
            shortened = strip_thinking(raw)
    except Exception as e:
        _progress_log(req.project_id, f"SHORTEN Ch.{req.chapter_number}: failed ({str(e)[:120]})", "warn")
        raise HTTPException(502, f"Shorten failed: {str(e)[:200]}")

    new_words = len(shortened.split())
    # Same reasoning-leak guard as the chapter-merge fix: a model that ran long
    # deliberating rather than actually shortening is worse than useless here —
    # never let its raw thinking get handed back as "the shortened chapter."
    if not shortened or new_words < 50 or new_words >= orig_words:
        _progress_log(req.project_id, f"SHORTEN Ch.{req.chapter_number}: result didn't actually shorten "
                                      f"({new_words} words) — discarded", "warn")
        raise HTTPException(502, "Shorten produced an unusable result (empty, too short, or not actually "
                                  "shorter) — nothing was changed. Try again.")

    _progress_log(req.project_id, f"SHORTEN Ch.{req.chapter_number}: complete — {orig_words} → {new_words} words", "success")
    return {"ok": True, "text": shortened, "word_count": new_words, "original_word_count": orig_words}


class ApplyPatchRequest(BaseModel):
    project_id: str
    old_text: str
    new_text: str
    note: Optional[str] = None   # the chat's critique/reason — recorded in project memory


@router.post("/apply-patch")
def apply_patch(req: ApplyPatchRequest):
    """Search all generated chapters for old_text and apply the replacement.
    Returns which chapter was patched, or 404 if not found in any chapter."""
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    if not gen_dir.exists():
        raise HTTPException(404, "No generated chapters found")

    def normalise(s):
        return (s.replace("\r\n", "\n")
                 .replace("‘", "'").replace("’", "'")
                 .replace("“", '"').replace("”", '"')
                 .replace("  ", " ").strip())

    norm_old = normalise(req.old_text)

    ch_files = sorted(gen_dir.glob("ch*_generated.txt"), key=lambda p: p.name)
    for cf in ch_files:
        try:
            raw = cf.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        norm_raw = normalise(raw)
        idx = norm_raw.find(norm_old)
        if idx == -1:
            # also try trimmed
            idx = norm_raw.find(norm_old.strip())
        if idx == -1:
            continue
        # Apply to the original raw text using the same normalised index mapping
        # Simple approach: find in normalised, replace in normalised, write back
        replaced = norm_raw[:idx] + req.new_text + norm_raw[idx + len(norm_old):]
        cf.write_text(replaced, encoding="utf-8")
        _index_chapter_async(req.project_id, int(re.sub(r'\D', '', cf.name.split('_')[0]) or 0))
        try:
            num = int(cf.name.replace("ch", "").replace("_generated.txt", ""))
        except Exception:
            num = 0
        _log_project_memory(
            req.project_id, f"Chapter {num} edited via chapter chat",
            (f"Critique/reason: {req.note[:400]}\n" if req.note else "")
            + f"Replaced: “{req.old_text[:180]}”\nWith: “{req.new_text[:180]}”")
        return {"ok": True, "chapter": num, "file": cf.name}

    raise HTTPException(404, "old_text not found in any generated chapter")


# ── Project memory log ───────────────────────────────────────────────────────
# A per-project, append-only markdown journal of everything the AI did:
# chapters generated (with corpus inspirations), chat edits (with critique),
# assistant turns. Every agent reads it, so context persists across turns.

def _memory_log_path(project_id: str) -> Path:
    return CORPUS_PATH / "projects" / project_id / "project_memory.md"


def _log_project_memory(project_id: str, kind: str, text: str):
    """Append one timestamped entry. Never raises — logging must not break generation."""
    try:
        import time
        p = _memory_log_path(project_id)
        p.parent.mkdir(parents=True, exist_ok=True)
        if not p.exists():
            p.write_text(
                "# Project Memory Log\n\n"
                "Auto-updated journal of AI work on this project: chapters generated, "
                "corpus inspirations used, critiques and edits applied. Newest entries last.\n",
                encoding="utf-8")
        with open(p, "a", encoding="utf-8") as f:
            f.write(f"\n## {time.strftime('%Y-%m-%d %H:%M')} · {kind}\n{text.strip()}\n")
        # keep the log bounded: header + most recent ~80 entries
        if p.stat().st_size > 250_000:
            parts = p.read_text(encoding="utf-8").split("\n## ")
            p.write_text(parts[0] + "\n## " + "\n## ".join(parts[-80:]), encoding="utf-8")
    except Exception:
        pass


def _memory_tail(project_id: str, max_chars: int = 2600) -> str:
    """Most recent memory entries, for injection into non-agentic prompts."""
    try:
        p = _memory_log_path(project_id)
        if not p.exists():
            return ""
        txt = p.read_text(encoding="utf-8")
        if len(txt) <= max_chars:
            return txt
        cut = txt[-max_chars:]
        i = cut.find("\n## ")
        return cut[i:] if i != -1 else cut
    except Exception:
        return ""


# ─────────────────────────────────────────────────────────────────────────────
# WHOLE-PROJECT AGENTIC ASSISTANT
# A chatbot that can grep the project workspace and edit anything in it
# (project.json systems/world/arcs/characters + chapter prose). Confined to the
# project's own dirs — the corpus (novels/) is never writable.
# ─────────────────────────────────────────────────────────────────────────────

def _project_backup_dir(project_id: str) -> Path:
    return CORPUS_PATH / "projects" / project_id / "_agent_backups"


def _snapshot_project(project_id: str) -> str:
    """Back up project.json + all generated chapter files into a timestamped dir.
    Returns the snapshot id. Keeps the most recent 8 snapshots."""
    import shutil, time
    proj_dir = CORPUS_PATH / "projects" / project_id
    gen_dir = CORPUS_PATH / "generated" / project_id
    snap_id = time.strftime("%Y%m%d_%H%M%S")
    snap_root = _project_backup_dir(project_id) / snap_id
    (snap_root / "projects").mkdir(parents=True, exist_ok=True)
    (snap_root / "generated").mkdir(parents=True, exist_ok=True)
    for name in ("project.json", "chapter_summaries.json"):
        src = proj_dir / name
        if src.exists():
            shutil.copy2(src, snap_root / "projects" / name)
    if gen_dir.exists():
        for f in gen_dir.glob("ch*_generated.txt"):
            shutil.copy2(f, snap_root / "generated" / f.name)
    # prune old snapshots
    backups = sorted([d for d in _project_backup_dir(project_id).iterdir() if d.is_dir()])
    for old in backups[:-8]:
        shutil.rmtree(old, ignore_errors=True)
    return snap_id


def _restore_project(project_id: str, snap_id: str):
    """Restore project.json + chapters from a snapshot, then delete that snapshot."""
    import shutil
    snap_root = _project_backup_dir(project_id) / snap_id
    if not snap_root.exists():
        raise HTTPException(404, f"Snapshot {snap_id} not found")
    proj_dir = CORPUS_PATH / "projects" / project_id
    gen_dir = CORPUS_PATH / "generated" / project_id
    for name in ("project.json", "chapter_summaries.json"):
        src = snap_root / "projects" / name
        if src.exists():
            shutil.copy2(src, proj_dir / name)
    snap_gen = snap_root / "generated"
    if snap_gen.exists():
        gen_dir.mkdir(parents=True, exist_ok=True)
        for f in snap_gen.glob("ch*_generated.txt"):
            shutil.copy2(f, gen_dir / f.name)
    shutil.rmtree(snap_root, ignore_errors=True)


class ProjectChatRequest(BaseModel):
    project_id: str
    messages: list           # [{role: "user"|"assistant", content: str}]
    provider: Optional[str] = None
    model: Optional[str] = None   # per-chat model override (assistant model selector)


@router.post("/project-chat")
def project_chat(req: ProjectChatRequest):
    """Whole-project assistant. Reads/greps the project workspace and can edit
    anything in it (project.json + chapter prose). Every turn is snapshotted so it
    can be undone. Corpus stays read-only (not in the agent's writable dirs)."""
    proj_dir = CORPUS_PATH / "projects" / req.project_id
    project_file = proj_dir / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")

    gen_dir = CORPUS_PATH / "generated" / req.project_id
    gen_dir.mkdir(parents=True, exist_ok=True)

    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    title = project.get("title", "Untitled")
    genre = project.get("genre", "Cultivation")
    pid = req.project_id

    gen_cfg = _get_generation_cfg()
    provider = req.provider or gen_cfg.get("default_provider", "anthropic")
    api_key = _get_key(provider)
    model = req.model or _get_models_cfg().get(provider, "")

    convo = "\n\n".join(
        f"{'User' if m['role'] == 'user' else 'Assistant'}: {m['content']}"
        for m in req.messages
    )

    # Fast conversational path: most chat turns ("hello", "what's Chen's
    # arc again?", small talk) need no file access at all, but were
    # previously ALWAYS sent through the full 30-turn/420s agentic tool-use
    # loop regardless — meaning a bare "hello" paid the same latency (and the
    # CLI-installed requirement, and a project snapshot) as an actual
    # multi-file edit. Try a quick plain LLM reply FIRST; the prompt tells it
    # to answer directly for conversational messages, or respond with the
    # exact sentinel NEEDS_FILE_ACCESS if the request genuinely requires
    # reading/editing project files — only then do we escalate to the slow
    # agentic path (which is where the CLI-readiness check and snapshot
    # actually belong, since only that path touches files). This keeps
    # "ability to change things if I ask it to" fully intact while making
    # every OTHER message fast.
    fast_prompt = (
        f'You are the project assistant for the web novel "{title}" ({genre}), embedded in the NovelTea Engine editor. '
        "Reply conversationally and helpfully to the user's latest message using the conversation below. "
        "If — and ONLY if — fulfilling this request requires reading or editing actual project files (renaming a "
        "character everywhere, rewriting a chapter, updating world/systems data, etc.), respond with EXACTLY the "
        "single word NEEDS_FILE_ACCESS and nothing else. For greetings, questions you can answer from context, "
        "brainstorming, or general conversation, just reply normally.\n\n"
        f"Conversation so far:\n{convo}\n\nRespond to the latest user message."
    )
    reply = None
    snap_id = None
    _progress_clear(pid)
    using_cli = not api_key
    effective_provider = f"{_get_agent_engine()}-cli (subscription)" if using_cli else provider
    _progress_log(pid, f"PROJECT ASSISTANT: 🤖 using {_model_label(effective_provider, provider, model, using_cli)}")
    try:
        fast_reply = _call_llm(fast_prompt, provider, model, api_key)
        if fast_reply.strip() != "NEEDS_FILE_ACCESS":
            reply = fast_reply
    except Exception:
        pass   # fast path failed — fall through to the full agentic path below, don't lose the request

    if reply is None:
        # Runs on the same tool-calling agent as the Workspace Assistant
        # (routers/aicoder.py's NemotronAgent) — Ollama or Nemotron only, an
        # API key/CLI for a different engine doesn't grant this feature access.
        if not _project_agent_ready():
            raise HTTPException(
                400,
                "The whole-project assistant needs a tool-capable engine (Ollama, Nemotron, Kimi K3 or Colibrì) — "
                "see Settings → CLI Accounts → Agent Engine and make sure the matching model/key pool is ready.",
            )

        # Snapshot BEFORE the agent runs so the whole turn is undoable
        snap_id = _snapshot_project(req.project_id)

        project_path = str(CORPUS_PATH / "projects" / pid)
        generated_path = str(CORPUS_PATH / "generated" / pid)
        novels_path = str(CORPUS_PATH / "novels")
        system = (
            f'You are the project assistant for the web novel "{title}" ({genre}), embedded in the NovelTea Engine editor. '
            "You have these tools: grep_files (search file CONTENTS by regex — use this first to locate things), "
            "glob_files (find files by NAME pattern), read_file, list_files, edit_file (replace an exact, unique "
            "substring — PREFER THIS for changing part of a file), write_file (replace an ENTIRE file — only for "
            "new files or full rewrites), and exec_bash_command. Always use the exact ABSOLUTE paths given below, "
            "not relative ones.\n\n"
            "YOUR PROJECT (read + write):\n"
            f"• Project brain: `{project_path}\\project.json` (premise, arcs, characters, world_bible, a "
            "`systems` object with power_levels/techniques/weapons/alchemy/arrays/artifact_forging/"
            "sacred_grounds/races/factions/wars/custom_engines — also `timeline` (the hero's realm and place per arc, and the chapter-by-chapter events), `antagonists.roster` (the Foes), `character_list` (each person's journey across the arcs, exit and voice), `lore.world`, and the hidden plan in `conspiracy` and `author_secrets` (PLANNER-ONLY: read it to check consistency and to answer the author, but never write a hidden truth into chapter prose or into any visible tab) — and `craft_notes`, the author's MANDATORY "
            "standing style rules for all prose work: dialogue attribution, ensemble scenes, italics for "
            "inner monologue).\n"
            f"• Chapter prose: `{generated_path}\\chNNN_generated.txt`.\n"
            f"• Chapter summaries: `{project_path}\\chapter_summaries.json`.\n"
            f"• PROJECT MEMORY LOG: `{project_path}\\project_memory.md` — READ THIS EARLY every turn. It records "
            "past chapter generations, corpus inspirations used, critiques and edits already applied. Honor past "
            "critiques (don't reintroduce fixed problems) and don't repeat inspirations verbatim. It is auto-updated "
            "after your turn — never edit it yourself.\n\n"
            "THE CORPUS (READ-ONLY — write_file/edit_file will be refused there, enforced by your tools, not just "
            "instructions):\n"
            f"• `{novels_path}\\<novel_id>\\` holds the extracted brains of real published web novels: "
            "prose/samples.json, humor/instances.json, reveals/log.json, reader_psychology/, entities/, "
            "narrative_genome.json.\n"
            "• Use it as reference and inspiration — study pacing, humor beats, prose rhythm, how side characters "
            "and factions are built — then create ORIGINAL content for this project. You may READ a corpus file "
            "and COPY/adapt material from it into a project file you write — never copy corpus names, plots, or "
            "text verbatim, and never attempt to write/edit a corpus file itself (it will fail).\n\n"
            "IGNORE `_agent_backups` directories and `.bak` files — automatic backups, not project data.\n\n"
            "WHEN THE USER ASKS FOR A CHANGE: make it directly by editing the relevant project file(s). "
            "Grep first to find every place affected (e.g. if renaming a character, update project.json AND every chapter). "
            "For project.json, preserve valid JSON and never drop existing data you weren't asked to remove. "
            "Keep prose edits consistent with the surrounding voice and pacing.\n\n"
            "WHEN THE USER ASKS A QUESTION: answer from the files (project and/or corpus), do not edit.\n\n"
            "Never claim you lack file access — you can read the corpus and read/edit your project. "
            "After doing the work, end your reply with a short plain-text summary of exactly which files you changed "
            "and what you did (or your answer if it was a question). Do not output JSON."
        )
        prompt = f"Conversation so far:\n{convo}\n\nRespond to the latest user message. Make any file changes needed, then summarise them."
        try:
            reply = _run_project_agent_tools(pid, prompt, system)
        except Exception as e:
            # On failure, roll back anything partially done and report
            try:
                _restore_project(req.project_id, snap_id)
            except Exception:
                pass
            raise HTTPException(500, f"Project assistant error: {str(e)[:300]}")

    # ── project memory: record the ask and what the assistant did ──
    last_user = next((m.get("content", "") for m in reversed(req.messages)
                      if m.get("role") == "user"), "")
    _log_project_memory(
        req.project_id, "Assistant turn",
        f"User asked: {last_user[:260]}\n"
        f"Assistant did: {reply[-800:] if len(reply) > 800 else reply}")

    return {
        "ok": True,
        "provider": f"{_project_agent_engine()} (project agent)" if snap_id else f"{provider} (fast chat)",
        "reply": reply,
        "snapshot_id": snap_id,   # None when the fast conversational path handled it — nothing to undo
    }


# ─────────────────────────────────────────────────────────────────────────────
# DISCOVERY — harvest everything the chapter generator invented (characters,
# techniques, items, areas, factions) back into the planning tabs/engines.
# ─────────────────────────────────────────────────────────────────────────────

_NAME_TITLES = {"elder", "deacon", "steward", "the", "venerable", "senior", "junior",
                "grand", "great", "young", "master", "disciple", "brother", "sister"}


def _name_core_words(name: str) -> frozenset:
    """Strip common honorifics/titles so 'Elder Mo Chuan' and 'Mo Chuan' reduce
    to the same core word-set for duplicate detection."""
    words = re.findall(r"[a-z]+", (name or "").lower())
    return frozenset(w for w in words if w not in _NAME_TITLES)


def _known_names(project: dict) -> set:
    """Every name already present anywhere in planning (case-insensitive)."""
    names = set()
    def add(n):
        if isinstance(n, str) and n.strip():
            names.add(n.strip().lower())
    for c in project.get("character_list") or []:
        add(c.get("name"))
    wb = project.get("world_bible") or {}
    for l in wb.get("key_locations") or []:
        add(l.get("name") if isinstance(l, dict) else l)
    for f in wb.get("factions") or []:
        add(f.get("name") if isinstance(f, dict) else f)
    for engine in (project.get("systems") or {}).values():
        if not isinstance(engine, dict):
            continue
        for v in engine.values():
            if isinstance(v, list):
                for e in v:
                    if isinstance(e, dict):
                        add(e.get("name"))
    return names


def _is_near_duplicate_name(candidate: str, known_names: set) -> bool:
    """Catch the case exact-match dedup misses: the same character referred to
    with/without an honorific across chapters (e.g. 'Elder Mo Chuan' harvested
    once, then 'Mo Chuan' harvested again from a chapter that dropped the
    title). Two names collide only if their title-stripped core word-sets are
    IDENTICAL, or one is a subset of the other with 2+ shared words — a single
    shared word (e.g. 'Hu Bao' vs 'Steward Hu') is deliberately NOT enough,
    since many distinct characters share a single surname/word in this cast."""
    cand_core = _name_core_words(candidate)
    if not cand_core:
        return False
    for known in known_names:
        known_core = _name_core_words(known)
        if not known_core:
            continue
        if cand_core == known_core:
            return True
        overlap = cand_core & known_core
        if len(overlap) >= 2 and (cand_core <= known_core or known_core <= cand_core):
            return True
    return False


class DiscoverRequest(BaseModel):
    project_id: str
    full: bool = False   # True = rescan every chapter, ignoring the scanned ledger


@router.post("/discover")
def discover(req: DiscoverRequest):
    """Scan generated chapters for named content absent from planning and merge
    it into the relevant tabs/engines. INCREMENTAL: only chapters not yet
    scanned (or modified since their last scan) are read — tracked by file
    mtime in project.discovery_scanned. Snapshotted first — undoable."""
    key = (req.project_id, "discovery")
    with _ACTIVE_GENERATIONS_LOCK:
        _ACTIVE_GENERATIONS.add(key)
    try:
        return _discover_impl(req)
    finally:
        with _ACTIVE_GENERATIONS_LOCK:
            _ACTIVE_GENERATIONS.discard(key)


def _discover_impl(req: DiscoverRequest):
    proj_dir = CORPUS_PATH / "projects" / req.project_id
    project_file = proj_dir / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    if not gen_dir.exists() or not list(gen_dir.glob("ch*_generated.txt")):
        raise HTTPException(400, "No generated chapters to scan yet.")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    if not _agent_cli_ready():
        raise HTTPException(400, "Discovery needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    title = project.get("title", "Untitled")
    _progress_clear(pid)
    _progress_log(pid, f"DISCOVERY: scanning generated chapters for content not yet in planning"
                       + (" (full rescan)" if req.full else "") + "…")

    # ── incremental scan ledger: chapter number → file mtime at last scan ──
    scanned = dict(project.get("discovery_scanned") or {})
    to_scan = []
    for f in sorted(gen_dir.glob("ch*_generated.txt")):
        try:
            num = int(f.name.replace("ch", "").replace("_generated.txt", ""))
        except Exception:
            continue
        mt = int(f.stat().st_mtime)
        rec = scanned.get(str(num))
        if req.full or rec is None or mt > int(rec):
            to_scan.append((num, f.name, mt))
    if not to_scan:
        _progress_log(pid, "DISCOVERY: all chapters already scanned — nothing new since the last run", "success")
        return {"ok": True, "total": 0, "scanned": [],
                "added": {"characters": [], "techniques": [], "items": [], "locations": [], "factions": []},
                "message": "All chapters already scanned — nothing new since the last Discovery run."}
    _progress_log(pid, f"DISCOVERY: {len(to_scan)} chapter(s) to scan — {', '.join(f'ch{n}' for n, _, _ in to_scan[:12])}"
                       + ("…" if len(to_scan) > 12 else ""))

    scan_list = "\n".join(f"• `generated/{pid}/{fname}` (chapter {num})" for num, fname, _ in to_scan)
    system = f"""You are the DISCOVERY engine for the web novel "{title}". The chapter generator is free to invent beyond the planning; your job is to harvest those inventions back INTO the planning.

Read with your tools (read-only):
• `projects/{pid}/project.json` — the CURRENT planning. Anything already named there (character_list, world_bible, any systems engine) is NOT new.
• ONLY these chapters — every other chapter was already harvested on a previous run, do NOT read them:
{scan_list}

Find every NAMED story element introduced in the chapters that is ABSENT from planning: characters (any named person with a speaking or plot role), techniques/arts/methods, items (weapons, artifacts, pills, treasures, scrolls), locations/areas, factions/organizations/sects, notable named beasts.

Output ONLY this JSON object (no fences, no commentary):
{{"new_characters": [{{"name": "", "role": "ally|rival|antagonist|mentor|love_interest|side|beast", "archetype": "", "motivation": "", "faction": "", "first_chapter": 1}}],
 "new_techniques": [{{"name": "", "type": "", "tier": "", "effect": "", "user": "", "first_chapter": 1}}],
 "new_items": [{{"name": "", "category": "weapon|artifact|pill|treasure", "description": "", "owner": "", "first_chapter": 1}}],
 "new_locations": [{{"name": "", "importance": "", "first_chapter": 1}}],
 "new_factions": [{{"name": "", "description": "", "first_chapter": 1}}]}}

Rules: descriptions 1-3 sentences grounded in what the chapters actually say. Skip anything whose name already appears anywhere in project.json. Empty arrays are fine. Do not invent — only harvest what the chapters wrote."""

    discovery_report_path = f"projects/{pid}/_discovery_report.json"
    default_found = {"new_characters": [], "new_techniques": [], "new_items": [],
                      "new_locations": [], "new_factions": []}
    _progress_log(pid, f"DISCOVERY: 🤖 agent reading {len(to_scan)} chapter(s), harvesting named content…")
    try:
        found = _run_readonly_agent_resumable(
            system, f"Scan the {len(to_scan)} listed chapter(s) and write the discovery report now.",
            discovery_report_path, default_found, max_turns=40, timeout=600, resume_attempts=2,
            abort_key=(pid, "discovery"))
    except Exception as e:
        _progress_log(pid, f"DISCOVERY failed: {str(e)[:150]}", "error")
        raise HTTPException(502, f"Discovery agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")
    for k, v in default_found.items():
        found.setdefault(k, v)
    _progress_log(pid, "DISCOVERY: harvest complete — "
                       + ", ".join(f"{len(found.get(k) or [])} {k.replace('new_','')}"
                                  for k in ("new_characters","new_techniques","new_items","new_locations","new_factions")),
                  "success")

    # ── merge, deduped against everything already in planning ──
    snap_id = _snapshot_project(pid)
    known = _known_names(project)
    added = {"characters": [], "techniques": [], "items": [], "locations": [], "factions": []}

    def fresh(name):
        k = (name or "").strip().lower()
        if not k or k in known:
            return False
        if _is_near_duplicate_name(k, known):
            return False
        known.add(k)
        return True

    for c in found.get("new_characters") or []:
        if isinstance(c, dict) and fresh(c.get("name")):
            project.setdefault("character_list", []).append({
                "name": c.get("name"), "role": c.get("role", "side"),
                "archetype": c.get("archetype", ""), "motivation": c.get("motivation", ""),
                "faction": c.get("faction", ""), "first_chapter": c.get("first_chapter"),
                "discovered": True,
            })
            added["characters"].append(c.get("name"))

    systems = project.setdefault("systems", {})
    tech_list = systems.setdefault("techniques", {}).setdefault("techniques", [])
    for t in found.get("new_techniques") or []:
        if isinstance(t, dict) and fresh(t.get("name")):
            tech_list.append({"name": t.get("name"), "type": t.get("type", ""),
                              "tier": t.get("tier", ""), "effect": t.get("effect", ""),
                              "user": t.get("user", ""), "first_chapter": t.get("first_chapter"),
                              "discovered": True})
            added["techniques"].append(t.get("name"))

    weap_list = systems.setdefault("weapons", {}).setdefault("weapons", [])
    pill_list = systems.setdefault("alchemy", {}).setdefault("pills", [])
    art_list = systems.setdefault("artifact_forging", {}).setdefault("artifacts", [])
    for it in found.get("new_items") or []:
        if isinstance(it, dict) and fresh(it.get("name")):
            entry = {"name": it.get("name"), "description": it.get("description", ""),
                     "owner": it.get("owner", ""), "first_chapter": it.get("first_chapter"),
                     "discovered": True}
            cat = (it.get("category") or "").lower()
            (weap_list if cat == "weapon" else pill_list if cat == "pill" else art_list).append(entry)
            added["items"].append(it.get("name"))

    wb = project.setdefault("world_bible", {})
    loc_list = wb.setdefault("key_locations", [])
    for l in found.get("new_locations") or []:
        if isinstance(l, dict) and fresh(l.get("name")):
            loc_list.append({"name": l.get("name"), "importance": l.get("importance", ""),
                             "first_chapter": l.get("first_chapter"), "discovered": True})
            added["locations"].append(l.get("name"))

    # Factions & Powers was absorbed into World Bible — a discovered faction
    # now only needs to land in wb_factions (systems.factions no longer
    # exists as a standalone system; writing there too would be dead data
    # nothing reads).
    wb_factions = wb.setdefault("factions", [])
    for fa in found.get("new_factions") or []:
        if isinstance(fa, dict) and fresh(fa.get("name")):
            entry = {"name": fa.get("name"), "description": fa.get("description", ""),
                     "first_chapter": fa.get("first_chapter"), "discovered": True}
            wb_factions.append(dict(entry, role="unknown"))
            added["factions"].append(fa.get("name"))

    total_added = sum(len(v) for v in added.values())
    if total_added:
        _progress_log(pid, "DISCOVERY: merged into planning — "
                           + ", ".join(f"{k}: {', '.join(v)}" for k, v in added.items() if v), "success")
    else:
        _progress_log(pid, "DISCOVERY: everything harvested already existed in planning — nothing new merged")

    # ── reconcile PLANNING vs WHAT ACTUALLY HAPPENED: skeleton entries for the
    #    scanned chapters (and any future chapter that referenced them) may now
    #    describe events that no longer match the written prose — e.g. a
    #    breakthrough's magnitude got edited after the skeleton was written.
    #    The arc description can also drift the same way. Second LLM pass,
    #    scoped only to the same chapters, run in the SAME session context. ──
    skel_by_num = {c.get("number"): c for c in project.get("chapter_skeletons", []) if c.get("number")}
    scanned_nums = [num for num, _f, _m in to_scan]
    relevant_skel = {n: skel_by_num[n] for n in scanned_nums if n in skel_by_num}
    arcs = project.get("arcs") or []

    reconciled = {"skeleton_updates": [], "arc_updates": []}
    if relevant_skel or arcs:
        skel_json = json.dumps(
            {n: {"purpose": s.get("purpose", ""), "key_event": s.get("key_event", ""),
                 "hook": s.get("hook", "")} for n, s in relevant_skel.items()},
            ensure_ascii=False)
        arc_json = json.dumps(
            [{"label": a.get("label", ""), "description": a.get("description", "")} for a in arcs],
            ensure_ascii=False)
        recon_system = f"""You are the CONTINUITY RECONCILER for the web novel "{title}". Chapters get hand-edited after their skeleton entry was written (dialogue changed, a power-up's magnitude changed, a character's line rewritten) and the skeleton/arc summaries can drift out of sync with what the prose actually says now.

Read with your tools (read-only):
• ONLY these already-written chapters: {scan_list}

Compare them against these EXISTING skeleton entries for the same chapters (JSON, keyed by chapter number):
{skel_json}

And these EXISTING arc descriptions (JSON array):
{arc_json}

For each skeleton entry, check whether its purpose/key_event/hook still accurately describes what the chapter text actually says NOW (specific facts: named amounts, cultivation stages/levels, who said what, outcomes, relationships). If a skeleton entry is now WRONG or STALE (contradicts the written prose), propose a corrected version. If it's still accurate, skip it — do not propose no-op changes.
For each arc, check if its description's summary of events still holds given the scanned chapters. If a specific claim in it is now wrong, propose a corrected description.

Output ONLY this JSON (no fences, no commentary):
{{"skeleton_updates": [{{"number": 1, "field": "purpose|key_event|hook", "corrected": "...", "reason": "one sentence"}}],
 "arc_updates": [{{"label": "...", "corrected_description": "...", "reason": "one sentence"}}]}}

Rules: only propose a change when the CURRENT text actively contradicts the chapter prose — not for style, not for things merely unmentioned. Empty arrays are fine and expected most of the time."""

        _progress_log(pid, f"DISCOVERY: 🤖 checking {len(relevant_skel)} skeleton entr{'y' if len(relevant_skel)==1 else 'ies'} "
                           f"and {len(arcs)} arc(s) for drift against the actual written prose…")
        try:
            reconciled = _run_readonly_agent_resumable(
                recon_system,
                "Compare the scanned chapters against the given skeleton/arc summaries and write the reconciliation report now.",
                f"projects/{pid}/_discovery_recon_report.json",
                {"skeleton_updates": [], "arc_updates": []}, max_turns=40, timeout=600, resume_attempts=1,
                abort_key=(pid, "discovery"))
        except Exception as e:
            _log_error("discovery reconciliation", f"project={pid} error={e}")
            _progress_log(pid, f"DISCOVERY: reconciliation pass failed ({str(e)[:100]}) — harvest results kept", "warn")
            # reconciliation is best-effort — never block the harvest on it

    skel_changed = []
    for upd in (reconciled.get("skeleton_updates") or []):
        if not isinstance(upd, dict):
            continue
        num, field = upd.get("number"), upd.get("field")
        if num in skel_by_num and field in ("purpose", "key_event", "hook") and upd.get("corrected"):
            skel_by_num[num][field] = upd["corrected"]
            skel_changed.append({"chapter": num, "field": field, "reason": upd.get("reason", "")})

    arc_changed = []
    arcs_by_label = {a.get("label"): a for a in arcs}
    for upd in (reconciled.get("arc_updates") or []):
        if not isinstance(upd, dict):
            continue
        label = upd.get("label")
        if label in arcs_by_label and upd.get("corrected_description"):
            arcs_by_label[label]["description"] = upd["corrected_description"]
            arc_changed.append({"arc": label, "reason": upd.get("reason", "")})

    # record the scan ledger regardless of findings — these chapters are done
    for num, _fname, mt in to_scan:
        scanned[str(num)] = mt
    project["discovery_scanned"] = scanned

    total = sum(len(v) for v in added.values())
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    ch_label = ", ".join(f"ch{num}" for num, _f, _m in to_scan)
    recon_summary = ""
    if skel_changed:
        recon_summary += " Skeleton corrections: " + "; ".join(
            f"ch{c['chapter']}.{c['field']} ({c['reason']})" for c in skel_changed)
    if arc_changed:
        recon_summary += " Arc corrections: " + "; ".join(
            f"{c['arc']} ({c['reason']})" for c in arc_changed)
    _log_project_memory(pid, "Discovery pass",
                        f"Scanned {ch_label}. "
                        + (f"Harvested {total} new elements into planning: "
                           + "; ".join(f"{k}: {', '.join(v)}" for k, v in added.items() if v)
                           if total else "Nothing new to harvest.")
                        + recon_summary)
    _progress_log(pid, f"DISCOVERY: complete — {total} new element(s) harvested"
                       + (f", {len(skel_changed)} skeleton fix(es)" if skel_changed else "")
                       + (f", {len(arc_changed)} arc fix(es)" if arc_changed else ""), "success")

    return {"ok": True, "added": added, "total": total, "snapshot_id": snap_id,
            "scanned": [num for num, _f, _m in to_scan],
            "skeleton_updates": skel_changed, "arc_updates": arc_changed}


# ── FACTS TAB ─────────────────────────────────────────────────────────────
# A durable, grep-able ledger of atomic statements the author has made in the
# written chapters — power levels, relationships, promises, injuries, named
# quantities, secrets, locations. Every chapter-generation and dialogue-shaping
# prompt gets a compact facts block so a contradiction 200 chapters later
# (e.g. "four-vein spirit root" vs. an earlier "three-vein") gets caught
# before it's written, not after.

_FACT_CATEGORIES = ("power_level", "relationship", "promise", "injury", "secret",
                    "possession", "location", "timeline", "physical_trait", "other")


def _facts_key(f: dict) -> str:
    """Dedup/contradiction-matching key: same subject + category = same slot."""
    return f"{(f.get('subject') or '').strip().lower()}|{(f.get('category') or '').strip().lower()}"


class FactsExtractRequest(BaseModel):
    project_id: str
    full: bool = False   # True = rescan every chapter, ignoring the facts_scanned ledger


@router.post("/facts-extract")
def facts_extract(req: FactsExtractRequest):
    """Scan generated chapters for atomic factual statements (power levels,
    relationships, promises, injuries, possessions, secrets, locations,
    timeline markers) and merge into project.facts_log. INCREMENTAL like
    Discovery: only chapters not yet scanned (or changed since) are read,
    tracked by mtime in project.facts_scanned. New facts are checked against
    existing facts for the same subject+category and flagged as possible
    CONTRADICTIONS rather than silently overwritten."""
    proj_dir = CORPUS_PATH / "projects" / req.project_id
    project_file = proj_dir / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    if not gen_dir.exists() or not list(gen_dir.glob("ch*_generated.txt")):
        raise HTTPException(400, "No generated chapters to scan yet.")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    if not _agent_cli_ready():
        raise HTTPException(400, "Facts extraction needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    title = project.get("title", "Untitled")

    scanned = dict(project.get("facts_scanned") or {})
    to_scan = []
    for f in sorted(gen_dir.glob("ch*_generated.txt")):
        try:
            num = int(f.name.replace("ch", "").replace("_generated.txt", ""))
        except Exception:
            continue
        mt = int(f.stat().st_mtime)
        rec = scanned.get(str(num))
        if req.full or rec is None or mt > int(rec):
            to_scan.append((num, f.name, mt))
    if not to_scan:
        return {"ok": True, "total": 0, "scanned": [], "added": [], "contradictions": [],
                "message": "All chapters already scanned — nothing new since the last Facts extraction."}

    scan_list = "\n".join(f"• `generated/{pid}/{fname}` (chapter {num})" for num, fname, _ in to_scan)
    report_path = f"projects/{pid}/_facts_report.json"
    system = f"""You are the FACTS engine for the web novel "{title}". You extract ATOMIC factual statements the author has committed to in the written prose, so a fact stated in chapter 3 can be checked against one in chapter 150.

Read with your tools (read-only):
• ONLY these chapters — every other chapter was already extracted on a previous run, do NOT read them:
{scan_list}

For EVERY concrete, checkable statement of fact, extract one entry. Categories: {", ".join(_FACT_CATEGORIES)}.
Examples of what counts: "Zhou Tien's spirit root has four veins" (physical_trait), "Zhou Tien is Qi Condensation Early Stage" (power_level), "Hu Bao owes Steward Hu 2 spirit stones" (possession/promise), "Elder Bai lost an eye in the Sea of Fallen Scriptures" (injury), "Su Wanqing is Elder Qin's grandniece" (relationship), "the Old Scripture Pavilion is condemned, scheduled for demolition" (location), "Zhou Tien has sworn never to reveal the Bamboo" (secret/promise).
Skip vague scene-setting, mood, or anything not a checkable claim.

Rules: `subject` is the character/place/item the fact is ABOUT (for matching against later facts on the same subject). `statement` is a single self-contained sentence, specific (names, numbers, exact claims) — not a summary of the scene. One statement per fact; split compound facts into separate entries.
JSON shape: {{"facts": [{{"chapter": 1, "category": "power_level", "subject": "Zhou Tien", "statement": "Qi Condensation, Early Stage — stalled three years", "characters": ["Zhou Tien"]}}]}}"""

    try:
        found = _run_readonly_agent_resumable(
            system, f"Extract facts from the {len(to_scan)} listed chapter(s) and write the report file now.",
            report_path, {"facts": []}, max_turns=40, timeout=600, resume_attempts=2)
    except Exception as e:
        raise HTTPException(502, f"Facts extraction agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")

    facts_log = project.get("facts_log") or []
    by_key = {}
    for i, f in enumerate(facts_log):
        by_key.setdefault(_facts_key(f), []).append(i)

    persisted_contras = project.get("facts_contradictions") or []
    next_contra_id = max((c.get("id", 0) for c in persisted_contras), default=0) + 1

    added, contradictions = [], []
    next_id = max((f.get("id", 0) for f in facts_log), default=0) + 1
    for nf in (found.get("facts") or []):
        if not isinstance(nf, dict) or not nf.get("statement") or not nf.get("subject"):
            continue
        entry = {
            "id": next_id, "chapter": nf.get("chapter"), "category": nf.get("category", "other"),
            "subject": nf.get("subject", "").strip(), "statement": nf.get("statement", "").strip(),
            "characters": nf.get("characters") or [],
        }
        next_id += 1
        key = _facts_key(entry)
        existing_idxs = by_key.get(key, [])
        # contradiction heuristic: same subject+category already has a DIFFERENT
        # statement on record — flag for human review rather than silently trusting
        # either version (the agent doing the flagging isn't the source of truth).
        if existing_idxs:
            prior = facts_log[existing_idxs[-1]]
            if prior.get("statement", "").strip().lower() != entry["statement"].lower():
                contra = {
                    "id": next_contra_id, "status": "open",
                    "subject": entry["subject"], "category": entry["category"],
                    "new": {"chapter": entry["chapter"], "statement": entry["statement"], "fact_id": entry["id"]},
                    "existing": {"chapter": prior.get("chapter"), "statement": prior.get("statement"), "fact_id": prior.get("id")},
                }
                next_contra_id += 1
                contradictions.append(contra)
                persisted_contras.append(contra)
        facts_log.append(entry)
        by_key.setdefault(key, []).append(len(facts_log) - 1)
        added.append(entry)

    project["facts_log"] = facts_log
    project["facts_contradictions"] = persisted_contras
    for num, _fname, mt in to_scan:
        scanned[str(num)] = mt
    project["facts_scanned"] = scanned

    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    ch_label = ", ".join(f"ch{num}" for num, _f, _m in to_scan)
    contra_note = ""
    if contradictions:
        contra_note = " ⚠ POSSIBLE CONTRADICTIONS: " + "; ".join(
            f"{c['subject']}/{c['category']}: ch{c['existing']['chapter']} said \"{c['existing']['statement'][:80]}\" "
            f"vs. ch{c['new']['chapter']} \"{c['new']['statement'][:80]}\"" for c in contradictions)
    _log_project_memory(pid, "Facts extraction",
                        f"Scanned {ch_label}. Extracted {len(added)} facts." + contra_note)

    return {"ok": True, "total": len(added), "added": added, "contradictions": contradictions,
            "scanned": [num for num, _f, _m in to_scan]}


class FactsFixRequest(BaseModel):
    project_id: str
    contradiction_id: int


@router.post("/facts-fix")
def facts_fix(req: FactsFixRequest):
    """Resolve one flagged Facts contradiction: an agent reads both chapters
    involved, decides which claim is actually correct (or how to reconcile
    both), edits the WRONG chapter's prose to match the truth, and updates the
    facts ledger. Pre-fix text is archived as a version, same as Dialogue
    Shaping, so the fix is always reversible."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    contras = project.get("facts_contradictions") or []
    contra = next((c for c in contras if c.get("id") == req.contradiction_id), None)
    if not contra:
        raise HTTPException(404, f"Contradiction {req.contradiction_id} not found")
    if not _agent_cli_ready():
        raise HTTPException(400, "Fixing contradictions needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    ch_a, ch_b = contra["existing"]["chapter"], contra["new"]["chapter"]
    gen_dir = CORPUS_PATH / "generated" / pid
    # word counts BEFORE the fix, so a growth warning can be logged after —
    # the length-budget instruction above asks the agent to hold flat/shrink,
    # but this catches it if that instruction isn't honored.
    _before_words = {}
    for n in (ch_a, ch_b):
        fp = gen_dir / f"ch{n:03d}_generated.txt"
        if fp.exists():
            _before_words[n] = len(fp.read_text(encoding="utf-8").split())
    report_path = f"projects/{pid}/_facts_fix_report.json"
    system = (
        "You are a continuity editor for a long-form web novel. You resolve a factual contradiction between two "
        "chapters by editing the chapter that is WRONG so it matches established canon. You work with Read/Edit "
        "tools inside the workspace. Never ask questions; never output explanations; never print the report JSON "
        "to stdout — write it to the file named."
    )
    prompt = f"""Resolve this factual contradiction in project {pid}:

Subject: {contra['subject']} ({contra['category']})
• Chapter {ch_a} states: "{contra['existing']['statement']}"
• Chapter {ch_b} states: "{contra['new']['statement']}"

STEP 1 — Read `generated/{pid}/ch{ch_a:03d}_generated.txt` and `generated/{pid}/ch{ch_b:03d}_generated.txt` (whichever chapter numbers are given above — pad to 3 digits). Read enough surrounding context in each to understand which claim is actually correct given the story's established facts and chronology (usually the EARLIER chapter is canon and the later one drifted, but check — sometimes the later chapter is a deliberate reveal/correction/plot development, in which case the earlier claim may need a small retroactive-consistency edit instead).
STEP 2 — Edit the chapter that is factually WRONG so its prose matches the correct fact. Make the SMALLEST edit that fixes the contradiction — change only the specific claim, not surrounding prose, dialogue voice, or pacing. Do not touch the chapter that's already correct.
LENGTH BUDGET — this chapter has already been fixed against other contradictions in this same run; each fix must be net-neutral or NET-SHORTER in word count, never a pure addition. Prefer REPLACING/REWORDING the wrong claim's existing sentence(s) over inserting a new clarifying clause — a contradiction is a wrong fact, not a missing explanation, so fixing it should rarely need more words than the wrong version already had. Multiple small insertions across a chapter compound into real, unwanted growth — if your edit doesn't reduce or hold the word count roughly flat, rewrite it tighter before writing the report.
STEP 3 — Write your report to `{report_path}` (Write tool, overwrite if it exists) as ONLY this JSON:
{{"resolved": true, "fixed_chapter": {ch_a} or {ch_b}, "correct_statement": "the fact as it now stands", "summary": "1 sentence on what was changed"}}
If you determine BOTH chapters need a small edit to reconcile (e.g. a reveal that recontextualizes the earlier claim rather than contradicts it), edit both and report fixed_chapter as a list: "fixed_chapter": [ch_a, ch_b]."""

    full_report_path = CORPUS_PATH / report_path
    try:
        prompt += "".join(_word_budget_note(project, _n, words=_w, pid=pid, label="facts fix") for _n, _w in _before_words.items())
        _call_project_agent(prompt, system, pid, max_turns=25, timeout=420, resumable=True, resume_attempts=2,
                            success_file=full_report_path)
    except Exception as e:
        _log_error("facts_fix", f"project={pid} contradiction={req.contradiction_id} error={e}")
        raise HTTPException(502, f"Fix agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")

    result = _read_agent_report(full_report_path, {"resolved": False, "fixed_chapter": None, "summary": ""})
    full_report_path.unlink(missing_ok=True)

    contra["status"] = "resolved" if result.get("resolved") else "fix_attempted"
    contra["resolution"] = result.get("summary", "")
    project["facts_contradictions"] = contras

    # correct the stale fact in facts_log so the block injected into future
    # generation reflects the resolved truth, not the contradiction
    if result.get("correct_statement"):
        facts_log = project.get("facts_log") or []
        for fid in (contra["existing"].get("fact_id"), contra["new"].get("fact_id")):
            for f in facts_log:
                if f.get("id") == fid:
                    f["statement"] = result["correct_statement"]
        project["facts_log"] = facts_log

    # the fixed chapter(s) changed — reset Discovery/facts/map ledgers for them
    # so the next scan pass re-harvests the corrected text
    fixed = result.get("fixed_chapter")
    fixed_nums = fixed if isinstance(fixed, list) else [fixed] if fixed else []
    for _n in fixed_nums:
        if isinstance(_n, int): _index_chapter_async(pid, _n)
    for ledger_key in ("discovery_scanned", "facts_scanned", "location_map_scanned"):
        ledger = dict(project.get(ledger_key) or {})
        for n in fixed_nums:
            ledger.pop(str(n), None)
        project[ledger_key] = ledger

    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    # Growth check — flag it in the memory log if the fix grew a chapter
    # meaningfully (>2%) instead of holding flat/shrinking as instructed, so
    # drift from repeated fixes is visible instead of silently accumulating.
    growth_note = ""
    growth_flags = []
    for n in fixed_nums:
        before = _before_words.get(n)
        fp = gen_dir / f"ch{n:03d}_generated.txt"
        if before and fp.exists():
            after = len(fp.read_text(encoding="utf-8").split())
            delta = after - before
            if delta > max(10, before * 0.02):
                growth_flags.append(f"ch{n}: {before}→{after} words (+{delta})")
    if growth_flags:
        growth_note = " ⚠ GREW: " + "; ".join(growth_flags)

    _log_project_memory(pid, "Facts contradiction fixed",
                        f"{contra['subject']}/{contra['category']}: {result.get('summary', '')}"
                        + (f" (edited ch{fixed_nums})" if fixed_nums else "") + growth_note)

    return {"ok": True, "resolved": result.get("resolved", False), "fixed_chapter": fixed,
            "summary": result.get("summary", ""), "contradiction_id": req.contradiction_id,
            "growth_warning": growth_flags or None}


