def _facts_block(project: dict, chapter_number: Optional[int] = None, max_facts: int = 60) -> str:
    """Compact facts reference injected into generation/shaping prompts so a
    new chapter (or a reshape) doesn't contradict something already stated.
    Prioritizes facts about characters/subjects most likely relevant: recent
    chapters first, capped so it doesn't bloat the prompt at chapter 200+."""
    facts = project.get("facts_log") or []
    if not facts:
        return ""
    ordered = sorted(facts, key=lambda f: f.get("chapter") or 0, reverse=True)[:max_facts]
    ordered.sort(key=lambda f: f.get("chapter") or 0)
    lines = ["━━ ESTABLISHED FACTS (do not contradict — these were stated in earlier chapters) ━━"]
    for f in ordered:
        lines.append(f"  • [ch{f.get('chapter', '?')}] {f.get('subject', '?')} — {f.get('statement', '')}")
    return "\n".join(lines)


# ── CONTINUITY REVIEW ─────────────────────────────────────────────────────
# A proactive sweep, distinct from Facts/Map extraction: those two only ever
# compare NEWLY scanned chapters against the ledger as they're harvested, so a
# contradiction between two ALREADY-scanned chapters (or between the ledger
# and the actual prose, if a chapter got hand-edited without triggering a
# re-scan) can sit undetected. Review re-reads the full written corpus against
# the full existing facts_log + location_map and hunts for anything that
# doesn't add up — flagged into the same contradiction queues, same Fix
# buttons, same everything.

class ContinuityReviewRequest(BaseModel):
    project_id: str


# Same seed vocabulary as corpus/extract_symbols_regex.py (V4 Phase 3,
# doc Layer 10) — kept in sync manually since one lives in the corpus
# pipeline and the other here in the app's own continuity check.
_SYMBOL_SEEDS = ["fire", "water", "moon", "sword", "tree", "bird",
                 "blood", "silence", "voice", "darkness", "light"]
_SYMBOL_PATTERNS = {sym: re.compile(rf"\b{re.escape(sym)}\w*\b", re.IGNORECASE) for sym in _SYMBOL_SEEDS}


def _project_symbol_check(gen_dir: Path) -> list:
    """Pure-python, no-LLM symbol-recurrence check (V4 Phase 3) — scans this
    project's own generated chapters for the same seed-symbol vocabulary the
    corpus symbol pipeline uses, and flags any symbol that appears in exactly
    one chapter and is never returned to since (a planted motif that never
    paid off). Detection needs no LLM call, same philosophy as Promise Drift."""
    chapters = sorted(gen_dir.glob("ch*_generated.txt"), key=lambda f: int(f.stem.split("_")[0][2:]))
    if len(chapters) < 5:
        return []  # too early in the book to judge recurrence meaningfully
    hits: dict = {sym: [] for sym in _SYMBOL_SEEDS}
    for cf in chapters:
        num = int(cf.stem.split("_")[0][2:])
        try:
            text = cf.read_text(encoding="utf-8")
        except Exception:
            continue
        for sym, pat in _SYMBOL_PATTERNS.items():
            if pat.search(text):
                hits[sym].append(num)
    latest = max(int(cf.stem.split("_")[0][2:]) for cf in chapters)
    flags = []
    for sym, chs in hits.items():
        # single mention, AND at least 3 chapters have passed since — gives a
        # freshly-planted symbol room to recur before it's flagged as orphaned
        if len(chs) == 1 and chs[0] <= latest - 3:
            flags.append({"symbol": sym, "chapter": chs[0]})
    return flags


@router.post("/continuity-review")
def continuity_review(req: ContinuityReviewRequest):
    """Actively hunt for contradictions across the WHOLE written story so far —
    not just newly-scanned chapters. Cross-checks facts_log and location_map
    against each other and against the actual chapter prose. Findings are
    appended to the same facts_contradictions / location_map_contradictions
    queues the extraction passes use, so the existing per-item Fix buttons
    apply to whatever this finds too."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    chapters = sorted(gen_dir.glob("ch*_generated.txt")) if gen_dir.exists() else []
    if not chapters:
        raise HTTPException(400, "No generated chapters to review yet.")
    if not _agent_cli_ready():
        raise HTTPException(400, "Continuity Review needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    title = project.get("title", "Untitled")
    facts_log = project.get("facts_log") or []
    location_map = project.get("location_map") or []
    if not facts_log and not location_map:
        raise HTTPException(400, "Nothing to review yet — run Extract Facts and/or Update Map first so there's a ledger to check the chapters against.")
    ch_range = f"1-{len(chapters)}"
    report_path = f"projects/{pid}/_continuity_review_report.json"

    # WinError 206 (Windows argv length cap, ~32KB) hit here previously because
    # the full facts_log/location_map JSON was embedded directly in
    # --system-prompt on the command line. Write it to a file for the agent to
    # Read instead — same fix pattern as every other report-based call, and it
    # also means the review is now explicitly TARGETED at what's actually in
    # the Facts/Map tabs (the ledger drives which chapters matter) rather than
    # an unbounded re-read of the whole story from scratch.
    ledger_path = f"projects/{pid}/_continuity_review_ledger.json"
    ledger_data = {
        "facts": [{"id": f.get("id"), "chapter": f.get("chapter"), "category": f.get("category"),
                   "subject": f.get("subject"), "statement": f.get("statement")} for f in facts_log],
        "locations": [{"name": n.get("name"), "chapter": n.get("chapter"), "description": n.get("description"),
                       "connections": n.get("connections", [])} for n in location_map],
    }
    with open(CORPUS_PATH / ledger_path, "w", encoding="utf-8") as f:
        json.dump(ledger_data, f, ensure_ascii=False)

    system = f"""You are the CONTINUITY REVIEWER for the web novel "{title}". You actively HUNT for contradictions — this is a proactive audit, not passive extraction, and it is TARGETED: driven by what's already recorded in the facts/map ledger, not a blind re-read of every chapter.

STEP 1 — Read `{ledger_path}` (JSON: {{"facts": [...], "locations": [...]}}). This is the current Facts tab + Map tab content.

STEP 2 — For each fact and each location/connection in the ledger, read ONLY the specific chapters relevant to it: the chapter it was recorded from, PLUS any other chapter that mentions the same subject/location by name (use Grep on `generated/{pid}/ch*.txt` to find them quickly — do not read all {len(chapters)} chapters in full). Check whether:
  (a) two ledger entries about the same subject/location conflict with each other, or
  (b) a chapter's actual prose no longer matches what the ledger claims (e.g. hand-edited since it was recorded).

Only report a GENUINE contradiction — two claims that cannot both be true — not a mere gap, omission, or stylistic inconsistency.

Write your report to `{report_path}` (Write tool, overwrite if it exists) as ONLY this JSON:
{{"fact_contradictions": [{{"subject": "Zhou Tien", "category": "power_level", "chapter_a": 5, "statement_a": "...", "chapter_b": 12, "statement_b": "..."}}],
 "location_contradictions": [{{"from": "The Old Scripture Pavilion", "to": "Sword Hall practice ground", "chapter_a": 5, "relation_a": "...", "chapter_b": 40, "relation_b": "..."}}]}}
Rules: chapter_a should be the earlier chapter. Be conservative — a false-positive contradiction wastes the author's time reviewing something that wasn't actually wrong. Empty arrays are the expected common case for a well-maintained story."""

    try:
        found = _run_readonly_agent_resumable(
            system, "Review the ledger against the chapters for contradictions and write the report now.",
            report_path, {"fact_contradictions": [], "location_contradictions": []},
            max_turns=50, timeout=720, resume_attempts=2)
    except Exception as e:
        raise HTTPException(502, f"Continuity Review agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")
    finally:
        (CORPUS_PATH / ledger_path).unlink(missing_ok=True)

    fact_contras = project.get("facts_contradictions") or []
    next_fc_id = max((c.get("id", 0) for c in fact_contras), default=0) + 1
    new_fact_contras = []
    for fc in (found.get("fact_contradictions") or []):
        if not isinstance(fc, dict) or not fc.get("statement_a") or not fc.get("statement_b"):
            continue
        entry = {
            "id": next_fc_id, "status": "open", "subject": fc.get("subject", ""), "category": fc.get("category", "other"),
            "existing": {"chapter": fc.get("chapter_a"), "statement": fc.get("statement_a"), "fact_id": None},
            "new": {"chapter": fc.get("chapter_b"), "statement": fc.get("statement_b"), "fact_id": None},
        }
        next_fc_id += 1
        fact_contras.append(entry)
        new_fact_contras.append(entry)
    project["facts_contradictions"] = fact_contras

    loc_contras = project.get("location_map_contradictions") or []
    next_lc_id = max((c.get("id", 0) for c in loc_contras), default=0) + 1
    new_loc_contras = []
    for lc in (found.get("location_contradictions") or []):
        if not isinstance(lc, dict) or not lc.get("relation_a") or not lc.get("relation_b"):
            continue
        entry = {
            "id": next_lc_id, "status": "open", "from": lc.get("from", ""), "to": lc.get("to", ""),
            "existing": {"chapter": lc.get("chapter_a"), "relation": lc.get("relation_a")},
            "new": {"chapter": lc.get("chapter_b"), "relation": lc.get("relation_b")},
        }
        next_lc_id += 1
        loc_contras.append(entry)
        new_loc_contras.append(entry)
    project["location_map_contradictions"] = loc_contras

    # Symbol-recurrence check (V4 Phase 3) — pure-python, no extra LLM cost,
    # runs alongside the agentic fact/location audit above, not instead of it.
    symbol_flags = _project_symbol_check(gen_dir)
    project["symbol_flags"] = symbol_flags

    project["last_continuity_review"] = {"chapters_reviewed": len(chapters), "at": __import__("time").strftime("%Y-%m-%d %H:%M:%S")}
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    total = len(new_fact_contras) + len(new_loc_contras)
    _log_project_memory(pid, "Continuity Review",
                        f"Reviewed all {len(chapters)} chapters. Found {total} new contradiction(s)"
                        f"{f' and {len(symbol_flags)} orphaned symbol(s)' if symbol_flags else ''}."
                        if (total or symbol_flags) else f"Reviewed all {len(chapters)} chapters. No contradictions found.")

    return {"ok": True, "total": total, "chapters_reviewed": len(chapters),
            "fact_contradictions": new_fact_contras, "location_contradictions": new_loc_contras,
            "symbol_flags": symbol_flags}


# ── REVISION INTELLIGENCE (V4 Phase 5, doc Layer 25) ────────────────────────
# A structured craft pass, alongside Continuity Review's factual-contradiction
# hunt — this one checks the doc's named categories (pacing, flat dialogue,
# weak stakes, exposition dumps, repetition) rather than "is this true," and
# surfaces them as a persistent, per-item checklist (same open/dismissed/fixed
# lifecycle as facts_contradictions) instead of a one-off report that vanishes
# after reading.

class RevisionCheckRequest(BaseModel):
    project_id: str
    chapter_range: Optional[str] = None   # e.g. "10-15" — None = most recent 10 chapters


_REVISION_CATEGORIES = ["pacing_issues", "flat_dialogue", "weak_stakes", "exposition_dumps", "repetition"]


@router.post("/revision-check")
def revision_check(req: RevisionCheckRequest):
    """Craft-quality pass: pacing, flat dialogue, weak stakes, exposition dumps,
    repetition — the doc's named Revision Intelligence categories (Layer 25).
    Same agentic-scan-then-persist-a-queue shape as Continuity Review, just
    checking craft instead of factual contradictions."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    all_chapters = sorted(gen_dir.glob("ch*_generated.txt")) if gen_dir.exists() else []
    if not all_chapters:
        raise HTTPException(400, "No generated chapters to review yet.")
    if not _agent_cli_ready():
        raise HTTPException(400, "Revision Check needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    title = project.get("title", "Untitled")

    # Default scope: most recent 10 chapters — a full-story scan on every click
    # doesn't scale, and craft issues are most actionable caught close to when
    # they were written, not buried under a 200-chapter backlog.
    if req.chapter_range:
        try:
            lo_s, hi_s = req.chapter_range.split("-")
            lo, hi = int(lo_s), int(hi_s)
        except Exception:
            raise HTTPException(400, "chapter_range must look like '10-15'.")
        scoped = [p for p in all_chapters if lo <= int(re.search(r"ch(\d+)_", p.name).group(1)) <= hi]
    else:
        scoped = all_chapters[-10:]
    if not scoped:
        raise HTTPException(400, "No chapters in that range.")
    lo_ch = int(re.search(r"ch(\d+)_", scoped[0].name).group(1))
    hi_ch = int(re.search(r"ch(\d+)_", scoped[-1].name).group(1))

    report_path = f"projects/{pid}/_revision_check_report.json"
    system = f"""You are a developmental editor doing a REVISION INTELLIGENCE pass on chapters {lo_ch}-{hi_ch} of "{title}" — craft quality, not factual contradictions (that's a separate check).

STEP 1 — Read `generated/{pid}/ch{{NNN}}_generated.txt` for each chapter {lo_ch} through {hi_ch} (zero-padded to 3 digits).

STEP 2 — For each chapter, check for genuine instances (not hypothetical risk) of:
  - pacing_issues: a scene that drags well past the point it's made its point, or a rushed beat that needed more room
  - flat_dialogue: exchanges where multiple characters sound interchangeable, or dialogue that's purely functional (no voice, no subtext)
  - weak_stakes: a conflict/decision presented as tense that has no real cost or consequence attached
  - exposition_dumps: worldbuilding/backstory delivered as a lecture (narration or dialogue) instead of dramatized
  - repetition: a phrase, sentence structure, beat, or description reused enough times across these chapters to be noticeable to a reader

Only flag genuine instances a careful reader would notice — this is a working author's checklist, not a quota. Empty categories are a good outcome, not a failure to find something.

Write your report to `{report_path}` (Write tool, overwrite if it exists) as ONLY this JSON:
{{"pacing_issues": [{{"chapter": 12, "description": "...", "suggestion": "..."}}],
 "flat_dialogue": [...], "weak_stakes": [...], "exposition_dumps": [...], "repetition": [...]}}
Each category is a list in the same shape (chapter/description/suggestion); empty arrays where nothing was found."""

    try:
        found = _run_readonly_agent_resumable(
            system, f"Review chapters {lo_ch}-{hi_ch} for the five Revision Intelligence categories and write the report now.",
            report_path, {c: [] for c in _REVISION_CATEGORIES},
            max_turns=50, timeout=720, resume_attempts=2)
    except Exception as e:
        raise HTTPException(502, f"Revision Check agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")

    checklist = project.get("revision_checklist") or []
    next_id = max((c.get("id", 0) for c in checklist), default=0) + 1
    new_items = []
    for cat in _REVISION_CATEGORIES:
        for item in (found.get(cat) or []):
            if not isinstance(item, dict) or not item.get("description"):
                continue
            entry = {"id": next_id, "status": "open", "category": cat,
                     "chapter": item.get("chapter"), "description": item.get("description", ""),
                     "suggestion": item.get("suggestion", "")}
            next_id += 1
            checklist.append(entry)
            new_items.append(entry)
    project["revision_checklist"] = checklist
    project["last_revision_check"] = {"chapter_range": f"{lo_ch}-{hi_ch}", "at": __import__("time").strftime("%Y-%m-%d %H:%M:%S")}
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    _log_project_memory(pid, "Revision Check",
                        f"Reviewed chapters {lo_ch}-{hi_ch}. Found {len(new_items)} new item(s)."
                        if new_items else f"Reviewed chapters {lo_ch}-{hi_ch}. Nothing flagged.")

    return {"ok": True, "chapter_range": f"{lo_ch}-{hi_ch}", "total_new": len(new_items), "items": new_items}


class RevisionChecklistUpdateRequest(BaseModel):
    project_id: str
    item_id: int
    status: str   # "open" | "dismissed" | "fixed"


@router.post("/revision-checklist-update")
def revision_checklist_update(req: RevisionChecklistUpdateRequest):
    """Mark one checklist item dismissed/fixed/reopened — same lifecycle as
    facts_contradictions' per-item status, no new pattern."""
    if req.status not in ("open", "dismissed", "fixed"):
        raise HTTPException(400, "status must be open, dismissed, or fixed.")
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    checklist = project.get("revision_checklist") or []
    item = next((c for c in checklist if c.get("id") == req.item_id), None)
    if not item:
        raise HTTPException(404, f"Checklist item {req.item_id} not found.")
    item["status"] = req.status
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)
    return {"ok": True, "item": item}


# ── PROMISE CHECK (V4 Phase 5) ───────────────────────────────────────────────
# The Promise Check WIZARD, sitting on top of Phase 2's drift detection —
# corpus/promise_drift.py already does this for the CORPUS (baseline
# chapter's payoff_categories/reader_emotions/genre_signals vs. a recent-
# window average, pure aggregation, no LLM call). This ports the SAME
# algorithm to the author's own project, sourced from chapter_skeletons'
# target_psychology/intent (already generated for free as part of planning —
# no new extraction pass), then walks flagged drift as A/B choices instead of
# a passive warning. Detection AND the wizard's choices are both zero-LLM-cost
# by design, matching promise_drift.py's own stated principle.

_PROMISE_WINDOW = 5
_PROMISE_DROP_THRESHOLD = 4
_PROMISE_EMERGE_THRESHOLD = 5


def _avg_dict(dicts: list) -> dict:
    sums, counts = {}, {}
    for d in dicts:
        for k, v in (d or {}).items():
            if isinstance(v, (int, float)):
                sums[k] = sums.get(k, 0) + v
                counts[k] = counts.get(k, 0) + 1
    return {k: round(sums[k] / counts[k], 1) for k in sums}


def _compute_project_promise_drift(project: dict) -> dict:
    """Chapter-skeleton equivalent of corpus/promise_drift.py's compute_drift().
    reader_emotions/tension_curve map directly (skeleton's own target_psychology);
    genre_signals maps to each chapter's ARC's genre_contracts (projects don't tag
    genre signals per-chapter, but arcs already carry a genre_contracts list)."""
    skeletons = sorted((c for c in (project.get("chapter_skeletons") or [])
                        if isinstance(c.get("number"), int) and c.get("target_psychology")),
                       key=lambda c: c["number"])
    if len(skeletons) < _PROMISE_WINDOW + 2:
        return {"status": "insufficient_data", "chapters_available": len(skeletons)}

    arcs = project.get("arcs") or []
    def _genre_signals_for(ch_num: int) -> set:
        arc = next((a for a in arcs if ch_num in (a.get("chapters") or [])), None)
        if not arc:
            return set()
        # genre_contracts entries are "label: explanation" — keep just the label,
        # matching genre_signals' short-tag shape on the corpus side.
        return {str(g).split(":")[0].strip() for g in (arc.get("genre_contracts") or []) if g}

    baseline_ch = skeletons[0]
    recent_window = skeletons[-_PROMISE_WINDOW:]
    confirmed = set(project.get("promise_drift_confirmed") or [])

    baseline_genres = _genre_signals_for(baseline_ch["number"])
    recent_genres = set()
    for c in recent_window:
        recent_genres |= _genre_signals_for(c["number"])
    genre_overlap = baseline_genres & recent_genres

    baseline_emotions = (baseline_ch.get("target_psychology") or {}).get("reader_emotions") or {}
    recent_avg_emotions = _avg_dict([(c.get("target_psychology") or {}).get("reader_emotions") for c in recent_window])
    baseline_tension = (baseline_ch.get("target_psychology") or {}).get("tension_curve") or {}
    recent_avg_tension = _avg_dict([(c.get("target_psychology") or {}).get("tension_curve") for c in recent_window])

    def _dropped(baseline_dict, recent_avg):
        out = []
        for k, v in (baseline_dict or {}).items():
            if k in confirmed or not isinstance(v, (int, float)) or v < _PROMISE_EMERGE_THRESHOLD:
                continue
            rv = recent_avg.get(k, 0)
            if v - rv >= _PROMISE_DROP_THRESHOLD:
                out.append({"label": k, "baseline": v, "recent_avg": rv})
        return out

    def _emerged(baseline_dict, recent_avg):
        baseline_keys = set((baseline_dict or {}).keys())
        return [{"label": k, "recent_avg": v} for k, v in recent_avg.items()
                if k not in baseline_keys and v >= _PROMISE_EMERGE_THRESHOLD and k not in confirmed]

    dropped_emotions = _dropped(baseline_emotions, recent_avg_emotions)
    emerged_emotions = _emerged(baseline_emotions, recent_avg_emotions)
    dropped_genres = sorted(g for g in (baseline_genres - genre_overlap) if g not in confirmed) if baseline_genres else []

    flags = []
    if dropped_emotions:
        flags.append({"kind": "dropped_emotion",
                     "text": (f"Chapter {baseline_ch['number']}'s opening promised **{', '.join(d['label'] for d in dropped_emotions)}** "
                             f"— largely absent across the last {len(recent_window)} planned chapters "
                             f"({', '.join(str(c['number']) for c in recent_window)}).")})
    if emerged_emotions:
        flags.append({"kind": "emerged_emotion",
                     "text": (f"Recent chapters lean into **{', '.join(e['label'] for e in emerged_emotions)}** "
                             f"— not part of chapter {baseline_ch['number']}'s opening promise.")})
    if dropped_genres:
        flags.append({"kind": "dropped_genre",
                     "text": (f"None of chapter {baseline_ch['number']}'s genre contracts ({', '.join(dropped_genres)}) "
                             f"recur in the arc(s) covering the recent window — possible tonal drift.")})

    return {
        "status": "drift_detected" if flags else "consistent",
        "baseline_chapter": baseline_ch["number"],
        "recent_window": [c["number"] for c in recent_window],
        "baseline_reader_emotions": baseline_emotions,
        "recent_avg_reader_emotions": recent_avg_emotions,
        "baseline_genre_signals": sorted(baseline_genres),
        "recent_genre_signals": sorted(recent_genres),
        "tension_shift": {"baseline": baseline_tension, "recent_avg": recent_avg_tension},
        "flags": flags,
    }


@router.get("/promise-check-status")
def promise_check_status(project_id: str):
    """Read-only: current drift report, no session/wizard state. Free — pure
    aggregation over already-planned chapter_skeletons, no LLM call."""
    project_file = CORPUS_PATH / "projects" / project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    return _compute_project_promise_drift(project)


class PromiseCheckRequest(BaseModel):
    project_id: str
    session_id: Optional[str] = None
    choice: Optional[str] = None   # "reanchor" | "confirm"


_PROMISE_SESSIONS: dict = {}


@router.post("/promise-check")
def promise_check(req: PromiseCheckRequest):
    """The wizard: walks each drift flag as an A/B choice —
    'reanchor' (add a standing craft_note reminding future chapters to bring
    the dropped element back — craft_notes already feeds every chapter-writing
    prompt as a MANDATORY style rule) or 'confirm' (accept the drift as the
    new normal — the label is added to promise_drift_confirmed so it stops
    being flagged). Zero LLM calls anywhere in this flow."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)

    if not req.session_id:
        report = _compute_project_promise_drift(project)
        if report.get("status") != "drift_detected":
            return {"ok": True, "done": True, "status": report.get("status"),
                    "message": "No drift flagged — nothing to walk through." if report.get("status") == "consistent"
                               else f"Not enough planned chapters yet ({report.get('chapters_available', 0)}/{_PROMISE_WINDOW + 2} needed)."}
        import uuid as _uuid
        sid = _uuid.uuid4().hex
        _PROMISE_SESSIONS[sid] = {"project_id": req.project_id, "flags": report["flags"], "idx": 0, "decisions": []}
    else:
        sid = req.session_id
        session = _PROMISE_SESSIONS.get(sid)
        if session is None:
            raise HTTPException(404, "Promise Check session not found or expired — start a new one.")
        if req.choice not in ("reanchor", "confirm"):
            raise HTTPException(400, "choice must be 'reanchor' or 'confirm'.")
        flag = session["flags"][session["idx"]]
        if req.choice == "reanchor":
            note = f"[Promise Check] {flag['text']} — bring this back into upcoming chapters."
            notes = project.get("craft_notes") or []
            if isinstance(notes, dict):
                # Named-section craft notes (see _craft_note_lines): Promise Check keeps
                # its notes in a list section of its own. append() on the dict crashed.
                pc = notes.get("promise_check")
                pc = pc if isinstance(pc, list) else ([pc] if isinstance(pc, str) and pc.strip() else [])
                if note not in pc:
                    pc.append(note)
                notes["promise_check"] = pc
            elif note not in notes:
                notes.append(note)
            project["craft_notes"] = notes
        else:
            label = flag.get("text", "")
            # Extract the bolded label(s) from the flag text as the confirmed key(s).
            for m in re.findall(r"\*\*(.+?)\*\*", label):
                for part in m.split(","):
                    part = part.strip()
                    if part:
                        confirmed = set(project.get("promise_drift_confirmed") or [])
                        confirmed.add(part)
                        project["promise_drift_confirmed"] = sorted(confirmed)
        session["decisions"].append({"flag": flag["text"], "choice": req.choice})
        session["idx"] += 1
        with open(project_file, "w", encoding="utf-8") as f:
            json.dump(project, f, indent=2, ensure_ascii=False)

    session = _PROMISE_SESSIONS[sid]
    if session["idx"] >= len(session["flags"]):
        n = len(session["decisions"])
        del _PROMISE_SESSIONS[sid]
        if n:
            _log_project_memory(req.project_id, "Promise Check",
                                "Walked drift flags; decisions: "
                                + " | ".join(f"{d['flag'][:60]} -> {d['choice']}" for d in session["decisions"])[:400])
        return {"ok": True, "done": True, "session_id": sid, "decisions_made": n}

    flag = session["flags"][session["idx"]]
    return {"ok": True, "done": False, "session_id": sid,
            "progress": f"Flag {session['idx'] + 1} of {len(session['flags'])}",
            "flag": flag["text"], "kind": flag["kind"],
            "options": [
                {"label": "Re-anchor", "description": "Add a standing note so upcoming chapters bring this back."},
                {"label": "Confirm intentional", "description": "This drift is deliberate — stop flagging it."},
            ]}


# ── LOCATION MAP ──────────────────────────────────────────────────────────
# A local-geography adjacency graph (NOT the grand-scale world_bible.key_locations
# — this is "what's near what, how long to get there") so a scene can't place a
# character somewhere impossible without the generator/shaping agent noticing.
# This is what was missing when a chapter had the protagonist "hauling water past
# the Sword Hall" after his sole assignment had already been reassigned to
# sweeping a separate, distant pavilion — nothing tracked that the two places
# were not adjacent and that duty no longer applied.

class LocationMapUpdateRequest(BaseModel):
    project_id: str
    location_map: list   # full replacement list — used by the Map tab for manual edit/delete


@router.post("/location-map-update")
def location_map_update(req: LocationMapUpdateRequest):
    """Manual edit endpoint for the Map tab."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    project["location_map"] = req.location_map
    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)
    return {"ok": True, "total": len(req.location_map)}


class LocationMapFixRequest(BaseModel):
    project_id: str
    contradiction_id: int


@router.post("/location-map-fix")
def location_map_fix(req: LocationMapFixRequest):
    """Resolve one flagged Map contradiction: an agent reads both chapters
    involved, decides which stated adjacency/distance is correct, edits the
    WRONG chapter's prose to match, and updates the location map. Same
    reversible pre-fix-archive pattern as facts_fix / Dialogue Shaping."""
    project_file = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    contras = project.get("location_map_contradictions") or []
    contra = next((c for c in contras if c.get("id") == req.contradiction_id), None)
    if not contra:
        raise HTTPException(404, f"Contradiction {req.contradiction_id} not found")
    if not _agent_cli_ready():
        raise HTTPException(400, "Fixing contradictions needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    ch_a, ch_b = contra["existing"]["chapter"], contra["new"]["chapter"]
    gen_dir = CORPUS_PATH / "generated" / pid
    _before_words = {}
    for n in (ch_a, ch_b):
        fp = gen_dir / f"ch{n:03d}_generated.txt"
        if fp.exists():
            _before_words[n] = len(fp.read_text(encoding="utf-8").split())
    report_path = f"projects/{pid}/_locationmap_fix_report.json"
    system = (
        "You are a continuity editor for a long-form web novel. You resolve a geography contradiction between two "
        "chapters by editing the chapter that is WRONG so it matches established local geography. You work with "
        "Read/Edit tools inside the workspace. Never ask questions; never output explanations; never print the "
        "report JSON to stdout — write it to the file named."
    )
    prompt = f"""Resolve this local-geography contradiction in project {pid}:

Locations: {contra['from']} → {contra['to']}
• Chapter {ch_a} states the relationship is: "{contra['existing']['relation']}"
• Chapter {ch_b} states the relationship is: "{contra['new']['relation']}"

STEP 1 — Read `generated/{pid}/ch{ch_a:03d}_generated.txt` and `generated/{pid}/ch{ch_b:03d}_generated.txt`. Determine which stated relationship is correct given how characters actually move through the scenes (usually the EARLIER chapter is canon and the later one drifted, but check for a deliberate reveal that changes the geography, e.g. a secret passage).
STEP 2 — Edit the chapter that is WRONG so its prose matches the correct relationship. Make the SMALLEST edit that fixes the contradiction. Do not touch the chapter that's already correct.
LENGTH BUDGET — prefer REPLACING/REWORDING the wrong claim's existing sentence(s) over inserting a new clarifying clause; each fix should be net-neutral or net-shorter in word count, not a pure addition. Multiple small insertions across a chapter compound into real, unwanted growth.
STEP 3 — Write your report to `{report_path}` (Write tool, overwrite if it exists) as ONLY this JSON:
{{"resolved": true, "fixed_chapter": {ch_a} or {ch_b}, "correct_relation": "the relationship as it now stands", "summary": "1 sentence on what was changed"}}
If both chapters need a small edit to reconcile, edit both and report fixed_chapter as a list."""

    full_report_path = CORPUS_PATH / report_path
    try:
        prompt += "".join(_word_budget_note(project, _n, words=_w, pid=pid, label="location map fix") for _n, _w in _before_words.items())
        _call_project_agent(prompt, system, pid, max_turns=25, timeout=420, resumable=True, resume_attempts=2,
                            success_file=full_report_path)
    except Exception as e:
        _log_error("location_map_fix", f"project={pid} contradiction={req.contradiction_id} error={e}")
        raise HTTPException(502, f"Fix agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")

    result = _read_agent_report(full_report_path, {"resolved": False, "fixed_chapter": None, "summary": ""})
    full_report_path.unlink(missing_ok=True)

    contra["status"] = "resolved" if result.get("resolved") else "fix_attempted"
    contra["resolution"] = result.get("summary", "")
    project["location_map_contradictions"] = contras

    if result.get("correct_relation"):
        location_map = project.get("location_map") or []
        for node in location_map:
            if node.get("name") == contra["from"]:
                for edge in (node.get("connections") or []):
                    if edge.get("to") == contra["to"]:
                        edge["relation"] = result["correct_relation"]
        project["location_map"] = location_map

    fixed = result.get("fixed_chapter")
    fixed_nums = fixed if isinstance(fixed, list) else [fixed] if fixed else []
    for _n in fixed_nums:
        if isinstance(_n, int): _index_chapter_async(pid, _n)
    for ledger_key in ("discovery_scanned", "facts_scanned", "location_map_scanned"):
        ledger = dict(project.get(ledger_key) or {})
        for n in fixed_nums:
            ledger.pop(str(n), None)
        project[ledger_key] = ledger

    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    growth_note = ""
    growth_flags = []
    for n in fixed_nums:
        before = _before_words.get(n)
        fp = gen_dir / f"ch{n:03d}_generated.txt"
        if before and fp.exists():
            after = len(fp.read_text(encoding="utf-8").split())
            delta = after - before
            if delta > max(10, before * 0.02):
                growth_flags.append(f"ch{n}: {before}→{after} words (+{delta})")
    if growth_flags:
        growth_note = " ⚠ GREW: " + "; ".join(growth_flags)

    _log_project_memory(pid, "Location Map contradiction fixed",
                        f"{contra['from']} → {contra['to']}: {result.get('summary', '')}"
                        + (f" (edited ch{fixed_nums})" if fixed_nums else "") + growth_note)

    return {"ok": True, "resolved": result.get("resolved", False), "fixed_chapter": fixed,
            "summary": result.get("summary", ""), "contradiction_id": req.contradiction_id,
            "growth_warning": growth_flags or None}


class LocationMapExtractRequest(BaseModel):
    project_id: str
    full: bool = False


@router.post("/location-map-extract")
def location_map_extract(req: LocationMapExtractRequest):
    """Scan generated chapters for LOCAL geography: named places the characters
    move through, and how they relate to each other (adjacent, visible-from,
    walking distance, same-building). INCREMENTAL like Discovery/Facts (mtime
    ledger in project.location_map_scanned). New nodes/edges are merged into
    project.location_map by name; conflicting distance/adjacency claims are
    flagged as contradictions, same as Facts."""
    proj_dir = CORPUS_PATH / "projects" / req.project_id / "project.json"
    if not proj_dir.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    with open(proj_dir, encoding="utf-8") as f:
        project = json.load(f)
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    if not gen_dir.exists() or not list(gen_dir.glob("ch*_generated.txt")):
        raise HTTPException(400, "No generated chapters to scan yet.")
    if not _agent_cli_ready():
        raise HTTPException(400, "Location Map extraction needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    title = project.get("title", "Untitled")

    scanned = dict(project.get("location_map_scanned") or {})
    to_scan = []
    for f in sorted(gen_dir.glob("ch*_generated.txt")):
        try:
            num = int(f.name.replace("ch", "").replace("_generated.txt", ""))
        except Exception:
            continue
        mt = int(f.stat().st_mtime)
        rec = scanned.get(str(num))
        if req.full or rec is None or mt > int(rec):
            to_scan.append((num, f.name, mt))
    if not to_scan:
        return {"ok": True, "total": 0, "scanned": [], "added": [], "contradictions": [],
                "message": "All chapters already scanned — nothing new since the last Map extraction."}

    scan_list = "\n".join(f"• `generated/{pid}/{fname}` (chapter {num})" for num, fname, _ in to_scan)
    existing_map = project.get("location_map") or []
    existing_names = [n.get("name") for n in existing_map if n.get("name")]
    has_facts = bool(project.get("facts_log"))
    report_path = f"projects/{pid}/_locationmap_report.json"

    system = f"""You are the LOCAL GEOGRAPHY engine for the web novel "{title}". You track the SMALL-SCALE map — the town/sect/building-level places characters actually walk between — not the grand story-world regions in world_bible.key_locations (ignore that field; it is not local geography). Precision here prevents scenes that accidentally place a character somewhere geographically impossible (e.g. two duties in two distant places at once, or a "nearby" location that was never established as near anything).

BUILD ONLY FROM WHAT THE CHAPTERS ACTUALLY SHOW. Do not infer or invent a location or connection the prose doesn't state or clearly enact through character movement — an incomplete map is fine and expected; a wrong map is not.

Read with your tools (read-only):
• ONLY these chapters — every other chapter was already scanned on a previous run, do NOT read them:
{scan_list}
{"• `projects/" + pid + "/project.json`'s `facts_log` — cross-check any location/possession/assignment facts already on record so your connections don't contradict them." if has_facts else ""}

Already-known locations (do not re-add these, only add NEW ones or NEW connections involving them): {", ".join(existing_names) or "(none yet)"}

For every named local place characters are actually IN or MOVE BETWEEN (a building, a courtyard, a wall, a path, a room, a specific spot), extract:
1. The location itself (if new).
2. Its relationship to other named locations mentioned in the same scene — adjacency, walking distance/time, visibility ("can see X from Y"), or "same building/complex as X". Only record a relationship the text ACTUALLY states or clearly implies by the scene's action — never assume proximity.

Write your report to `{report_path}` (Write tool, overwrite if it exists) as ONLY this JSON:
{{"locations": [{{"name": "The Old Scripture Pavilion", "chapter": 1, "description": "condemned three-story building, Zhou Tien's sole sweeping assignment"}}],
 "connections": [{{"from": "The Old Scripture Pavilion", "to": "Sword Hall practice ground", "relation": "shares an east wall — visible over a collapsed section", "chapter": 6}}]}}
Rules: `relation` is a short factual phrase (adjacent/shares a wall/visible from/X minutes' walk/same building). Skip vague scene-setting. If a chapter's action contradicts a distance/adjacency you'd expect from an earlier chapter, still just report what THIS chapter states — contradiction resolution happens outside your task."""

    try:
        found = _run_readonly_agent_resumable(
            system, f"Scan the {len(to_scan)} listed chapter(s) and write the location-map report now.",
            report_path, {"locations": [], "connections": []}, max_turns=40, timeout=600, resume_attempts=2)
    except Exception as e:
        raise HTTPException(502, f"Location Map extraction agent failed: {str(e)[:200]}. Details logged to ~/.noveltea-engine/errors.log")

    location_map = project.get("location_map") or []
    by_name = {n.get("name", "").strip().lower(): n for n in location_map if n.get("name")}
    added_locs, added_conns, contradictions = [], [], []
    persisted_contras = project.get("location_map_contradictions") or []
    next_contra_id = max((c.get("id", 0) for c in persisted_contras), default=0) + 1

    for loc in (found.get("locations") or []):
        if not isinstance(loc, dict) or not loc.get("name"):
            continue
        key = loc["name"].strip().lower()
        if key in by_name:
            continue
        entry = {"name": loc["name"].strip(), "chapter": loc.get("chapter"),
                 "description": loc.get("description", ""), "connections": []}
        location_map.append(entry)
        by_name[key] = entry
        added_locs.append(entry["name"])

    for conn in (found.get("connections") or []):
        if not isinstance(conn, dict) or not conn.get("from") or not conn.get("to"):
            continue
        from_key, to_key = conn["from"].strip().lower(), conn["to"].strip().lower()
        from_node = by_name.get(from_key)
        if not from_node:
            # connection references a location not captured as a node this pass — create a stub
            from_node = {"name": conn["from"].strip(), "chapter": conn.get("chapter"), "description": "", "connections": []}
            location_map.append(from_node)
            by_name[from_key] = from_node
            added_locs.append(from_node["name"])
        new_edge = {"to": conn["to"].strip(), "relation": conn.get("relation", ""), "chapter": conn.get("chapter")}
        existing_edges = from_node.setdefault("connections", [])
        prior = next((e for e in existing_edges if e.get("to", "").strip().lower() == to_key), None)
        if prior:
            if prior.get("relation", "").strip().lower() != new_edge["relation"].strip().lower():
                contra = {
                    "id": next_contra_id, "status": "open",
                    "from": from_node["name"], "to": conn["to"].strip(),
                    "existing": {"chapter": prior.get("chapter"), "relation": prior.get("relation")},
                    "new": {"chapter": conn.get("chapter"), "relation": new_edge["relation"]},
                }
                next_contra_id += 1
                contradictions.append(contra)
                persisted_contras.append(contra)
            continue
        existing_edges.append(new_edge)
        added_conns.append(f"{from_node['name']} → {conn['to'].strip()}")

    project["location_map"] = location_map
    project["location_map_contradictions"] = persisted_contras
    for num, _fname, mt in to_scan:
        scanned[str(num)] = mt
    project["location_map_scanned"] = scanned

    with open(proj_dir, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    ch_label = ", ".join(f"ch{num}" for num, _f, _m in to_scan)
    contra_note = ""
    if contradictions:
        contra_note = " ⚠ POSSIBLE CONTRADICTIONS: " + "; ".join(
            f"{c['from']}→{c['to']}: ch{c['existing']['chapter']} said \"{c['existing']['relation']}\" "
            f"vs. ch{c['new']['chapter']} \"{c['new']['relation']}\"" for c in contradictions)
    _log_project_memory(pid, "Location Map extraction",
                        f"Scanned {ch_label}. Added {len(added_locs)} locations, {len(added_conns)} connections." + contra_note)

    return {"ok": True, "total": len(added_locs) + len(added_conns), "added_locations": added_locs,
            "added_connections": added_conns, "contradictions": contradictions,
            "scanned": [num for num, _f, _m in to_scan]}


def _location_map_block(project: dict, max_nodes: int = 40) -> str:
    """Compact local-geography reference injected into generation/shaping prompts
    so a scene can't place a character somewhere geographically inconsistent
    with what's already established (wrong duty, impossible adjacency, etc)."""
    location_map = project.get("location_map") or []
    if not location_map:
        return ""
    nodes = location_map[:max_nodes]
    lines = ["━━ LOCAL GEOGRAPHY (established locations and how they relate — do not contradict) ━━"]
    for n in nodes:
        desc = f" — {n['description']}" if n.get("description") else ""
        lines.append(f"  • {n.get('name', '?')}{desc}")
        for c in (n.get("connections") or [])[:6]:
            lines.append(f"      ↳ {c.get('relation', 'connected to')}: {c.get('to', '?')}")
    return "\n".join(lines)


class CorpusSuggestRequest(BaseModel):
    project_id: str
    full: bool = False       # True = rescan every chapter, ignoring the ledger


@router.post("/corpus-suggestions")
def corpus_suggestions(req: CorpusSuggestRequest):
    """For each written chapter not yet reviewed, compare it against the SAME
    chapter-number range across EVERY corpus novel that has it extracted —
    reading their full craft schema (reader_psychology, author_intent, prose
    samples, reveals, schemes, humor) — and apply concrete prose improvements.
    INCREMENTAL like Discovery (own ledger, mtime-based). Any chapter this
    edits has its Discovery ledger entry cleared, since the text changed and
    is worth re-harvesting."""
    key = (req.project_id, "suggestions")
    with _ACTIVE_GENERATIONS_LOCK:
        _ACTIVE_GENERATIONS.add(key)
    try:
        return _corpus_suggestions_impl(req)
    finally:
        with _ACTIVE_GENERATIONS_LOCK:
            _ACTIVE_GENERATIONS.discard(key)


def _corpus_suggestions_impl(req: CorpusSuggestRequest):
    proj_dir = CORPUS_PATH / "projects" / req.project_id
    project_file = proj_dir / "project.json"
    if not project_file.exists():
        raise HTTPException(404, f"Project {req.project_id} not found")
    gen_dir = CORPUS_PATH / "generated" / req.project_id
    if not gen_dir.exists() or not list(gen_dir.glob("ch*_generated.txt")):
        raise HTTPException(400, "No generated chapters to review yet.")
    with open(project_file, encoding="utf-8") as f:
        project = json.load(f)
    if not _agent_cli_ready():
        raise HTTPException(400, "Corpus Suggestions needs the selected Agent Engine CLI (Claude Code, Gemini, Qoder, or Kimi Code — install it or switch engines in Settings → CLI Accounts).")

    pid = req.project_id
    title = project.get("title", "Untitled")
    _progress_clear(pid)
    _progress_log(pid, "CORPUS SUGGESTIONS: checking which chapters need review"
                       + (" (full re-review)" if req.full else "") + "…")

    # ── incremental ledger, separate from Discovery's ──
    reviewed = dict(project.get("corpus_suggestions_reviewed") or {})
    to_review = []
    for f in sorted(gen_dir.glob("ch*_generated.txt")):
        try:
            num = int(f.name.replace("ch", "").replace("_generated.txt", ""))
        except Exception:
            continue
        mt = int(f.stat().st_mtime)
        rec = reviewed.get(str(num))
        if req.full or rec is None or mt > int(rec):
            to_review.append((num, f.name, mt))
    if not to_review:
        _progress_log(pid, "CORPUS SUGGESTIONS: all chapters already reviewed — nothing new", "success")
        return {"ok": True, "total": 0, "reviewed": [], "changes": [],
                "message": "All written chapters already reviewed against the corpus — nothing new."}

    ch_nums = [n for n, _f, _m in to_review]
    lo, hi = min(ch_nums), max(ch_nums)
    _progress_log(pid, f"CORPUS SUGGESTIONS: {len(to_review)} chapter(s) to review — "
                       f"{', '.join(f'ch{n}' for n in ch_nums[:12])}{'…' if len(ch_nums) > 12 else ''} "
                       f"(range {lo}-{hi})")

    # ── EVERY corpus novel that has this chapter range extracted (not a sample) ──
    registry_path = NOVELS_PATH / "registry.json"
    novel_ids = []
    if registry_path.exists():
        try:
            reg = json.loads(registry_path.read_text(encoding="utf-8-sig"))
            for nov in reg.get("novels", []):
                nid = nov.get("id", "")
                dd = NOVELS_PATH / nid / "deltas_v3"
                if dd.exists() and any((dd / f"ch{c}.json").exists() for c in range(lo, hi + 1)):
                    novel_ids.append(nid)
        except Exception:
            pass
    novel_ids.sort()
    if not novel_ids:
        _progress_log(pid, f"CORPUS SUGGESTIONS: no corpus novels have chapters {lo}-{hi} extracted", "error")
        raise HTTPException(400, f"No corpus novels have chapters {lo}-{hi} extracted yet.")
    _progress_log(pid, f"CORPUS SUGGESTIONS: comparing against {len(novel_ids)} corpus novel(s) — {', '.join(novel_ids)}")

    review_list = "\n".join(f"• `generated/{pid}/{fname}` (chapter {num})" for num, fname, _ in to_review)
    novel_list = "\n".join(f"• {nid}" for nid in novel_ids)

    system = f"""You are the CORPUS SUGGESTIONS engine for the web novel "{title}". Your job: make each listed chapter genuinely better prose, using real published novels as your craft reference — never copying their names, plot, or text, only their TECHNIQUE.

Read with your tools (read-only):
• The project's chapters to review, ONLY these — every other chapter was already reviewed on a previous run:
{review_list}
• The SAME chapter-number range ({lo}-{hi}) from these corpus novels under `novels/<id>/` — for each, read the extracted schema for chapters {lo}-{hi}: `reader_psychology/chapters.json` (tension_curve, reader_emotions, payoff_categories), `author_intent/chapters.json` (author_goal, strategy_notes), `prose/samples.json` (style_notes, narrative_distance), `reveals/log.json`, `schemes/instances.json`, `humor/instances.json` — filter each to entries whose chapter/source_chapter falls in {lo}-{hi}:
{novel_list}
• The project's own `projects/{pid}/project.json` — characters, world_bible, systems, craft_notes AND critique_notes (the author's mandatory style rules — critique_notes are standing rules distilled from past chapter critiques via the Critique tab, same mandatory weight as craft_notes — any edit MUST still follow both) — and chapter_skeletons for the chapters under review, so your edits stay within the intended plot.

For EACH project chapter under review:
1. Build a craft picture from the corpus range: how do strong novels pace tension across this exact chapter range, what reveal/payoff density do they hit, how much reader-psychology work (dread, hope, catharsis) do they do, how do they build humor/schemes here.
2. Compare the project chapter's own tension, event density, and craft against that picture.
3. If there's a concrete, specific improvement — sharper hook, better-paced reveal, tighter dialogue, a beat that's flat compared to what the corpus range achieves, or a continuity/logic wart (a contradiction, a flat introduction, a missing transition) — apply it directly by editing the chapter file. Small, surgical edits preferred over rewrites, but you are FREE TO INVENT when invention is the real fix: a new minor character, a new named technique/item/location, a new aside or beat — anything that makes the chapter and the surrounding story fit together better. Draw inspiration from the corpus range's own approach to this same kind of beat (how it introduces a minor character, how it hangs a piece of worldbuilding on a scene) without ever copying its names, plot, or text — original, inspired-by, never lifted. You are not limited to what's already in project.json; invent whatever the story needs. Preserve the core plot facts and each character's established voice — you are free to add and enrich, not to reverse established outcomes or rewrite who someone fundamentally is.
4. If a chapter is already strong and needs no change, make NO edit to it — do not touch files unnecessarily.

Respect `craft_notes` AND `critique_notes` in project.json absolutely (dialogue attribution, ensemble scenes, italics for inner thought, etc.; critique_notes' `rule` fields are standing craft rules the author distilled from past chapter feedback) in anything you write. Anything you invent (new characters, techniques, items, areas) will be picked up by a separate Discovery pass and folded into the planning tabs automatically — you do not need to update project.json yourself, just write it into the chapter.

When finished, output ONLY this JSON summarizing what you changed (no fences, no commentary):
{{"changes": [{{"chapter": 1, "summary": "one sentence describing the specific craft fix made", "invented": ["any new character/technique/item/location name introduced, if any"], "inspired_by": ["novel_id", ...]}}]}}

If a chapter needed no edit, do not include it in "changes". Empty array is fine and expected for some chapters."""

    review_prompt = (f"Review the {len(to_review)} listed chapter(s) against the corpus range {lo}-{hi} and apply any "
                     f"concrete craft improvements now.")
    # every chapter this edits is counted first (author's rule for post-generation operations that can change length)
    review_prompt += "".join(_word_budget_note(project, num, _read_text_safe(gen_dir / fname), pid=pid,
                                               label="corpus suggestions") for num, fname, _m in to_review)

    def _review_claude():
        return _run_claude_cli(
            ["--add-dir", str(CORPUS_PATH), "--max-turns", "60",
             "--allowedTools", "Read,Grep,Glob,Edit,Write",
             f"--disallowedTools",
             ",".join([f"Edit({n}/**)" for n in ["novels", "raw", "accounts"]]
                      + [f"Write({n}/**)" for n in ["novels", "raw", "accounts"]]
                      + ["Read(accounts/**)", "Grep(accounts/**)", "Glob(accounts/**)",
                         "Read(.env)", "Read(.env.*)", "Grep(.env)", "Grep(.env.*)"]),
             "--system-prompt", system],
            review_prompt, timeout=900, cwd=CORPUS_PATH, abort_key=(pid, "suggestions"),
        )

    def _review_gemini():
        gem_system = system + (f"\n\nSTRICT WRITE SCOPE: you may only edit chapter files under "
                               f"{CORPUS_PATH / 'generated' / pid}. The corpus novels/ and everything "
                               f"else in the workspace is READ-ONLY reference.")
        return _run_gemini_cli_resumable(_gemini_path_note() + review_prompt, gem_system, timeout=900,
                                         cwd=CORPUS_PATH / "generated" / pid,
                                         include_dirs=_gemini_corpus_include_dirs(),
                                         resume_attempts=1)

    def _review_qoder():
        qod_system = system + (f"\n\nSTRICT WRITE SCOPE: you may only edit chapter files under "
                               f"{CORPUS_PATH / 'generated' / pid}. The corpus novels/ and everything "
                               f"else in the workspace is READ-ONLY reference.")
        return _run_qoder_agent(_gemini_path_note() + review_prompt, qod_system, timeout=900,
                                cwd=CORPUS_PATH / "generated" / pid,
                                include_dirs=_gemini_corpus_include_dirs(),
                                resume_attempts=1, allowed_tools=["Read", "Grep", "Glob", "Edit", "Write"])

    def _review_kimi():
        kim_system = system + (f"\n\nSTRICT WRITE SCOPE: you may only edit chapter files under "
                               f"{CORPUS_PATH / 'generated' / pid}. The corpus novels/ and everything "
                               f"else in the workspace is READ-ONLY reference.")
        return _run_kimi_agent(_gemini_path_note() + review_prompt, kim_system, timeout=900,
                                       cwd=CORPUS_PATH / "generated" / pid,
                                       include_dirs=_gemini_corpus_include_dirs(),
                                       resume_attempts=1)

    _progress_log(pid, "CORPUS SUGGESTIONS: 🤖 agent applying craft fixes chapter by chapter…")
    def _review_nemotron():
        nem_system = system + (f"\n\nSTRICT WRITE SCOPE: you may only edit chapter files under "
                               f"{CORPUS_PATH / 'generated' / pid}. The corpus novels/ and everything "
                               f"else in the workspace is READ-ONLY reference.")
        return _run_nemotron_agent(_gemini_path_note() + review_prompt, nem_system, timeout=900)

    _t0 = _time.time()
    raw = _dispatch_engines(pid, _review_claude, _review_gemini, _review_qoder, _review_kimi,
                            _review_nemotron)
    secs = round(_time.time() - _t0)
    parsed = False
    try:
        result = _parse_json_from_text(raw)
        parsed = isinstance(result, dict) and isinstance(result.get("changes"), list)
    except Exception:
        result = {"changes": []}
    if not isinstance(result, dict):
        result = {"changes": []}
    changes = [c for c in (result.get("changes") or []) if isinstance(c, dict) and c.get("chapter")]
    # chapters whose file really changed during the run (the agent edits them directly), whatever it replied
    edited = sorted(n for n, fname, old_mt in to_review if (gen_dir / fname).exists() and int((gen_dir / fname).stat().st_mtime) > old_mt)
    # an agent that read nothing replies in seconds: reading a chapter plus the same chapters of every corpus novel
    # takes far longer than this, so a fast "nothing to change" is unverified, not a verdict
    too_fast = secs < 25
    verified = bool(changes) or bool(edited) or (parsed and not too_fast)
    try:      # what it actually said, kept so a run can be judged afterwards
        rd = proj_dir / "_suggestion_runs"
        rd.mkdir(exist_ok=True)
        (rd / f"{_time.strftime('%Y%m%d_%H%M%S')}.json").write_text(json.dumps({
            "seconds": secs, "chapters": [n for n, _f, _m in to_review], "novels": novel_ids, "parsed": parsed,
            "files_edited": edited, "verified": verified, "reply": (raw or "")[:30000]}, ensure_ascii=False, indent=1), encoding="utf-8")
    except Exception:
        pass
    if changes:
        _progress_log(pid, f"CORPUS SUGGESTIONS: {len(changes)} chapter(s) improved in {secs}s — "
                           + "; ".join(f"ch{c['chapter']}: {c.get('summary','')[:80]}" for c in changes), "success")
    elif edited:
        _progress_log(pid, f"CORPUS SUGGESTIONS: ch{', ch'.join(map(str, edited))} was edited during the run ({secs}s) but the "
                           f"agent's summary wasn't readable — see projects/{pid}/_suggestion_runs/", "warn")
    elif not parsed:
        _progress_log(pid, f"CORPUS SUGGESTIONS: the agent's reply wasn't the expected summary (after {secs}s), so nothing is "
                           f"known about this review. Not marked reviewed — run it again. Reply kept in projects/{pid}/_suggestion_runs/",
                      "error")
    elif too_fast:
        _progress_log(pid, f"CORPUS SUGGESTIONS: the agent answered 'no changes' after only {secs}s — too fast to have read the "
                           f"chapter and the same chapters of {len(novel_ids)} corpus novels. Not marked reviewed — run it again.", "warn")
    else:
        _progress_log(pid, f"CORPUS SUGGESTIONS: no changes needed after {secs}s — chapters already strong", "success")

    if not verified:
        return {"ok": True, "total": 0, "changes": [], "reviewed": [], "novels_compared": novel_ids, "range": [lo, hi],
                "unverified": True, "seconds": secs,
                "message": ("The agent's reply wasn't readable, so this review didn't count. Run it again." if not parsed else
                            f"The agent said 'no changes' after only {secs}s, which is too fast to have really read the chapter "
                            "and the corpus novels, so it was not marked reviewed. Run it again.")}

    # snapshot AFTER the edits (agent already wrote files directly) so Undo
    # restores to pre-review state; still useful even though writes already landed
    snap_id = _snapshot_project(pid)

    # record the review ledger for every chapter we asked about, regardless of
    # whether it got an edit — re-read mtimes since the agent may have touched files
    changed_nums = {c["chapter"] for c in changes} | set(edited)
    for _n in changed_nums:
        if isinstance(_n, int): _index_chapter_async(pid, _n)
    for num, fname, _old_mt in to_review:
        p = gen_dir / fname
        reviewed[str(num)] = int(p.stat().st_mtime) if p.exists() else _old_mt
    project["corpus_suggestions_reviewed"] = reviewed

    # any chapter actually edited: clear its Discovery ledger entry so the next
    # Discovery run re-scans it (new/changed content may need harvesting)
    disc = dict(project.get("discovery_scanned") or {})
    cleared = [n for n in changed_nums if str(n) in disc]
    for n in cleared:
        disc.pop(str(n), None)
    project["discovery_scanned"] = disc

    with open(project_file, "w", encoding="utf-8") as f:
        json.dump(project, f, indent=2, ensure_ascii=False)

    ch_label = ", ".join(f"ch{n}" for n, _f, _m in to_review)
    _log_project_memory(
        pid, "Corpus Suggestions pass",
        f"Reviewed {ch_label} against corpus range {lo}-{hi} in {', '.join(novel_ids)}. "
        + (f"{len(changes)} chapter(s) improved: "
           + "; ".join(f"ch{c['chapter']} ({c['summary']})" for c in changes)
           if changes else "No changes needed — chapters already strong.")
        + (f" Discovery ledger cleared for: {', '.join(f'ch{n}' for n in sorted(cleared))}."
           if cleared else ""))

    return {"ok": True, "total": len(changes), "changes": changes,
            "reviewed": [n for n, _f, _m in to_review],
            "novels_compared": novel_ids, "range": [lo, hi],
            "discovery_reset": sorted(cleared), "snapshot_id": snap_id}


class MemoryLogRequest(BaseModel):
    project_id: str
    kind: str
    text: str


@router.post("/memory-log")
def memory_log(req: MemoryLogRequest):
    """Client-side hook into the project memory log (e.g. chat patches applied
    in the editor without a backend round-trip)."""
    _log_project_memory(req.project_id, req.kind[:80], req.text[:1400])
    return {"ok": True}


class ProjectChatUndoRequest(BaseModel):
    project_id: str
    snapshot_id: str


@router.post("/project-chat/undo")
def project_chat_undo(req: ProjectChatUndoRequest):
    """Undo a whole-project assistant turn by restoring its pre-turn snapshot."""
    _restore_project(req.project_id, req.snapshot_id)
    return {"ok": True, "restored": True}
